INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a20b44-5212-4aad-9948-95708855ba5a', '哭嚴僕射歸櫬', '哭嚴僕射归櫬', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["素幔隨流水，歸舟返舊京。","老親如宿昔，部曲異平生。","風送蛟龍雨，天長驃騎營。","一哀三峽暮，遺後見君情。"]', '["素幔隨流水，归舟返旧京。","老親如宿昔，部曲異平生。","风送蛟龙雨，天长驃騎營。","一哀三峽暮，遺後见君情。"]', '诗', 'shi', '', NULL, '哭嚴僕射歸櫬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57d32a1-4b7d-4827-9b1f-cd8077a3604f', '宴戎州楊使君東樓', '宴戎州楊使君东楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["勝絕驚身老，情忘發興奇。","座從歌妓密，樂任主人爲。","重碧拈春酒，輕紅擘荔枝。","樓高欲愁思，橫笛未休吹。"]', '["勝絕驚身老，情忘發兴奇。","座從歌妓密，乐任主人爲。","重碧拈春酒，轻紅擘荔枝。","楼高欲愁思，橫笛未休吹。"]', '诗', 'shi', '', NULL, '宴戎州楊使君東樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c5694c-6914-48bc-97ae-7c2d99bf7e07', '渝州候嚴六侍御不到先下峽', '渝州候嚴六侍御不到先下峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道乘驄發，沙邊待至今。","不知雲雨散，虛費短長吟。","山帶烏蠻闊，江連白帝深。","船經一柱觀，留眼共登臨。"]', '["闻道乘驄發，沙邊待至今。","不知云雨散，虛費短长吟。","山带烏蠻闊，江連白帝深。","船經一柱观，留眼共登臨。"]', '诗', 'shi', '', NULL, '渝州候嚴六侍御不到先下峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1091cece-e986-4808-af31-676ce83a1083', '撥悶', '撥悶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道雲安麴米春，纔傾一醆即醺人。","乘舟取醉非難事，下峽消愁定幾巡。","長年三老遙憐汝，棙柁開頭捷有神。","已辦青錢防雇直，當令美味入吾脣。"]', '["闻道云安麴米春，纔傾一醆即醺人。","乘舟取醉非难事，下峽消愁定幾巡。","长年三老遙怜汝，棙柁开头捷有神。","已辦青錢防雇直，當令美味入吾脣。"]', '诗', 'shi', '', NULL, '撥悶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0a7058-2f6e-44ac-abe0-e04a56a1a694', '聞高常侍亡', '闻高常侍亡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歸朝不相見，蜀使忽傳亡。","虛歷金華省，何殊地下郎。","致君丹檻折，哭友白雲長。","獨步詩名在，秪令故舊傷。"]', '["归朝不相见，蜀使忽傳亡。","虛歷金华省，何殊地下郎。","致君丹檻折，哭友白云长。","独步诗名在，秪令故旧傷。"]', '诗', 'shi', '', NULL, '聞高常侍亡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d17152-8094-4bb1-bfad-079daf16d81b', '宴忠州使君姪宅', '宴忠州使君姪宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["出守吾家姪，殊方此日歡。","自須遊阮巷，不是怕湖灘。","樂助長歌逸，杯饒旅思寬。","昔曾如意舞，牽率強爲看。"]', '["出守吾家姪，殊方此日歡。","自須游阮巷，不是怕湖灘。","乐助长歌逸，杯饒旅思寬。","昔曾如意舞，牽率強爲看。"]', '诗', 'shi', '', NULL, '宴忠州使君姪宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9fb2949-5ca8-4ac5-a00a-c35b190d3881', '禹廟', '禹廟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["禹廟空山裏，秋風落日斜。","荒庭垂橘柚，古屋畫龍蛇。","雲氣生虛壁，江聲走白沙。","早知乘四載，疏鑿控三巴。"]', '["禹廟空山裏，秋风落日斜。","荒庭垂橘柚，古屋畫龙蛇。","云氣生虛壁，江声走白沙。","早知乘四載，疏鑿控三巴。"]', '诗', 'shi', '', NULL, '禹廟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcca940-28ef-4cc4-b493-d692dc423aee', '題忠州龍興寺所居院壁', '題忠州龙兴寺所居院壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["忠州三峽內，井邑聚雲根。","小市常爭米，孤城早閉門。","空看過客淚，莫覓主人恩。","淹泊仍愁虎，深居賴獨園。"]', '["忠州三峽內，井邑聚云根。","小市常爭米，孤城早閉门。","空看過客泪，莫覓主人恩。","淹泊仍愁虎，深居賴独园。"]', '诗', 'shi', '', NULL, '題忠州龍興寺所居院壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96506ea-e8ac-47e0-a0a6-ccd306e56645', '旅夜書懷', '旅夜书懷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["細草微風岸，危檣獨夜舟。","星垂平野闊，月湧大江流。","名豈文章著，官因老病休。","飄飄何所似，天地一沙鷗。"]', '["細草微风岸，危檣独夜舟。","星垂平野闊，月湧大江流。","名豈文章著，官因老病休。","飄飄何所似，天地一沙鷗。"]', '诗', 'shi', '', NULL, '旅夜書懷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08a9f3c-8345-4aa6-b0ee-ac8be76a1d93', '別常徵君', '別常徵君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兒扶猶杖策，臥病一秋強。","白髮少新洗，寒衣寬總長。","故人憂見及，此別淚相忘。","各逐萍流轉，來書細作行。"]', '["兒扶猶杖策，臥病一秋強。","白髮少新洗，寒衣寬總长。","故人憂见及，此別泪相忘。","各逐萍流轉，来书細作行。"]', '诗', 'shi', '', NULL, '別常徵君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2024061f-63cc-4adf-b3bc-b321eb7d282e', '三絕句 一', '三絕句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["前年渝州殺刺史，今年開州殺刺史。","羣盜相隨劇虎狼，食人更肯留妻子。"]', '["前年渝州殺刺史，今年开州殺刺史。","羣盜相隨劇虎狼，食人更肯留妻子。"]', '诗', 'shi', '', NULL, '三絕句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce14cdf4-17a0-4a0f-b49e-cec74b99d7c1', '三絕句 二', '三絕句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二十一家同入蜀，惟殘一人出駱谷。","自說二女齧臂時，回頭却向秦雲哭。"]', '["二十一家同入蜀，惟殘一人出駱谷。","自说二女齧臂时，回头却向秦云哭。"]', '诗', 'shi', '', NULL, '三絕句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff9cf4e-3d22-4ca6-a7e8-54ebd99fccb0', '三絕句 三', '三絕句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["殿前兵馬雖驍雄，縱暴略與羌渾同。","聞道殺人漢水上，婦女多在官軍中。"]', '["殿前兵马雖驍雄，縱暴略與羌渾同。","闻道殺人漢水上，婦女多在官軍中。"]', '诗', 'shi', '', NULL, '三絕句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48a84c4-9481-4d6a-8f18-b7890f940d88', '十二月一日三首 一', '十二月一日三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今朝臘月春意動，雲安縣前江可憐。","一聲何處送書鴈，百丈誰家上水船。","未將梅蘂驚愁眼，要取楸花媚遠天。","明光起草人所羨，肺病幾時朝日邊。"]', '["今朝臘月春意动，云安縣前江可怜。","一声何处送书鴈，百丈誰家上水船。","未將梅蘂驚愁眼，要取楸花媚远天。","明光起草人所羨，肺病幾时朝日邊。"]', '诗', 'shi', '', NULL, '十二月一日三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('989669f3-7208-4452-b8b1-bc7e258a74be', '十二月一日三首 二', '十二月一日三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒輕市上山煙碧，日滿樓前江霧黃。","負鹽出井此谿女，打鼓發船何郡郎。","新亭舉目風景切，茂陵著書消渴長。","春花不愁不爛漫，楚客唯聽棹相將。"]', '["寒轻市上山煙碧，日满楼前江霧黄。","負鹽出井此谿女，打鼓發船何郡郎。","新亭舉目风景切，茂陵著书消渴长。","春花不愁不爛漫，楚客唯听棹相將。"]', '诗', 'shi', '', NULL, '十二月一日三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed35d16-2972-44be-beb9-cc6d586ab0f2', '十二月一日三首 三', '十二月一日三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["即看燕子入山扉，豈有黃鸝歷翠微。","短短桃花臨水岸，輕輕柳絮點人衣。","春來準擬開懷久，老去親知見面稀。","他日一杯難強進，重嗟筋力故山違。"]', '["即看燕子入山扉，豈有黄鸝歷翠微。","短短桃花臨水岸，轻轻柳絮点人衣。","春来準擬开懷久，老去親知见面稀。","他日一杯难強進，重嗟筋力故山違。"]', '诗', 'shi', '', NULL, '十二月一日三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49577c84-9adc-4983-96ef-81d474492aa9', '又雪', '又雪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南雪不到地，青崖霑未消。","微微向日薄，脈脈去人遙。","冬熱鴛鴦病，峽深豺虎驕。","愁邊有江水，焉得北之朝。"]', '["南雪不到地，青崖霑未消。","微微向日薄，脈脈去人遙。","冬熱鴛鴦病，峽深豺虎驕。","愁邊有江水，焉得北之朝。"]', '诗', 'shi', '', NULL, '又雪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8603405-d351-470e-9a35-421734940554', '奉漢中王手札', '奉漢中王手札', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["國有乾坤大，王今叔父尊。","剖符來蜀道，歸蓋取荆門。","峽險通舟過，江長注海奔。","主人留上客，避暑得名園。","前後緘書報，分明饌玉恩。","天雲浮絕壁，風竹在華軒。","已覺良宵永，何看駭浪翻。","入期朱邸雪，朝傍紫微垣。","枚乘文章老，河間禮樂存。","悲秋宋玉宅，失路武陵源。","淹薄俱崖口，東西異石根。","夷音迷咫尺，鬼物傍黃昏。","犬馬誠爲戀，狐貍不足論。","從容草奏罷，宿昔奉清罇。"]', '["国有乾坤大，王今叔父尊。","剖符来蜀道，归蓋取荆门。","峽險通舟過，江长注海奔。","主人留上客，避暑得名园。","前後緘书報，分明饌玉恩。","天云浮絕壁，风竹在华軒。","已覺良宵永，何看駭浪翻。","入期朱邸雪，朝傍紫微垣。","枚乘文章老，河间禮乐存。","悲秋宋玉宅，失路武陵源。","淹薄俱崖口，东西異石根。","夷音迷咫尺，鬼物傍黄昏。","犬马誠爲戀，狐貍不足論。","從容草奏罷，宿昔奉清罇。"]', '诗', 'shi', '', NULL, '奉漢中王手札 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac1b352-d7b5-4be4-bf0d-2b3f0935e340', '贈崔十三評事公輔', '贈崔十三評事公輔', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["飄飄西極馬，來自渥洼池。","颯飁定山桂，低徊風雨枝。","我聞龍正直，道屈爾何爲。","且有元戎命，悲歌識者誰。","官聯辭宂長，行路洗欹危。","脫劒主人贈，去帆春色隨。","陰沈鐵鳳闕，教練羽林兒。","天子朝侵早，雲臺仗數移。","分軍應供給，百姓日支離。","黠吏因封己，公才或守雌。","燕王買駿骨，渭老得熊羆。","活國名公在，拜壇羣寇疑。","冰壺動瑤碧，野水失蛟螭。","入幕諸彥集，渴賢高選宜。","騫騰坐可致，九萬起於斯。","復進出矛戟，昭然開鼎彝。","會看之子貴，歎及老夫衰。","豈但江曾決，還思霧一披。","暗塵生古鏡，拂匣照西施。","舅氏多人物，無慙困翮垂。"]', '["飄飄西極马，来自渥洼池。","颯飁定山桂，低徊风雨枝。","我闻龙正直，道屈爾何爲。","且有元戎命，悲歌識者誰。","官聯辞宂长，行路洗欹危。","脫劒主人贈，去帆春色隨。","陰沈鐵鳳闕，教練羽林兒。","天子朝侵早，云台仗數移。","分軍應供給，百姓日支離。","黠吏因封己，公才或守雌。","燕王買駿骨，渭老得熊羆。","活国名公在，拜壇羣寇疑。","冰壺动瑤碧，野水失蛟螭。","入幕諸彥集，渴賢高選宜。","騫腾坐可致，九万起於斯。","复進出矛戟，昭然开鼎彝。","會看之子貴，歎及老夫衰。","豈但江曾決，還思霧一披。","暗塵生古镜，拂匣照西施。","舅氏多人物，無慙困翮垂。"]', '诗', 'shi', '', NULL, '贈崔十三評事公輔 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22624fe3-d419-451c-81e0-51d4be56e014', '長江二首 一', '长江二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衆水會涪萬，瞿塘爭一門。","朝宗人共挹，盜賊爾誰尊。","孤石隱如馬，高蘿垂飲猨。","歸心異波浪，何事即飛飜。"]', '["衆水會涪万，瞿塘爭一门。","朝宗人共挹，盜賊爾誰尊。","孤石隐如马，高蘿垂饮猨。","归心異波浪，何事即飞飜。"]', '诗', 'shi', '', NULL, '長江二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7bdb65-ec29-4ebe-b698-19a2f60498df', '長江二首 二', '长江二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["浩浩終不息，乃知東極臨。","衆流歸海意，萬國奉君心。","色借瀟湘闊，聲驅灧澦深。","未辭添霧雨，接上遇衣襟。"]', '["浩浩終不息，乃知东極臨。","衆流归海意，万国奉君心。","色借瀟湘闊，声驱灧澦深。","未辞添霧雨，接上遇衣襟。"]', '诗', 'shi', '', NULL, '長江二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e03aea9d-c2c8-4fce-bfd4-93d0aa46960b', '承聞故房相公靈櫬自閬州啓殯歸葬東都有作二首 一', '承闻故房相公靈櫬自閬州啓殯归葬东都有作二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遠聞房太守，歸葬陸渾山。","一德興王後，孤魂久客間。","孔明多故事，安石竟崇班。","他日嘉陵涕，仍沾楚水還。"]', '["远闻房太守，归葬陸渾山。","一德兴王後，孤魂久客间。","孔明多故事，安石竟崇班。","他日嘉陵涕，仍沾楚水還。"]', '诗', 'shi', '', NULL, '承聞故房相公靈櫬自閬州啓殯歸葬東都有作二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd1ccca-7ddb-41ec-9627-8a093b3f5721', '承聞故房相公靈櫬自閬州啓殯歸葬東都有作二首 二', '承闻故房相公靈櫬自閬州啓殯归葬东都有作二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丹旐飛飛日，初傳發閬州。","風塵終不解，江漢忽同流。","劒動新身匣，書歸故國樓。","盡哀知有處，爲客恐長休。"]', '["丹旐飞飞日，初傳發閬州。","风塵終不解，江漢忽同流。","劒动新身匣，书归故国楼。","尽哀知有处，爲客恐长休。"]', '诗', 'shi', '', NULL, '承聞故房相公靈櫬自閬州啓殯歸葬東都有作二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3415e02-0a13-47d3-8ba2-e33bc0e079b1', '雲安九日鄭十八攜酒陪諸公宴', '云安九日鄭十八携酒陪諸公宴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒花開已盡，菊蘂獨盈枝。","舊摘人頻異，輕香酒蹔隨。","地偏初衣裌，山擁更登危。","萬國皆戎馬，酣歌淚欲垂。"]', '["寒花开已尽，菊蘂独盈枝。","旧摘人頻異，轻香酒蹔隨。","地偏初衣裌，山擁更登危。","万国皆戎马，酣歌泪欲垂。"]', '诗', 'shi', '', NULL, '雲安九日鄭十八攜酒陪諸公宴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c51321-a3dd-4dfd-998a-af8309e58d77', '荅鄭十七郎一絕', '荅鄭十七郎一絕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨後過畦潤，花殘步屐遲。","把文驚小陸，好客見當時。"]', '["雨後過畦潤，花殘步屐遲。","把文驚小陸，好客见當时。"]', '诗', 'shi', '', NULL, '荅鄭十七郎一絕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d9440e-b2d8-4c43-930b-ba0c5dd68548', '將曉二首 一', '將晓二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["石城除擊柝，鐵鎖欲開關。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使動無還。","垂老孤帆色，飄飄犯百蠻。"]', '["石城除擊柝，鐵鎖欲开关。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使动無還。","垂老孤帆色，飄飄犯百蠻。"]', '诗', 'shi', '', NULL, '將曉二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b3f473-2a29-4cf9-ba9c-11676206d700', '將曉二首 二', '將晓二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["軍吏回官燭，舟人自楚歌。","寒沙蒙薄霧，落月去清波。","壯惜身名晚，衰慙應接多。","歸朝日簪笏，筋力定如何。"]', '["軍吏回官燭，舟人自楚歌。","寒沙蒙薄霧，落月去清波。","壯惜身名晚，衰慙應接多。","归朝日簪笏，筋力定如何。"]', '诗', 'shi', '', NULL, '將曉二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f90e24f-0ed7-4a52-a3cc-afccd7a14933', '懷錦水居止二首 一', '懷錦水居止二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["軍旅西征僻，風塵戰伐多。","猶聞蜀父老，不忘舜謳歌。","天險終難立，柴門豈重過。","朝朝巫峽水，遠逗錦江波。"]', '["軍旅西征僻，风塵戰伐多。","猶闻蜀父老，不忘舜謳歌。","天險終难立，柴门豈重過。","朝朝巫峽水，远逗錦江波。"]', '诗', 'shi', '', NULL, '懷錦水居止二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2908cc58-a479-4472-a5b8-d81f874d14f3', '懷錦水居止二首 二', '懷錦水居止二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里橋南宅，百花潭北莊。","層軒皆面水，老樹飽經霜。","雪嶺界天白，錦城曛日黃。","惜哉形勝地，回首一茫茫。"]', '["万里橋南宅，百花潭北莊。","層軒皆面水，老樹飽經霜。","雪嶺界天白，錦城曛日黄。","惜哉形勝地，回首一茫茫。"]', '诗', 'shi', '', NULL, '懷錦水居止二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4168a793-7936-473c-8a83-e72796a70469', '子規', '子規', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽裏雲安縣，江樓翼瓦齊。","兩邊山木合，終日子規啼。","眇眇春風見，蕭蕭夜色淒。","客愁那聽此，故作傍人低。"]', '["峽裏云安縣，江楼翼瓦齊。","兩邊山木合，終日子規啼。","眇眇春风见，蕭蕭夜色淒。","客愁那听此，故作傍人低。"]', '诗', 'shi', '', NULL, '子規 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('240b5111-54b8-466d-9b35-d5206013dcd1', '立春', '立春', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春日春盤細生菜，忽憶兩京梅發時。","盤出高門行白玉，菜傳纖手送青絲。","巫峽寒江那對眼，杜陵遠客不勝悲。","此身未知歸定處，呼兒覓紙一題詩。"]', '["春日春盤細生菜，忽憶兩京梅發时。","盤出高门行白玉，菜傳纖手送青絲。","巫峽寒江那对眼，杜陵远客不勝悲。","此身未知归定处，呼兒覓紙一題诗。"]', '诗', 'shi', '', NULL, '立春 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b90e6f-c015-4833-bed8-40d2092a3d35', '漫成一絕', '漫成一絕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江月去人只數尺，風燈照夜欲三更。","沙頭宿鷺聯拳靜，船尾跳魚撥刺鳴。"]', '["江月去人只數尺，风灯照夜欲三更。","沙头宿鷺聯拳静，船尾跳鱼撥刺鳴。"]', '诗', 'shi', '', NULL, '漫成一絕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642f5dc6-0c6f-4964-b64e-f4445b079109', '老病', '老病', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老病巫山裏，稽留楚客中。","藥殘他日裹，花發去年叢。","夜足霑沙雨，春多逆水風。","合分雙賜筆，猶作一飄蓬。"]', '["老病巫山裏，稽留楚客中。","藥殘他日裹，花發去年叢。","夜足霑沙雨，春多逆水风。","合分雙賜笔，猶作一飄蓬。"]', '诗', 'shi', '', NULL, '老病 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191c54af-8c42-40be-b931-db22b2e46c06', '南楚', '南楚', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南楚青春異，暄寒早早分。","無名江上草，隨意嶺頭雲。","正月蜂相見，非時鳥共聞。","杖藜妨躍馬，不是故離羣。"]', '["南楚青春異，暄寒早早分。","無名江上草，隨意嶺头云。","正月蜂相见，非时鸟共闻。","杖藜妨躍马，不是故離羣。"]', '诗', 'shi', '', NULL, '南楚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18101e75-88aa-4533-821f-438d99ceecdf', '寄常徵君', '寄常徵君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白水青山空復春，徵君晚節傍風塵。","楚妃堂上色殊衆，海鶴階前鳴向人。","萬事糾紛猶絕粒，一官羇絆實藏身。","開州入夏知涼冷，不似雲安毒熱新。"]', '["白水青山空复春，徵君晚節傍风塵。","楚妃堂上色殊衆，海鹤階前鳴向人。","万事糾紛猶絕粒，一官羇絆實藏身。","开州入夏知涼冷，不似云安毒熱新。"]', '诗', 'shi', '', NULL, '寄常徵君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('510af400-6dc4-4fdd-a6a1-29645ea01164', '寄岑嘉州', '寄岑嘉州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不見故人十年餘，不道故人無素書。","願逢顏色關塞遠，豈意出守江城居。","外江三峽且相接，斗酒新詩終日疎。","謝朓每篇堪諷誦，馮唐已老聽吹噓。","泊船秋夜經春草，伏枕青楓限玉除。","眼前所寄選何物，贈子雲安雙鯉魚。"]', '["不见故人十年餘，不道故人無素书。","願逢顏色关塞远，豈意出守江城居。","外江三峽且相接，斗酒新诗終日疎。","謝朓每篇堪諷誦，馮唐已老听吹噓。","泊船秋夜經春草，伏枕青楓限玉除。","眼前所寄選何物，贈子云安雙鯉鱼。"]', '诗', 'shi', '', NULL, '寄岑嘉州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d190d386-7eeb-4e0d-8421-7ebf0cf9fa85', '移居夔州郭', '移居夔州郭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["伏枕雲安縣，遷居白帝城。","春知催柳別，江與放船清。","農事聞人說，山光見鳥情。","禹功饒斷石，且就土微平。"]', '["伏枕云安縣，遷居白帝城。","春知催柳別，江與放船清。","農事闻人说，山光见鸟情。","禹功饒斷石，且就土微平。"]', '诗', 'shi', '', NULL, '移居夔州郭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee869b1-4f09-431c-9438-cf5a2e75d34b', '船下夔州郭宿雨濕不得上岸別王十二判官', '船下夔州郭宿雨濕不得上岸別王十二判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["依沙宿舸船，石瀨月娟娟。","風起春燈亂，江鳴夜雨懸。","晨鐘雲外濕，勝地石堂煙。","柔櫓輕鷗外，含悽覺汝賢。"]', '["依沙宿舸船，石瀨月娟娟。","风起春灯亂，江鳴夜雨懸。","晨鐘云外濕，勝地石堂煙。","柔櫓轻鷗外，含悽覺汝賢。"]', '诗', 'shi', '', NULL, '船下夔州郭宿雨濕不得上岸別王十二判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd5c586-f560-4a72-acea-f2674561aabb', '雨不絕', '雨不絕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鳴雨既過漸細微，映空搖颺如絲飛。","階前短草泥不亂，院裏長條風乍稀。","舞石旋應將乳子，行雲莫自濕仙衣。","眼邊江舸何怱促，未待安流逆浪歸。"]', '["鳴雨既過漸細微，映空搖颺如絲飞。","階前短草泥不亂，院裏长條风乍稀。","舞石旋應將乳子，行云莫自濕仙衣。","眼邊江舸何怱促，未待安流逆浪归。"]', '诗', 'shi', '', NULL, '雨不絕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d86d1df4-dba7-4ef2-9efc-9111c80ae92e', '崔評事弟許相迎不到應慮老夫見泥雨怯出必愆佳期走筆戲簡', '崔評事弟許相迎不到應慮老夫见泥雨怯出必愆佳期走笔戲簡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江閣要賓許馬迎，午時起坐自天明。","浮雲不負青春色，細雨何孤白帝城。","身過花間霑濕好，醉於馬上往來輕。","虛疑皓首衝泥怯，實少銀鞍傍險行。"]', '["江閣要賓許马迎，午时起坐自天明。","浮云不負青春色，細雨何孤白帝城。","身過花间霑濕好，醉於马上往来轻。","虛疑皓首衝泥怯，實少銀鞍傍險行。"]', '诗', 'shi', '', NULL, '崔評事弟許相迎不到應慮老夫見泥雨怯出必愆佳期走筆戲簡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5564daec-7353-412f-8979-50a31cfc7339', '宿江邊閣', '宿江邊閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暝色延山徑，高齋次水門。","薄雲巖際宿，孤月浪中飜。","鸛鶴追飛靜，豺狼得食喧。","不眠憂戰伐，無力正乾坤。"]', '["暝色延山徑，高斋次水门。","薄云巖際宿，孤月浪中飜。","鸛鹤追飞静，豺狼得食喧。","不眠憂戰伐，無力正乾坤。"]', '诗', 'shi', '', NULL, '宿江邊閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ad17df-2a5c-4f93-af23-b66893e495f3', '夜宿西閣曉呈元二十一曹長', '夜宿西閣晓呈元二十一曹长', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城暗更籌急，樓高雨雪微。","稍通綃幕霽，遠帶玉繩稀。","門鵲晨光起，牆烏宿處飛。","寒江流甚細，有意待人歸。"]', '["城暗更籌急，楼高雨雪微。","稍通綃幕霽，远带玉繩稀。","门鵲晨光起，牆烏宿处飞。","寒江流甚細，有意待人归。"]', '诗', 'shi', '', NULL, '夜宿西閣曉呈元二十一曹長 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('134597c9-e2f1-42cc-9891-d201d5fb542c', '西閣口號', '西閣口號', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山木抱雲稠，寒江繞上頭。","雪崖纔變石，風幔不依樓。","社稷堪流涕，安危在運籌。","看君話王室，感動幾銷憂。"]', '["山木抱云稠，寒江繞上头。","雪崖纔变石，风幔不依楼。","社稷堪流涕，安危在運籌。","看君話王室，感动幾銷憂。"]', '诗', 'shi', '', NULL, '西閣口號 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6313a11-5990-45ec-8dc7-2cffd50ede93', '西閣雨望', '西閣雨望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樓雨霑雲幔，山寒著水城。","徑添沙面出，湍減石稜生。","菊蘂淒疎放，松林駐遠情。","滂沱朱檻濕，萬慮傍簷楹。"]', '["楼雨霑云幔，山寒著水城。","徑添沙面出，湍減石稜生。","菊蘂淒疎放，松林駐远情。","滂沱朱檻濕，万慮傍簷楹。"]', '诗', 'shi', '', NULL, '西閣雨望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1194ad8-9977-44bd-b1a2-235eab904fa4', '不離西閣二首 一', '不離西閣二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江柳非時發，江花冷色頻。","地偏應有瘴，臘近已含春。","失學從愚子，無家住老身。","不知西閣意，肯別定留人。"]', '["江柳非时發，江花冷色頻。","地偏應有瘴，臘近已含春。","失学從愚子，無家住老身。","不知西閣意，肯別定留人。"]', '诗', 'shi', '', NULL, '不離西閣二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294a2fee-f9ee-4b2b-9442-f15496b6eb8e', '不離西閣二首 二', '不離西閣二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西閣從人別，人今亦故亭。","江雲飄素練，石壁斷空青。","滄海先迎日，銀河倒列星。","平生耽勝事，吁駭始初經。"]', '["西閣從人別，人今亦故亭。","江云飄素練，石壁斷空青。","滄海先迎日，銀河倒列星。","平生耽勝事，吁駭始初經。"]', '诗', 'shi', '', NULL, '不離西閣二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('349ea830-2ad3-4b39-9b60-23594d6c57a1', '西閣三度期大昌嚴明府同宿不到', '西閣三度期大昌嚴明府同宿不到', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["問子能來宿，今疑索故要。","匣琴虛夜夜，手板自朝朝。","金吼霜鐘徹，花催臘炬銷。","早鳧江檻底，雙影漫飄颻。"]', '["问子能来宿，今疑索故要。","匣琴虛夜夜，手板自朝朝。","金吼霜鐘徹，花催臘炬銷。","早鳧江檻底，雙影漫飄颻。"]', '诗', 'shi', '', NULL, '西閣三度期大昌嚴明府同宿不到 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0476ef-0c5f-4789-aa92-26f52da3586f', '西閣二首 一', '西閣二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫山小搖落，碧色見松林。","百鳥各相命，孤雲無自心。","層軒俯江壁，要路亦高深。","朱紱猶紗帽，新詩近玉琴。","功名不早立，衰病謝知音。","哀世非王粲，終然學越吟。"]', '["巫山小搖落，碧色见松林。","百鸟各相命，孤云無自心。","層軒俯江壁，要路亦高深。","朱紱猶紗帽，新诗近玉琴。","功名不早立，衰病謝知音。","哀世非王粲，終然学越吟。"]', '诗', 'shi', '', NULL, '西閣二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb4426c-cc99-40d4-949a-0574ecc33240', '西閣二首 二', '西閣二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嬾心似江水，日夜向滄洲。","不道含香賤，其如鑷白休。","經過調碧柳，蕭索倚朱樓。","畢娶何時竟，消中得自由。","豪華看古往，服食寄冥搜。","詩盡人間興，兼須入海求。"]', '["嬾心似江水，日夜向滄洲。","不道含香賤，其如鑷白休。","經過調碧柳，蕭索倚朱楼。","畢娶何时竟，消中得自由。","豪华看古往，服食寄冥搜。","诗尽人间兴，兼須入海求。"]', '诗', 'shi', '', NULL, '西閣二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5874bf-3748-44c9-bc3a-be4a8c3eb2f6', '閣夜', '閣夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歲暮陰陽催短景，天涯霜雪霽寒宵。","五更鼓角聲悲壯，三峽星河影動搖。","野哭幾家聞戰伐，夷歌數處起漁樵。","臥龍躍馬終黃土，人事依依漫寂寥。"]', '["歲暮陰陽催短景，天涯霜雪霽寒宵。","五更鼓角声悲壯，三峽星河影动搖。","野哭幾家闻戰伐，夷歌數处起漁樵。","臥龙躍马終黄土，人事依依漫寂寥。"]', '诗', 'shi', '', NULL, '閣夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807e27bc-7987-4c96-bbf8-69dbf3149bae', '西閣夜', '西閣夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["恍惚寒山暮，逶迤白霧昏。","山虛風落石，樓靜月侵門。","擊柝可憐子，無衣何處村。","時危關百慮，盜賊爾猶存。"]', '["恍惚寒山暮，逶迤白霧昏。","山虛风落石，楼静月侵门。","擊柝可怜子，無衣何处村。","时危关百慮，盜賊爾猶存。"]', '诗', 'shi', '', NULL, '西閣夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ba0521b-3a2e-4c50-bce8-06bc4f512685', '瀼西寒望', '瀼西寒望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["水色含羣動，朝光切太虛。","年侵頻悵望，興遠一蕭疎。","猨挂時相學，鷗行炯自如。","瞿唐春欲至，定卜瀼西居。"]', '["水色含羣动，朝光切太虛。","年侵頻悵望，兴远一蕭疎。","猨挂时相学，鷗行炯自如。","瞿唐春欲至，定卜瀼西居。"]', '诗', 'shi', '', NULL, '瀼西寒望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffcf04ad-885a-4f9e-89c3-df5eb7eb7d75', '入宅三首 一', '入宅三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["奔峭背赤甲，斷崖當白鹽。","客居愧遷次，春酒漸多添。","花亞欲移竹，鳥窺新捲簾。","衰年不敢恨，勝概欲相兼。"]', '["奔峭背赤甲，斷崖當白鹽。","客居愧遷次，春酒漸多添。","花亞欲移竹，鸟窺新捲簾。","衰年不敢恨，勝概欲相兼。"]', '诗', 'shi', '', NULL, '入宅三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9098a316-70d2-41df-8018-5a18e82a8cfb', '入宅三首 二', '入宅三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亂後居難定，春歸客未還。","水生魚復浦，雲暖麝香山。","半頂梳頭白，過眉拄杖斑。","相看多使者，一一問函關。"]', '["亂後居难定，春归客未還。","水生鱼复浦，云暖麝香山。","半頂梳头白，過眉拄杖斑。","相看多使者，一一问函关。"]', '诗', 'shi', '', NULL, '入宅三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c0662e-6dc6-4146-80bd-c0eee78dc0b4', '入宅三首 三', '入宅三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宋玉歸州宅，雲通白帝城。","吾人淹老病，旅食豈才名。","峽口風常急，江流氣不平。","只應與兒子，飄轉任浮生。"]', '["宋玉归州宅，云通白帝城。","吾人淹老病，旅食豈才名。","峽口风常急，江流氣不平。","只應與兒子，飄轉任浮生。"]', '诗', 'shi', '', NULL, '入宅三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e199059f-0155-4650-bd27-2048062f8d10', '赤甲', '赤甲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["卜居赤甲遷居新，兩見巫山楚水春。","炙背可以獻天子，美芹由來知野人。","荆州鄭薛寄書近，蜀客郗岑非我鄰。","笑接郎中評事飲，病從深酌道吾真。"]', '["卜居赤甲遷居新，兩见巫山楚水春。","炙背可以獻天子，美芹由来知野人。","荆州鄭薛寄书近，蜀客郗岑非我鄰。","笑接郎中評事饮，病從深酌道吾真。"]', '诗', 'shi', '', NULL, '赤甲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbcd3acf-f256-4ea4-9ba3-dff2f0727a2c', '卜居', '卜居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歸羨遼東鶴，吟同楚執珪。","未成遊碧海，著處覓丹梯。","雲障寬江左，春耕破瀼西。","桃紅客若至，定似昔人迷。"]', '["归羨遼东鹤，吟同楚執珪。","未成游碧海，著处覓丹梯。","云障寬江左，春耕破瀼西。","桃紅客若至，定似昔人迷。"]', '诗', 'shi', '', NULL, '卜居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95ecb516-eef9-4ab8-b4aa-091c84aba40d', '暮春題瀼西新賃草屋五首 一', '暮春題瀼西新賃草屋五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久嗟三峽客，再與暮春期。","百舌欲無語，繁花能幾時。","谷虛雲氣薄，波亂日華遲。","戰伐何由定，哀傷不在茲。"]', '["久嗟三峽客，再與暮春期。","百舌欲無語，繁花能幾时。","谷虛云氣薄，波亂日华遲。","戰伐何由定，哀傷不在茲。"]', '诗', 'shi', '', NULL, '暮春題瀼西新賃草屋五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b810d01-f954-481f-8b2c-4aef51904c75', '暮春題瀼西新賃草屋五首 二', '暮春題瀼西新賃草屋五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此邦千樹橘，不見比封君。","養拙干戈際，全生麋鹿羣。","畏人江北草，旅食瀼西雲。","萬里巴渝曲，三年實飽聞。"]', '["此邦千樹橘，不见比封君。","養拙干戈際，全生麋鹿羣。","畏人江北草，旅食瀼西云。","万里巴渝曲，三年實飽闻。"]', '诗', 'shi', '', NULL, '暮春題瀼西新賃草屋五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e78cdb-4a2b-439c-99da-34b466fe138e', '暮春題瀼西新賃草屋五首 三', '暮春題瀼西新賃草屋五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["綵雲陰復白，錦樹曉來青。","身世雙蓬鬢，乾坤一草亭。","哀歌時自短，醉舞爲誰醒。","細雨荷鋤立，江猨吟翠屏。"]', '["綵云陰复白，錦樹晓来青。","身世雙蓬鬢，乾坤一草亭。","哀歌时自短，醉舞爲誰醒。","細雨荷鋤立，江猨吟翠屏。"]', '诗', 'shi', '', NULL, '暮春題瀼西新賃草屋五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('590b9fa1-2f29-41fa-8b37-4c9869e7ec1a', '暮春題瀼西新賃草屋五首 四', '暮春題瀼西新賃草屋五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["壯年學書劒，他日委泥沙。","事主非無祿，浮生即有涯。","高齋依藥餌，絕域改春華。","喪亂丹心破，王臣未一家。"]', '["壯年学书劒，他日委泥沙。","事主非無祿，浮生即有涯。","高斋依藥餌，絕域改春华。","喪亂丹心破，王臣未一家。"]', '诗', 'shi', '', NULL, '暮春題瀼西新賃草屋五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8393ea07-5a6e-4f70-892c-8130b54b519e', '暮春題瀼西新賃草屋五首 五', '暮春題瀼西新賃草屋五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["欲陳濟世策，已老尚書郎。","未息豺虎鬬，空慙鴛鷺行。","時危人事急，風逆羽毛傷。","落日悲江漢，中宵淚滿床。"]', '["欲陳濟世策，已老尚书郎。","未息豺虎鬬，空慙鴛鷺行。","时危人事急，风逆羽毛傷。","落日悲江漢，中宵泪满床。"]', '诗', 'shi', '', NULL, '暮春題瀼西新賃草屋五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42248d6-0235-4179-ab4a-2b708eff1301', '園', '园', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["仲夏流多水，清晨向小園。","碧溪搖艇闊，朱果爛枝繁。","始爲江山靜，終防市井喧。","畦蔬繞茅屋，自足媚盤餐。"]', '["仲夏流多水，清晨向小园。","碧溪搖艇闊，朱果爛枝繁。","始爲江山静，終防市井喧。","畦蔬繞茅屋，自足媚盤餐。"]', '诗', 'shi', '', NULL, '園 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1884cc1c-33fb-4783-bff3-557671719651', '豎子至', '豎子至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樝梨且綴碧，梅杏半傳黃。","小子幽園至，輕籠熟柰香。","山風猶滿把，野露及新嘗。","欲寄江湖客，提攜日月長。"]', '["樝梨且綴碧，梅杏半傳黄。","小子幽园至，轻籠熟柰香。","山风猶满把，野露及新嘗。","欲寄江湖客，提携日月长。"]', '诗', 'shi', '', NULL, '豎子至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0708f21e-7b95-47f4-9115-18c7f4904786', '示獠奴阿段', '示獠奴阿段', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山木蒼蒼落日曛，竹竿褭褭細泉分。","郡人入夜爭餘瀝，豎子尋源獨不聞。","病渴三更迴白首，傳聲一注濕青雲。","曾驚陶侃胡奴異，怪爾常穿虎豹羣。"]', '["山木蒼蒼落日曛，竹竿褭褭細泉分。","郡人入夜爭餘瀝，豎子尋源独不闻。","病渴三更迴白首，傳声一注濕青云。","曾驚陶侃胡奴異，怪爾常穿虎豹羣。"]', '诗', 'shi', '', NULL, '示獠奴阿段 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1e7b7e-1824-402a-8ef1-ada1b0490f58', '秋野五首 一', '秋野五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋野日疏蕪，寒江動碧虛。","繫舟蠻井絡，卜宅楚村墟。","棗熟從人打，葵荒欲自鋤。","盤餐老夫食，分減及溪魚。"]', '["秋野日疏蕪，寒江动碧虛。","繫舟蠻井絡，卜宅楚村墟。","棗熟從人打，葵荒欲自鋤。","盤餐老夫食，分減及溪鱼。"]', '诗', 'shi', '', NULL, '秋野五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948aee1f-c5d9-47f3-949a-932f22ac79ba', '秋野五首 二', '秋野五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["易識浮生理，難教一物違。","水深魚極樂，林茂鳥知歸。","吾老甘貧病，榮華有是非。","秋風吹几杖，不厭此山薇。"]', '["易識浮生理，难教一物違。","水深鱼極乐，林茂鸟知归。","吾老甘貧病，榮华有是非。","秋风吹几杖，不厭此山薇。"]', '诗', 'shi', '', NULL, '秋野五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698d613c-197c-4967-a0d1-c1d7a19e4858', '秋野五首 三', '秋野五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["禮樂攻吾短，山林引興長。","掉頭紗帽仄，曝背竹書光。","風落收松子，天寒割蜜房。","稀疎小紅翠，駐屐近微香。"]', '["禮乐攻吾短，山林引兴长。","掉头紗帽仄，曝背竹书光。","风落收松子，天寒割蜜房。","稀疎小紅翠，駐屐近微香。"]', '诗', 'shi', '', NULL, '秋野五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c69461-79e6-4754-a486-e165cef8606b', '秋野五首 四', '秋野五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遠岸秋沙白，連山晚照紅。","潛鱗輸駭浪，歸翼會高風。","砧響家家發，樵聲箇箇同。","飛霜任青女，賜被隔南宮。"]', '["远岸秋沙白，連山晚照紅。","潛鱗輸駭浪，归翼會高风。","砧响家家發，樵声箇箇同。","飞霜任青女，賜被隔南宮。"]', '诗', 'shi', '', NULL, '秋野五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e10394a-b2cf-4f84-a07c-2b1103966824', '秋野五首 五', '秋野五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["身許麒膦畫，年衰鴛鷺羣。","大江秋易盛，空峽夜多聞。","徑隱千重石，帆留一片雲。","兒童解蠻語，不必作參軍。"]', '["身許麒膦畫，年衰鴛鷺羣。","大江秋易盛，空峽夜多闻。","徑隐千重石，帆留一片云。","兒童解蠻語，不必作參軍。"]', '诗', 'shi', '', NULL, '秋野五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7202af23-2063-4556-be72-f887f5688d3f', '溪上', '溪上', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽內淹留客，溪邊四五家。","古苔生迮地，秋竹隱疎花。","塞俗人無井，山田飯有沙。","西江使船至，時復問京華。"]', '["峽內淹留客，溪邊四五家。","古苔生迮地，秋竹隐疎花。","塞俗人無井，山田飯有沙。","西江使船至，时复问京华。"]', '诗', 'shi', '', NULL, '溪上 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69982aff-b3db-4650-b28f-5b89ff6695a6', '樹間', '樹间', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["岑寂雙甘樹，婆娑一院香。","交柯低几杖，垂實礙衣裳。","滿歲如松碧，同時待菊黃。","幾迴霑葉露，乘月坐胡牀。"]', '["岑寂雙甘樹，婆娑一院香。","交柯低几杖，垂實礙衣裳。","满歲如松碧，同时待菊黄。","幾迴霑葉露，乘月坐胡牀。"]', '诗', 'shi', '', NULL, '樹間 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f359c3-d3d9-4b65-ba49-a281cb8d8ec1', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 一', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["病枕依茅棟，荒鉏淨果林。","背堂資僻遠，在野興清深。","山雉防求敵，江猨應獨吟。","洩雲高不去，隱几亦無心。"]', '["病枕依茅棟，荒鉏淨果林。","背堂資僻远，在野兴清深。","山雉防求敵，江猨應独吟。","洩云高不去，隐几亦無心。"]', '诗', 'shi', '', NULL, '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98275391-c590-4fd1-ae91-3641fa8c4756', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 二', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衆壑生寒早，長林卷霧齊。","青蟲懸就日，朱果落封泥。","薄俗防人面，全身學馬蹄。","吟詩坐迴首，隨意葛巾低。"]', '["衆壑生寒早，长林卷霧齊。","青蟲懸就日，朱果落封泥。","薄俗防人面，全身学马蹄。","吟诗坐迴首，隨意葛巾低。"]', '诗', 'shi', '', NULL, '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13724b6-6cd7-4c38-bdae-aa29c39b29c5', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 三', '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["籬弱門何向，沙虛岸只摧。","日斜魚更食，客散鳥還來。","寒水光難定，秋山響易哀。","天涯稍曛黑，倚杖更裴回。"]', '["籬弱门何向，沙虛岸只摧。","日斜鱼更食，客散鸟還来。","寒水光难定，秋山响易哀。","天涯稍曛黑，倚杖更裴回。"]', '诗', 'shi', '', NULL, '課小豎鉏斫舍北果林枝蔓荒穢淨訖移牀三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e2cf65b-d757-4698-97a0-31aedb02f4a3', '寒雨朝行視園樹', '寒雨朝行視园樹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["柴門雜樹向千株，丹橘黃甘此地無。","江上今朝寒雨歇，籬中秀色畫屏紆。","桃蹊李徑年雖故，梔子紅椒豔復殊。","鏁石藤稍元自落，倚天松骨見來枯。","林香出實垂將盡，葉蔕辭枝不重蘇。","愛日恩光蒙借貸，清霜殺氣得憂虞。","衰顏更覓藜床坐，緩步仍須竹杖扶。","散騎未知雲閣處，啼猨僻在楚山隅。"]', '["柴门杂樹向千株，丹橘黄甘此地無。","江上今朝寒雨歇，籬中秀色畫屏紆。","桃蹊李徑年雖故，梔子紅椒豔复殊。","鏁石藤稍元自落，倚天松骨见来枯。","林香出實垂將尽，葉蔕辞枝不重蘇。","愛日恩光蒙借貸，清霜殺氣得憂虞。","衰顏更覓藜床坐，緩步仍須竹杖扶。","散騎未知云閣处，啼猨僻在楚山隅。"]', '诗', 'shi', '', NULL, '寒雨朝行視園樹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e71d5c-ff47-4b86-b37f-f79cbfbc4796', '季秋江村', '季秋江村', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["喬木村墟古，疎籬野蔓懸。","清琴將暇日，白首望霜天。","登俎黃甘重，支床錦石圓。","遠遊雖寂寞，難見此山川。"]', '["喬木村墟古，疎籬野蔓懸。","清琴將暇日，白首望霜天。","登俎黄甘重，支床錦石圓。","远游雖寂寞，难见此山川。"]', '诗', 'shi', '', NULL, '季秋江村 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb07ed0-a56b-49e6-8ec5-16df727f2c65', '小園', '小园', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["由來巫峽水，本自楚人家。","客病留因藥，春深買爲花。","秋庭風落果，瀼岸雨頹沙。","問俗營寒事，將詩待物華。"]', '["由来巫峽水，本自楚人家。","客病留因藥，春深買爲花。","秋庭风落果，瀼岸雨頹沙。","问俗營寒事，將诗待物华。"]', '诗', 'shi', '', NULL, '小園 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100902e0-ed47-4a70-a85f-05e9bb4e3ca5', '自瀼西荆扉且移居東屯茅屋四首 一', '自瀼西荆扉且移居东屯茅屋四首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白鹽危嶠北，赤甲古城東。","平地一川穩，高山四面同。","煙霜淒野日，秔稻熟天風。","人事傷蓬轉，吾將守桂叢。"]', '["白鹽危嶠北，赤甲古城东。","平地一川穩，高山四面同。","煙霜淒野日，秔稻熟天风。","人事傷蓬轉，吾將守桂叢。"]', '诗', 'shi', '', NULL, '自瀼西荆扉且移居東屯茅屋四首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5cc8fa-d12f-4b61-9926-32e8a62baca2', '自瀼西荆扉且移居東屯茅屋四首 二', '自瀼西荆扉且移居东屯茅屋四首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東屯復瀼西，一種住青溪。","來往皆茅屋，淹留爲稻畦。","市喧宜近利，林僻此無蹊。","若訪衰翁語，須令賸客迷。"]', '["东屯复瀼西，一種住青溪。","来往皆茅屋，淹留爲稻畦。","市喧宜近利，林僻此無蹊。","若訪衰翁語，須令賸客迷。"]', '诗', 'shi', '', NULL, '自瀼西荆扉且移居東屯茅屋四首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ae6792-2b0a-4714-b6af-90e15c2c546c', '自瀼西荆扉且移居東屯茅屋四首 三', '自瀼西荆扉且移居东屯茅屋四首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["道北馮都使，高齋見一川。","子能渠細石，吾亦沼清泉。","枕帶還相似，柴荆即有焉。","斫畬應費日，解纜不知年。"]', '["道北馮都使，高斋见一川。","子能渠細石，吾亦沼清泉。","枕带還相似，柴荆即有焉。","斫畬應費日，解纜不知年。"]', '诗', 'shi', '', NULL, '自瀼西荆扉且移居東屯茅屋四首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d87d55c8-dbfb-4a90-a3b7-d34920317999', '自瀼西荆扉且移居東屯茅屋四首 四', '自瀼西荆扉且移居东屯茅屋四首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["牢落西江外，參差北戶間。","久遊巴子國，臥病楚人山。","幽獨移佳境，清深隔遠關。","寒空見鴛鷺，迴首憶朝班。"]', '["牢落西江外，參差北戶间。","久游巴子国，臥病楚人山。","幽独移佳境，清深隔远关。","寒空见鴛鷺，迴首憶朝班。"]', '诗', 'shi', '', NULL, '自瀼西荆扉且移居東屯茅屋四首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661bab14-62cd-4385-a173-f47e53e6e649', '茅堂檢校收稻二首 一', '茅堂檢校收稻二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["香稻三秋末，平田百頃間。","喜無多屋宇，幸不礙雲山。","御裌侵寒氣，嘗新破旅顏。","紅鮮終日有，玉粒未吾慳。"]', '["香稻三秋末，平田百頃间。","喜無多屋宇，幸不礙云山。","御裌侵寒氣，嘗新破旅顏。","紅鲜終日有，玉粒未吾慳。"]', '诗', 'shi', '', NULL, '茅堂檢校收稻二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde17d21-b335-43ef-8a18-c476b60f4b57', '茅堂檢校收稻二首 二', '茅堂檢校收稻二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["稻米炊能白，秋葵煮復新。","誰云滑易飽，老藉軟俱勻。","種幸房州熟，苗同伊闕春。","無勞映渠盌，自有色如銀。"]', '["稻米炊能白，秋葵煮复新。","誰云滑易飽，老藉軟俱勻。","種幸房州熟，苗同伊闕春。","無勞映渠盌，自有色如銀。"]', '诗', 'shi', '', NULL, '茅堂檢校收稻二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab1281d-86d5-4114-83bc-384228b89102', '東屯月夜', '东屯月夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["抱疾漂萍老，防邊舊穀屯。","春農親異俗，歲月在衡門。","青女霜楓重，黃牛峽水喧。","泥留虎鬬跡，月挂客愁村。","喬木澄稀影，輕雲倚細根。","數驚聞雀噪，暫睡想猨蹲。","日轉東方白，風來北斗昏。","天寒不成寢，無夢寄歸魂。"]', '["抱疾漂萍老，防邊旧穀屯。","春農親異俗，歲月在衡门。","青女霜楓重，黄牛峽水喧。","泥留虎鬬跡，月挂客愁村。","喬木澄稀影，轻云倚細根。","數驚闻雀噪，暫睡想猨蹲。","日轉东方白，风来北斗昏。","天寒不成寢，無梦寄归魂。"]', '诗', 'shi', '', NULL, '東屯月夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60dbbd97-f841-4008-9a8a-35188f8242f4', '東屯北崦', '东屯北崦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["盜賊浮生困，誅求異俗貧。","空村惟見鳥，落日未逢人。","步壑風吹面，看松露滴身。","遠山迴白首，戰地有黃塵。"]', '["盜賊浮生困，誅求異俗貧。","空村惟见鸟，落日未逢人。","步壑风吹面，看松露滴身。","远山迴白首，戰地有黄塵。"]', '诗', 'shi', '', NULL, '東屯北崦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('745560cf-467b-4fe9-a0c9-50d10f03efdb', '從驛次草堂復至東屯二首 一', '從驛次草堂复至东屯二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽內歸田客，江邊借馬騎。","非尋戴安道，似向習家池。","峽險風煙僻，天寒橘柚垂。","築場看斂積，一學楚人爲。"]', '["峽內归田客，江邊借马騎。","非尋戴安道，似向習家池。","峽險风煙僻，天寒橘柚垂。","築場看斂積，一学楚人爲。"]', '诗', 'shi', '', NULL, '從驛次草堂復至東屯二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fea3c2-af73-4b77-8cd1-ebf233140999', '從驛次草堂復至東屯二首 二', '從驛次草堂复至东屯二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["短景難高臥，衰年強此身。","山家蒸栗暖，野飯射麋新。","世路知交薄，門庭畏客頻。","牧童斯在眼，田父實爲鄰。"]', '["短景难高臥，衰年強此身。","山家蒸栗暖，野飯射麋新。","世路知交薄，门庭畏客頻。","牧童斯在眼，田父實爲鄰。"]', '诗', 'shi', '', NULL, '從驛次草堂復至東屯二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0878d2a-a575-4609-9bae-5b69cd5ce9c7', '暫往白帝復還東屯', '暫往白帝复還东屯', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["復作歸田去，猶殘穫稻功。","築場憐穴蟻，拾穗許村童。","落杵光輝白，除芒子粒紅。","加餐可扶老，倉庾慰飄蓬。"]', '["复作归田去，猶殘穫稻功。","築場怜穴蟻，拾穗許村童。","落杵光輝白，除芒子粒紅。","加餐可扶老，倉庾慰飄蓬。"]', '诗', 'shi', '', NULL, '暫往白帝復還東屯 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256d10b8-dba7-466f-8bf9-ba87b8deac72', '刈稻了詠懷', '刈稻了詠懷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["稻穫空雲水，川平對石門。","寒風疎落木，旭日散雞豚。","野哭初聞戰，樵歌稍出村。","無家問消息，作客信乾坤。"]', '["稻穫空云水，川平对石门。","寒风疎落木，旭日散雞豚。","野哭初闻戰，樵歌稍出村。","無家问消息，作客信乾坤。"]', '诗', 'shi', '', NULL, '刈稻了詠懷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a9afa8-5b0f-4dcb-85f8-b7f2f23f8b5e', '上白帝城', '上白帝城', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城峻隨天壁，樓高更女牆。","江流思夏后，風至憶襄王。","老去聞悲角，人扶報夕陽。","公孫初恃險，躍馬意何長。"]', '["城峻隨天壁，楼高更女牆。","江流思夏后，风至憶襄王。","老去闻悲角，人扶報夕陽。","公孫初恃險，躍马意何长。"]', '诗', 'shi', '', NULL, '上白帝城 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a292ae6-2955-4cbb-af62-fc78e4982c7a', '上白帝城二首 一', '上白帝城二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江城含變態，一上一回新。","天欲今朝雨，山歸萬古春。","英雄餘事業，衰邁久風塵。","取醉他鄉客，相逢故國人。","兵戈猶擁蜀，賦斂強輸秦。","不是煩形勝，深慙畏損神。"]', '["江城含变態，一上一回新。","天欲今朝雨，山归万古春。","英雄餘事業，衰邁久风塵。","取醉他乡客，相逢故国人。","兵戈猶擁蜀，賦斂強輸秦。","不是煩形勝，深慙畏損神。"]', '诗', 'shi', '', NULL, '上白帝城二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96c86d0-8a1d-477e-be76-96b9443598ad', '上白帝城二首 二', '上白帝城二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白帝空祠廟，孤雲自往來。","江山城宛轉，棟宇客裴回。","勇略今何在，當年亦壯哉。","後人將酒肉，虛殿日塵埃。","谷鳥鳴還過，林花落又開。","多慙病無力，騎馬入青苔。"]', '["白帝空祠廟，孤云自往来。","江山城宛轉，棟宇客裴回。","勇略今何在，當年亦壯哉。","後人將酒肉，虛殿日塵埃。","谷鸟鳴還過，林花落又开。","多慙病無力，騎马入青苔。"]', '诗', 'shi', '', NULL, '上白帝城二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f63a15-ac80-463f-9abf-c7d3b238d289', '武侯廟', '武侯廟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遺廟丹青落，空山草木長。","猶聞辭後主，不復臥南陽。"]', '["遺廟丹青落，空山草木长。","猶闻辞後主，不复臥南陽。"]', '诗', 'shi', '', NULL, '武侯廟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('927908c0-999f-4d3f-8192-d67d28f93576', '八陣圖', '八陣圖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["功蓋三分國，名高八陣圖。","江流石不轉，遺恨失吞吳。"]', '["功蓋三分国，名高八陣圖。","江流石不轉，遺恨失吞吳。"]', '诗', 'shi', '', NULL, '八陣圖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed8211c-2a95-4571-8ce3-065619d2bc69', '謁先主廟', '謁先主廟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["慘淡風雲會，乘時各有人。","力侔分社稷，志屈偃經綸。","復漢留長策，中原仗老臣。","雜耕心未已，歐血事酸辛。","霸氣西南歇，雄圖曆數屯。","錦江元過楚，劒閣復通秦。","舊俗存祠廟，空山立鬼神。","虛簷交鳥道，枯木半龍鱗。","竹送清溪月，苔移玉座春。","閭閻兒女換，歌舞歲時新。","絕域歸舟遠，荒城繫馬頻。","如何對搖落，況乃久風塵。","孰與關張並，功臨耿鄧親。","應天才不小，得士契無鄰。","遲暮堪帷幄，飄零且釣緡。","向來憂國淚，寂寞灑衣巾。"]', '["慘淡风云會，乘时各有人。","力侔分社稷，志屈偃經綸。","复漢留长策，中原仗老臣。","杂耕心未已，歐血事酸辛。","霸氣西南歇，雄圖曆數屯。","錦江元過楚，劒閣复通秦。","旧俗存祠廟，空山立鬼神。","虛簷交鸟道，枯木半龙鱗。","竹送清溪月，苔移玉座春。","閭閻兒女換，歌舞歲时新。","絕域归舟远，荒城繫马頻。","如何对搖落，況乃久风塵。","孰與关張並，功臨耿鄧親。","應天才不小，得士契無鄰。","遲暮堪帷幄，飄零且釣緡。","向来憂国泪，寂寞灑衣巾。"]', '诗', 'shi', '', NULL, '謁先主廟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204563c9-a4ca-42f1-b9fb-350a373e1831', '白鹽山', '白鹽山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["卓立羣峰外，蟠根積水邊。","他皆任厚地，爾獨近高天。","白牓千家邑，清秋萬估船。","詞人取佳句，刻畫竟誰傳。"]', '["卓立羣峰外，蟠根積水邊。","他皆任厚地，爾独近高天。","白牓千家邑，清秋万估船。","词人取佳句，刻畫竟誰傳。"]', '诗', 'shi', '', NULL, '白鹽山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2709295-8e63-474a-97e9-506a1bcbd28b', '灩澦堆', '灩澦堆', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巨積水中央，江寒出水長。","沈牛荅雲雨，如馬戒舟航。","天意存傾覆，神功接混茫。","干戈連解纜，行止憶垂堂。"]', '["巨積水中央，江寒出水长。","沈牛荅云雨，如马戒舟航。","天意存傾覆，神功接混茫。","干戈連解纜，行止憶垂堂。"]', '诗', 'shi', '', NULL, '灩澦堆 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50ac001-7581-484a-93bd-667993c3b608', '灩澦', '灩澦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["灧澦既沒孤根深，西來水多愁太陰。","江天漠漠鳥雙去，風雨時時龍一吟。","舟人漁子歌迴首，估客胡商淚滿襟。","寄語舟航惡年少，休翻鹽井橫黃金。"]', '["灧澦既沒孤根深，西来水多愁太陰。","江天漠漠鸟雙去，风雨时时龙一吟。","舟人漁子歌迴首，估客胡商泪满襟。","寄語舟航惡年少，休翻鹽井橫黄金。"]', '诗', 'shi', '', NULL, '灩澦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f96e94c-3ccf-435a-8c67-9c0447f16d11', '白帝', '白帝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白帝城中雲出門，白帝城下雨翻盆。","高江急峽雷霆鬬，翠木蒼藤日月昏。","戎馬不如歸馬逸，千家今有百家存。","哀哀寡婦誅求盡，慟哭秋原何處村。"]', '["白帝城中云出门，白帝城下雨翻盆。","高江急峽雷霆鬬，翠木蒼藤日月昏。","戎马不如归马逸，千家今有百家存。","哀哀寡婦誅求尽，慟哭秋原何处村。"]', '诗', 'shi', '', NULL, '白帝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b148ee6a-a877-40a0-858a-40bf23f1bf26', '白帝城樓', '白帝城楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江度寒山閣，城高絕塞樓。","翠屏宜晚對，白谷會深遊。","急急能鳴鴈，輕輕不下鷗。","彝陵春色起，漸擬放扁舟。"]', '["江度寒山閣，城高絕塞楼。","翠屏宜晚对，白谷會深游。","急急能鳴鴈，轻轻不下鷗。","彝陵春色起，漸擬放扁舟。"]', '诗', 'shi', '', NULL, '白帝城樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5218857b-75ca-4ec2-9d8d-2ebd4d7075c4', '曉望白帝城鹽山', '晓望白帝城鹽山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["徐步移班杖，看山仰白頭。","翠深開斷壁，紅遠結飛樓。","日出清江望，暄和散旅愁。","春城見松雪，始擬進歸舟。"]', '["徐步移班杖，看山仰白头。","翠深开斷壁，紅远結飞楼。","日出清江望，暄和散旅愁。","春城见松雪，始擬進归舟。"]', '诗', 'shi', '', NULL, '曉望白帝城鹽山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0729417-079c-46a2-8d01-efb01e3f2d50', '白帝城最高樓', '白帝城最高楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城尖徑昃旌斾愁，獨立縹緲之飛樓。","峽坼雲霾龍虎臥，江清日抱黿鼉遊。","扶桑西枝對斷石，弱水東影隨長流。","杖藜歎世者誰子，泣血迸空迴白頭。"]', '["城尖徑昃旌斾愁，独立縹緲之飞楼。","峽坼云霾龙虎臥，江清日抱黿鼉游。","扶桑西枝对斷石，弱水东影隨长流。","杖藜歎世者誰子，泣血迸空迴白头。"]', '诗', 'shi', '', NULL, '白帝城最高樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726d3ed2-4b2b-42c0-a5a3-5fe1d91a6bf5', '白帝樓', '白帝楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漠漠虛無裏，連連睥睨侵。","樓光去日遠，峽影入江深。","臘破思端綺，春歸待一金。","去年梅柳意，還欲攪邊心。"]', '["漠漠虛無裏，連連睥睨侵。","楼光去日远，峽影入江深。","臘破思端綺，春归待一金。","去年梅柳意，還欲攪邊心。"]', '诗', 'shi', '', NULL, '白帝樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2138b8-a79c-435a-a1be-737188b31450', '陪諸公上白帝城宴越公堂之作', '陪諸公上白帝城宴越公堂之作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此堂存古製，城上俯江郊。","落構垂雲雨，荒階蔓草茅。","柱穿蜂溜蜜，棧缺燕添巢。","坐接春杯氣，心傷豔蘂梢。","英靈如過隙，宴衎願投膠。","莫問東流水，生涯未即拋。"]', '["此堂存古製，城上俯江郊。","落構垂云雨，荒階蔓草茅。","柱穿蜂溜蜜，棧缺燕添巢。","坐接春杯氣，心傷豔蘂梢。","英靈如過隙，宴衎願投膠。","莫问东流水，生涯未即拋。"]', '诗', 'shi', '', NULL, '陪諸公上白帝城宴越公堂之作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d3bcf8-a082-435c-83cc-381869968238', '峽隘', '峽隘', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞說江陵府，雲沙靜眇然。","白魚如切玉，朱橘不論錢。","水有遠湖樹，人今何處船。","青山各在眼，却望峽中天。"]', '["闻说江陵府，云沙静眇然。","白鱼如切玉，朱橘不論錢。","水有远湖樹，人今何处船。","青山各在眼，却望峽中天。"]', '诗', 'shi', '', NULL, '峽隘 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6a4293-c89f-4e4b-9365-be01edb02ccd', '諸葛廟', '諸葛廟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久遊巴子國，屢入武侯祠。","竹日斜虛寢，溪風滿薄帷。","君臣當共濟，賢聖亦同時。","翊戴歸先主，幷吞更出師。","蟲虵穿畫壁，巫覡醉蛛絲。","歘憶吟梁父，躬耕也未遲。"]', '["久游巴子国，屢入武侯祠。","竹日斜虛寢，溪风满薄帷。","君臣當共濟，賢聖亦同时。","翊戴归先主，幷吞更出師。","蟲虵穿畫壁，巫覡醉蛛絲。","歘憶吟梁父，躬耕也未遲。"]', '诗', 'shi', '', NULL, '諸葛廟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98fc0ac5-1c75-4c64-8e09-6813c8d1b9fc', '峽口二首 一', '峽口二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽口大江間，西南控百蠻。","城欹連粉堞，岸斷更青山。","開闢多天險，防隅一水關。","亂離聞鼓角，秋氣動衰顏。"]', '["峽口大江间，西南控百蠻。","城欹連粉堞，岸斷更青山。","开闢多天險，防隅一水关。","亂離闻鼓角，秋氣动衰顏。"]', '诗', 'shi', '', NULL, '峽口二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92010e4-10af-4ea9-8c98-31713be74c52', '峽口二首 二', '峽口二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["時清關失險，世亂戟如林。","去矣英雄事，荒哉割據心。","蘆花留客晚，楓樹坐猨深。","疲薾煩親故，諸侯數賜金。"]', '["时清关失險，世亂戟如林。","去矣英雄事，荒哉割據心。","蘆花留客晚，楓樹坐猨深。","疲薾煩親故，諸侯數賜金。"]', '诗', 'shi', '', NULL, '峽口二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5857487-ad9f-4ca2-b16f-bee669ac0def', '天池', '天池', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天池馬不到，嵐壁鳥纔通。","百頃青雲杪，層波白石中。","鬱紆騰秀氣，蕭瑟浸寒空。","直對巫山出，兼疑夏禹功。","魚龍開闢有，菱芡古今同。","聞道奔雷黑，初看浴日紅。","飄零神女雨，斷續楚王風。","欲問支機石，如臨獻寶宮。","九秋驚鴈序，萬里狎漁翁。","更是無人處，誅茅任薄躬。"]', '["天池马不到，嵐壁鸟纔通。","百頃青云杪，層波白石中。","鬱紆腾秀氣，蕭瑟浸寒空。","直对巫山出，兼疑夏禹功。","鱼龙开闢有，菱芡古今同。","闻道奔雷黑，初看浴日紅。","飄零神女雨，斷續楚王风。","欲问支機石，如臨獻寶宮。","九秋驚鴈序，万里狎漁翁。","更是無人处，誅茅任薄躬。"]', '诗', 'shi', '', NULL, '天池 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c996da5-8748-4457-9fb8-50556b2a2901', '瞿塘兩崖', '瞿塘兩崖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三峽傳何處，雙崖壯此門。","入天猶石色，穿水忽雲根。","猱攫鬚髯古，蛟龍窟宅尊。","羲和冬馭近，愁畏日車翻。"]', '["三峽傳何处，雙崖壯此门。","入天猶石色，穿水忽云根。","猱攫鬚髯古，蛟龙窟宅尊。","羲和冬馭近，愁畏日车翻。"]', '诗', 'shi', '', NULL, '瞿塘兩崖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972dea94-8001-40a3-88e1-ad588d2f0567', '夔州歌十絕句 一', '夔州歌十絕句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中巴之東巴東山，江水開闢流其間。","白帝高爲三峽鎮，夔州險過百牢關。"]', '["中巴之东巴东山，江水开闢流其间。","白帝高爲三峽鎮，夔州險過百牢关。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68078cf-e7db-43e9-b6d8-48cbdf5c09cc', '夔州歌十絕句 二', '夔州歌十絕句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白帝夔州各異城，蜀江楚峽混殊名。","英雄割據非天意，霸主幷吞在物情。"]', '["白帝夔州各異城，蜀江楚峽混殊名。","英雄割據非天意，霸主幷吞在物情。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb4b66d-fcae-4e98-ae5f-ae24d533e9fe', '夔州歌十絕句 三', '夔州歌十絕句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣雄競起問前朝，王者無外見今朝。","比訝漁陽結怨恨，元聽舜日舊簫韶。"]', '["羣雄競起问前朝，王者無外见今朝。","比訝漁陽結怨恨，元听舜日旧簫韶。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d804266-6776-4385-b2af-14af2b649671', '夔州歌十絕句 四', '夔州歌十絕句 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["赤甲白鹽俱刺天，閭閻繚繞接山巔。","楓林橘樹丹青合，複道重樓錦繡懸。"]', '["赤甲白鹽俱刺天，閭閻繚繞接山巔。","楓林橘樹丹青合，複道重楼錦繡懸。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c10dd3-d477-42a4-b40d-1f97cc3371a8', '夔州歌十絕句 五', '夔州歌十絕句 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["瀼東瀼西一萬家，江北江南春冬花。","背飛鶴子遺瓊蘂，相趁鳧雛入蔣牙。"]', '["瀼东瀼西一万家，江北江南春冬花。","背飞鹤子遺瓊蘂，相趁鳧雛入蔣牙。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1977b41a-e00a-457f-a4f1-42ad9c18acb1', '夔州歌十絕句 六', '夔州歌十絕句 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東屯稻畦一百頃，北有澗水通青苗。","晴浴狎鷗分處處，雨隨神女下朝朝。"]', '["东屯稻畦一百頃，北有澗水通青苗。","晴浴狎鷗分处处，雨隨神女下朝朝。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d102dbb2-b12f-474f-9a18-9bddbf511244', '夔州歌十絕句 七', '夔州歌十絕句 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蜀麻吳鹽自古通，萬斛之舟行若風。","長年三老長歌裏，白晝攤錢高浪中。"]', '["蜀麻吳鹽自古通，万斛之舟行若风。","长年三老长歌裏，白晝攤錢高浪中。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f4689b-85da-4d72-abb5-9b2c67bfc884', '夔州歌十絕句 八', '夔州歌十絕句 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昔咸陽都市合，山水之圖張賣時。","巫峽曾經寶屏見，楚宮猶對碧峰疑。"]', '["憶昔咸陽都市合，山水之圖張賣时。","巫峽曾經寶屏见，楚宮猶对碧峰疑。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e021009-78c1-46c6-bb7e-fe82fe759b2e', '夔州歌十絕句 九', '夔州歌十絕句 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["武侯祠堂不可忘，中有松柏參天長。","干戈滿地客愁破，雲日如火炎天涼。"]', '["武侯祠堂不可忘，中有松柏參天长。","干戈满地客愁破，云日如火炎天涼。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0e3fd3-1493-408b-a616-0b940072d222', '夔州歌十絕句 十', '夔州歌十絕句 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["閬風玄圃與蓬壺，中有高堂天下無。","借問夔州壓何處，峽門江腹擁城隅。"]', '["閬风玄圃與蓬壺，中有高堂天下無。","借问夔州壓何处，峽门江腹擁城隅。"]', '诗', 'shi', '', NULL, '夔州歌十絕句 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6762d2-ede5-4b41-9527-c3d8c8f91533', '上卿翁請修武侯廟遺像缺落時崔卿權夔州', '上卿翁請修武侯廟遺像缺落时崔卿權夔州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大賢爲政即多聞，刺史真符不必分。","尚有西郊諸葛廟，臥龍無首對江濆。"]', '["大賢爲政即多闻，刺史真符不必分。","尚有西郊諸葛廟，臥龙無首对江濆。"]', '诗', 'shi', '', NULL, '上卿翁請修武侯廟遺像缺落時崔卿權夔州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c95696d-8258-4661-a1ad-f34ad1e37cd1', '偶題', '偶題', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["文章千古事，得失寸心知。","作者皆殊列，名聲豈浪垂。","騷人嗟不見，漢道盛於斯。","前輩飛騰入，餘波綺麗爲。","後賢兼舊列，歷代各清規。","法自儒家有，心從弱歲疲。","永懷江左逸，多病鄴中奇。","騄驥皆良馬，騏驎帶好兒。","車輪徒已斵，堂構惜仍虧。","漫作潛夫論，虛傳幼婦碑。","緣情慰漂蕩，抱疾屢遷移。","經濟慙長策，飛棲假一枝。","塵沙傍蜂蠆，江峽繞蛟螭。","蕭瑟唐虞遠，聯翩楚漢危。","聖朝兼盜賊，異俗更喧卑。","鬱鬱星辰劒，蒼蒼雲雨池。","兩都開幕府，萬宇插軍麾。","南海殘銅柱，東風避月支。","音書恨烏鵲，號怒怪熊羆。","稼穡分詩興，柴荆學土宜。","故山迷白閣，秋水隱黃陂。","不敢要佳句，愁來賦別離。"]', '["文章千古事，得失寸心知。","作者皆殊列，名声豈浪垂。","騷人嗟不见，漢道盛於斯。","前輩飞腾入，餘波綺丽爲。","後賢兼旧列，歷代各清規。","法自儒家有，心從弱歲疲。","永懷江左逸，多病鄴中奇。","騄驥皆良马，騏驎带好兒。","车輪徒已斵，堂構惜仍虧。","漫作潛夫論，虛傳幼婦碑。","緣情慰漂蕩，抱疾屢遷移。","經濟慙长策，飞棲假一枝。","塵沙傍蜂蠆，江峽繞蛟螭。","蕭瑟唐虞远，聯翩楚漢危。","聖朝兼盜賊，異俗更喧卑。","鬱鬱星辰劒，蒼蒼云雨池。","兩都开幕府，万宇插軍麾。","南海殘銅柱，东风避月支。","音书恨烏鵲，號怒怪熊羆。","稼穡分诗兴，柴荆学土宜。","故山迷白閣，秋水隐黄陂。","不敢要佳句，愁来賦別離。"]', '诗', 'shi', '', NULL, '偶題 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a23446-cb6c-40e2-9d5f-81db0657f3d7', '秋興八首 一', '秋兴八首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["玉露凋傷楓樹林，巫山巫峽氣蕭森。","江間波浪兼天湧，塞上風雲接地陰。","叢菊兩開他日淚，孤舟一繫故園心。","寒衣處處催刀尺，白帝城高急暮砧。"]', '["玉露凋傷楓樹林，巫山巫峽氣蕭森。","江间波浪兼天湧，塞上风云接地陰。","叢菊兩开他日泪，孤舟一繫故园心。","寒衣处处催刀尺，白帝城高急暮砧。"]', '诗', 'shi', '', NULL, '秋興八首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15190dbd-fbb9-4a1a-b4b7-7bc94ea577ef', '秋興八首 二', '秋兴八首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夔府孤城落日斜，每依南斗望京華。","聽猨實下三聲淚，奉使虛隨八月查。","畫省香爐違伏枕，山樓粉堞隱悲笳。","請看石上藤蘿月，已暎洲前蘆荻花。"]', '["夔府孤城落日斜，每依南斗望京华。","听猨實下三声泪，奉使虛隨八月查。","畫省香爐違伏枕，山楼粉堞隐悲笳。","請看石上藤蘿月，已暎洲前蘆荻花。"]', '诗', 'shi', '', NULL, '秋興八首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0758afd3-8514-4ce5-a716-6c5b1d4ddb41', '秋興八首 三', '秋兴八首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["千家山郭靜朝暉，一日江樓坐翠微。","信宿漁人還汎汎，清秋燕子故飛飛。","匡衡抗疏功名薄，劉向傳經心事違。","同學少年多不賤，五陵衣馬自輕肥。"]', '["千家山郭静朝暉，一日江楼坐翠微。","信宿漁人還汎汎，清秋燕子故飞飞。","匡衡抗疏功名薄，劉向傳經心事違。","同学少年多不賤，五陵衣马自轻肥。"]', '诗', 'shi', '', NULL, '秋興八首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec1bfe2-0243-4f3c-9789-8bdbddc6a015', '秋興八首 四', '秋兴八首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道長安似弈棊，百年世事不勝悲。","王侯第宅皆新主，文武衣冠異昔時。","直北關山金鼓振，征西車馬羽書遲。","魚龍寂寞秋江冷，故國平居有所思。"]', '["闻道长安似弈棊，百年世事不勝悲。","王侯第宅皆新主，文武衣冠異昔时。","直北关山金鼓振，征西车马羽书遲。","鱼龙寂寞秋江冷，故国平居有所思。"]', '诗', 'shi', '', NULL, '秋興八首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e03b89ed-18ab-4576-ad30-fd5a6060f7a7', '秋興八首 五', '秋兴八首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蓬萊宮闕對南山，承露金莖霄漢間。","西望瑤池降王母，東來紫氣滿函關。","雲移雉尾開宮扇，日繞龍鱗識聖顏。","一臥滄江驚歲晚，幾迴青瑣照朝班。"]', '["蓬萊宮闕对南山，承露金莖霄漢间。","西望瑤池降王母，东来紫氣满函关。","云移雉尾开宮扇，日繞龙鱗識聖顏。","一臥滄江驚歲晚，幾迴青瑣照朝班。"]', '诗', 'shi', '', NULL, '秋興八首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d411317-d3fb-45c2-8a4d-b8d30987028e', '秋興八首 六', '秋兴八首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["瞿唐峽口曲江頭，萬里風煙接素秋。","花萼夾城通御氣，芙蓉小苑入邊愁。","朱簾繡柱圍黃鶴，錦纜牙檣起白鷗。","迴首可憐歌舞地，秦中自古帝王州。"]', '["瞿唐峽口曲江头，万里风煙接素秋。","花萼夾城通御氣，芙蓉小苑入邊愁。","朱簾繡柱圍黄鹤，錦纜牙檣起白鷗。","迴首可怜歌舞地，秦中自古帝王州。"]', '诗', 'shi', '', NULL, '秋興八首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e33874-18b2-4ad8-942e-41240bc9d97c', '秋興八首 七', '秋兴八首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昆明池水漢時功，武帝旌旗在眼中。","織女機絲虛月夜，石鯨鱗甲動秋風。","波漂菰米沈雲黑，露冷蓮房墜粉紅。","關塞極天唯鳥道，江湖滿地一漁翁。"]', '["昆明池水漢时功，武帝旌旗在眼中。","织女機絲虛月夜，石鯨鱗甲动秋风。","波漂菰米沈云黑，露冷蓮房墜粉紅。","关塞極天唯鸟道，江湖满地一漁翁。"]', '诗', 'shi', '', NULL, '秋興八首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcc9d85-c605-489c-a8ce-8233c26bbb8d', '秋興八首 八', '秋兴八首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昆吾御宿自逶迤，紫閣峰陰入渼陂。","香稻啄餘鸚鵡粒，碧梧棲老鳳皇枝。","佳人拾翠春相問，仙侶同舟晚更移。","綵筆昔遊干氣象，白頭吟望苦低垂。"]', '["昆吾御宿自逶迤，紫閣峰陰入渼陂。","香稻啄餘鸚鵡粒，碧梧棲老鳳皇枝。","佳人拾翠春相问，仙侶同舟晚更移。","綵笔昔游干氣象，白头吟望苦低垂。"]', '诗', 'shi', '', NULL, '秋興八首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03eb4001-023a-4920-bbc7-a0fc52b2836d', '詠懷古跡五首 一', '詠懷古跡五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["支離東北風塵際，漂泊西南天地間。","三峽樓臺淹日月，五溪衣服共雲山。","羯胡事主終無賴，詞客衰時且未還。","庾信平生最蕭瑟，暮年詩賦動江關。"]', '["支離东北风塵際，漂泊西南天地间。","三峽楼台淹日月，五溪衣服共云山。","羯胡事主終無賴，词客衰时且未還。","庾信平生最蕭瑟，暮年诗賦动江关。"]', '诗', 'shi', '', NULL, '詠懷古跡五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acbe1729-cefd-4678-9719-09c5c9c27db0', '詠懷古跡五首 二', '詠懷古跡五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["搖落深知宋玉悲，風流儒雅亦吾師。","悵望千秋一灑淚，蕭條異代不同時。","江山故宅空文藻，雲雨荒臺豈夢思。","最是楚宮俱泯滅，舟人指點到今疑。"]', '["搖落深知宋玉悲，风流儒雅亦吾師。","悵望千秋一灑泪，蕭條異代不同时。","江山故宅空文藻，云雨荒台豈梦思。","最是楚宮俱泯滅，舟人指点到今疑。"]', '诗', 'shi', '', NULL, '詠懷古跡五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5db620-1964-4674-a01d-ad70ba3ebd2a', '詠懷古跡五首 三', '詠懷古跡五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣山萬壑赴荆門，生長明妃尚有村。","一去紫臺連朔漠，獨留青塚向黃昏。","畫圖省識春風面，環佩空歸月夜魂。","千載琵琶作胡語，分明怨恨曲中論。"]', '["羣山万壑赴荆门，生长明妃尚有村。","一去紫台連朔漠，独留青塚向黄昏。","畫圖省識春风面，环佩空归月夜魂。","千載琵琶作胡語，分明怨恨曲中論。"]', '诗', 'shi', '', NULL, '詠懷古跡五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733afc7b-e370-4724-b755-e9342c574d22', '詠懷古跡五首 四', '詠懷古跡五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蜀主窺吳幸三峽，崩年亦在永安宮。","翠華想像空山裏，玉殿虛無野寺中。","古廟杉松巢水鶴，歲時伏臘走村翁。","武侯祠屋常鄰近，一體君臣祭祀同。"]', '["蜀主窺吳幸三峽，崩年亦在永安宮。","翠华想像空山裏，玉殿虛無野寺中。","古廟杉松巢水鹤，歲时伏臘走村翁。","武侯祠屋常鄰近，一體君臣祭祀同。"]', '诗', 'shi', '', NULL, '詠懷古跡五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f5949b-bdad-4b5e-b488-7015bd45cc4f', '詠懷古跡五首 五', '詠懷古跡五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["諸葛大名垂宇宙，宗臣遺像肅清高。","三分割據紆籌策，萬古雲霄一羽毛。","伯仲之間見伊呂，指揮若定失蕭曹。","福移漢祚難恢復，志決身殲軍務勞。"]', '["諸葛大名垂宇宙，宗臣遺像肅清高。","三分割據紆籌策，万古云霄一羽毛。","伯仲之间见伊呂，指揮若定失蕭曹。","福移漢祚难恢复，志決身殲軍務勞。"]', '诗', 'shi', '', NULL, '詠懷古跡五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ff3fc01-3028-4ee9-b1a4-f9f8fbe14464', '諸將五首 一', '諸將五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢朝陵暮對南山，胡虜千秋尚入關。","昨日玉魚蒙葬地，早時今盌出人間。","見愁汗馬西戎逼，曾閃朱旗北斗殷。","多少材官守涇渭，將軍且莫破愁顏。"]', '["漢朝陵暮对南山，胡虜千秋尚入关。","昨日玉鱼蒙葬地，早时今盌出人间。","见愁汗马西戎逼，曾閃朱旗北斗殷。","多少材官守涇渭，將軍且莫破愁顏。"]', '诗', 'shi', '', NULL, '諸將五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246ff1f1-9148-400a-930e-635dbdc699b9', '諸將五首 二', '諸將五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["韓公本意築三城，擬絕天驕拔漢旌。","豈謂盡煩回紇馬，翻然遠救朔方兵胡來不覺潼關隘，龍起猶聞晉水清。","獨使至尊憂社稷，諸君何以荅升平。"]', '["韓公本意築三城，擬絕天驕拔漢旌。","豈謂尽煩回紇马，翻然远救朔方兵胡来不覺潼关隘，龙起猶闻晉水清。","独使至尊憂社稷，諸君何以荅升平。"]', '诗', 'shi', '', NULL, '諸將五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbd2f90-69ec-4f6a-9407-3092f035909a', '諸將五首 三', '諸將五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洛陽宮殿化爲烽，休道秦關百二重。","滄海未全歸禹貢，薊門何處盡堯封。","朝廷衮職雖多預，天下軍儲不自供。","稍喜臨邊王相國，肯銷金甲事春農。"]', '["洛陽宮殿化爲烽，休道秦关百二重。","滄海未全归禹貢，薊门何处尽堯封。","朝廷衮職雖多預，天下軍儲不自供。","稍喜臨邊王相国，肯銷金甲事春農。"]', '诗', 'shi', '', NULL, '諸將五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9019bc9b-6b53-4266-9933-cab4fdaac333', '諸將五首 四', '諸將五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["迴首扶桑銅柱標，冥冥氛祲未全銷。","越裳翡翠無消息，南海明珠久寂寥。","殊錫曾爲大司馬，總戎皆插侍中貂。","炎風朔雪天王地，只在忠臣翊聖朝。"]', '["迴首扶桑銅柱標，冥冥氛祲未全銷。","越裳翡翠無消息，南海明珠久寂寥。","殊錫曾爲大司马，總戎皆插侍中貂。","炎风朔雪天王地，只在忠臣翊聖朝。"]', '诗', 'shi', '', NULL, '諸將五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9044d831-e82f-44c9-9b36-176a8bac0d5e', '諸將五首 五', '諸將五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["錦江春色逐人來，巫峽清秋萬壑哀。","正憶往時嚴僕射，共迎中使望鄉臺。","主恩前後三持節，軍令分明數舉桮。","西蜀地形天下險，安危須仗出羣材。"]', '["錦江春色逐人来，巫峽清秋万壑哀。","正憶往时嚴僕射，共迎中使望乡台。","主恩前後三持節，軍令分明數舉桮。","西蜀地形天下險，安危須仗出羣材。"]', '诗', 'shi', '', NULL, '諸將五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3aec75e-d67c-4a40-920a-c3ccbac03993', '秋日夔府詠懷奉寄鄭監李賓客一百韻', '秋日夔府詠懷奉寄鄭監李賓客一百韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["絕塞烏蠻北，孤城白帝邊。","飄零仍百里，消渴已三年。","雄劒鳴開匣，羣書滿繫船。","亂離心不展，衰謝日蕭然。","筋力妻孥問，菁華歲月遷。","登臨多物色，陶冶賴詩篇。","峽束滄江起，巖排石樹圓。","拂雲霾楚氣，朝海蹴吳天。","煮井爲鹽速，燒畬度地偏。","有時驚疊嶂，何處覓平川。","鸂鶒雙雙舞，獼猿壘壘懸。","碧蘿長似帶，錦石小如錢。","春草何曾歇，寒花亦可憐。","獵人吹戍火，野店引山泉。","喚起搔頭急，扶行幾屐穿。","兩京猶薄產，四海絕隨肩。","幕府初交辟，郎官幸備員。","瓜時猶旅寓，萍泛苦夤緣。","藥餌虛狼藉，秋風灑靜便。","開襟驅瘴癘，明目掃雲煙。","高宴諸侯禮，佳人上客前。","哀箏傷老大，華屋豔神仙。","南內開元曲，常時弟子傳。","法歌聲變轉，滿座涕潺湲。","弔影夔州僻，回腸杜曲煎。","即今龍廄水，莫帶犬戎羶。","耿賈扶王室，蕭曹拱御筵。","乘威滅蜂蠆，戮力効鷹鸇。","舊物森猶在，凶徒惡未悛。","國須行戰伐，人憶止戈鋋。","奴僕何知禮，恩榮錯與權。","胡星一彗孛，黔首逐拘攣。","哀痛絲綸切，煩苛法令蠲。","業成陳始王，兆喜出於畋。","宮禁經綸密，台階翊戴全。","熊羆載呂望，鴻雁美周宣。","側聽中興主，長吟不世賢。","音徽一柱數，道里下牢千。","鄭李光時論，文章並我先。","陰何尚清省，沈宋歘聯翩。","律比崑崙竹，音知燥濕弦。","風流俱善價，愜當久忘筌。","置驛常如此，登龍蓋有焉。","雖云隔禮數，不敢墜周旋。","高視收人表，虛心味道玄。","馬來皆汗血，鶴唳必青田。","羽翼商山起，蓬萊漢閣連。","管寧紗帽淨，江令錦袍鮮。","東郡時題壁，南湖日扣舷。","遠遊凌絕境，佳句染華牋。","每欲孤飛去，徒爲百慮牽。","生涯已寥落，國步乃迍邅。","衾枕成蕪沒，池塘作棄捐。","別離憂怛怛，伏臘涕漣漣。","露菊班豐鎬，秋蔬影澗瀍。","共誰論昔事，幾處有新阡。","富貴空迴首，喧爭嬾著鞭。","兵戈塵漠漠，江漢月娟娟。","局促看秋燕，蕭疎聽晚蟬。","雕蟲蒙記憶，烹鯉問沈綿。","卜羨君平杖，偷存子敬氈。","囊虛把釵釧，米盡坼花鈿。","甘子陰涼葉，茅齋八九椽。","陣圖沙北岸，市暨瀼西巔。","羈絆心常折，棲遲病即痊。","紫收岷嶺芋，白種陸池蓮。","色好梨勝頰，穰多栗過拳。","勅廚唯一味，求飽或三鱣。","兒去看魚笱，人來坐馬韉。","縛柴門窄窄，通竹溜涓涓。","塹抵公畦稜，村依野廟壖。","缺籬將棘拒，倒石賴藤纏。","借問頻朝謁，何如穩醉眠。","誰云行不逮，自覺坐能堅。","霧雨銀章澀，馨香粉署妍。","紫鸞無近遠，黃雀任翩翾。","困學違從衆，明公各勉旃。","聲華夾宸極，早晚到星躔。","懇諫留匡鼎，諸儒引服虔。","不逢輸鯁直，會是正陶甄。","宵旰憂虞軫，黎元疾苦駢。","雲臺終日畫，青簡爲誰編。","行路難何有，招尋興已專。","由來具飛檝，蹔擬控鳴弦。","身許雙峰寺，門求七祖禪。","落帆追宿昔，衣褐向真詮。","安石名高晉，昭王客赴燕。","途中非阮籍，查上似張騫。","披拂雲寧在，淹留景不延。","風期終破浪，水怪莫飛涎。","他日辭神女，傷春怯杜鵑。","淡交隨聚散，澤國繞迴旋。","本自依迦葉，何曾藉偓佺。","鑪峯生轉盻，橘井尚高褰。","東走窮歸鶴，南征盡跕鳶。","晚聞多妙教，卒踐塞前愆。","顧凱丹青列，頭陀琬琰鐫。","衆香深黯黯，幾地肅芊芊。","勇猛爲心極，清羸任體孱。","金蓖空刮眼，鏡象未離銓。"]', '["絕塞烏蠻北，孤城白帝邊。","飄零仍百里，消渴已三年。","雄劒鳴开匣，羣书满繫船。","亂離心不展，衰謝日蕭然。","筋力妻孥问，菁华歲月遷。","登臨多物色，陶冶賴诗篇。","峽束滄江起，巖排石樹圓。","拂云霾楚氣，朝海蹴吳天。","煮井爲鹽速，燒畬度地偏。","有时驚叠嶂，何处覓平川。","鸂鶒雙雙舞，獼猿壘壘懸。","碧蘿长似带，錦石小如錢。","春草何曾歇，寒花亦可怜。","獵人吹戍火，野店引山泉。","喚起搔头急，扶行幾屐穿。","兩京猶薄產，四海絕隨肩。","幕府初交辟，郎官幸備員。","瓜时猶旅寓，萍泛苦夤緣。","藥餌虛狼藉，秋风灑静便。","开襟驱瘴癘，明目掃云煙。","高宴諸侯禮，佳人上客前。","哀箏傷老大，华屋豔神仙。","南內开元曲，常时弟子傳。","法歌声变轉，满座涕潺湲。","弔影夔州僻，回腸杜曲煎。","即今龙廄水，莫带犬戎羶。","耿賈扶王室，蕭曹拱御筵。","乘威滅蜂蠆，戮力効鷹鸇。","旧物森猶在，凶徒惡未悛。","国須行戰伐，人憶止戈鋋。","奴僕何知禮，恩榮錯與權。","胡星一彗孛，黔首逐拘攣。","哀痛絲綸切，煩苛法令蠲。","業成陳始王，兆喜出於畋。","宮禁經綸密，台階翊戴全。","熊羆載呂望，鴻雁美周宣。","側听中兴主，长吟不世賢。","音徽一柱數，道里下牢千。","鄭李光时論，文章並我先。","陰何尚清省，沈宋歘聯翩。","律比崑崙竹，音知燥濕弦。","风流俱善價，愜當久忘筌。","置驛常如此，登龙蓋有焉。","雖云隔禮數，不敢墜周旋。","高視收人表，虛心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬萊漢閣連。","管寧紗帽淨，江令錦袍鲜。","东郡时題壁，南湖日扣舷。","远游凌絕境，佳句染华牋。","每欲孤飞去，徒爲百慮牽。","生涯已寥落，国步乃迍邅。","衾枕成蕪沒，池塘作棄捐。","別離憂怛怛，伏臘涕漣漣。","露菊班豐鎬，秋蔬影澗瀍。","共誰論昔事，幾处有新阡。","富貴空迴首，喧爭嬾著鞭。","兵戈塵漠漠，江漢月娟娟。","局促看秋燕，蕭疎听晚蟬。","雕蟲蒙記憶，烹鯉问沈綿。","卜羨君平杖，偷存子敬氈。","囊虛把釵釧，米尽坼花鈿。","甘子陰涼葉，茅斋八九椽。","陣圖沙北岸，市暨瀼西巔。","羈絆心常折，棲遲病即痊。","紫收岷嶺芋，白種陸池蓮。","色好梨勝頰，穰多栗過拳。","勅廚唯一味，求飽或三鱣。","兒去看鱼笱，人来坐马韉。","縛柴门窄窄，通竹溜涓涓。","塹抵公畦稜，村依野廟壖。","缺籬將棘拒，倒石賴藤纏。","借问頻朝謁，何如穩醉眠。","誰云行不逮，自覺坐能堅。","霧雨銀章澀，馨香粉署妍。","紫鸾無近远，黄雀任翩翾。","困学違從衆，明公各勉旃。","声华夾宸極，早晚到星躔。","懇諫留匡鼎，諸儒引服虔。","不逢輸鯁直，會是正陶甄。","宵旰憂虞軫，黎元疾苦駢。","云台終日畫，青簡爲誰編。","行路难何有，招尋兴已專。","由来具飞檝，蹔擬控鳴弦。","身許雙峰寺，门求七祖禪。","落帆追宿昔，衣褐向真詮。","安石名高晉，昭王客赴燕。","途中非阮籍，查上似張騫。","披拂云寧在，淹留景不延。","风期終破浪，水怪莫飞涎。","他日辞神女，傷春怯杜鵑。","淡交隨聚散，澤国繞迴旋。","本自依迦葉，何曾藉偓佺。","鑪峯生轉盻，橘井尚高褰。","东走窮归鹤，南征尽跕鳶。","晚闻多妙教，卒踐塞前愆。","顧凱丹青列，头陀琬琰鐫。","衆香深黯黯，幾地肅芊芊。","勇猛爲心極，清羸任體孱。","金蓖空刮眼，镜象未離銓。"]', '诗', 'shi', '', NULL, '秋日夔府詠懷奉寄鄭監李賓客一百韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20a6a82e-639c-4244-a3c4-193f16fd0b57', '贈李八祕書別三十韻', '贈李八祕书別三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["往時中補右，扈蹕上元初。","反氣凌行在，妖星下直廬。","六龍瞻漢闕，萬騎略姚墟。","玄朔迴天步，神都憶帝車。","一戎纔汗馬，百姓免爲魚。","通籍蟠螭印，差肩列鳳輿。","事殊迎代邸，喜異賞朱虛。","寇盜方歸順，乾坤欲晏如。","不才同補衮，奉詔許牽裾。","鴛鷺叨雲閣，麒麟滯玉除。","文園多病後，中散舊交疎。","飄泊哀相見，平生意有餘。","風煙巫峽遠，臺榭楚宮虛。","觸目非論故，新文尚起予。","清秋凋碧柳，別浦落紅蕖。","消息多旗幟，經過嘆里閭。","戰連唇齒國，軍急羽毛書。","幕府籌頻問，山家藥正鋤。","台星入朝謁，使節有吹噓。","西蜀災長弭，南翁憤始攄。","對敭抏士卒，乾沒費倉儲。","勢藉兵須用，功無禮忽諸。","御鞍金騕褭，宮硯玉蟾蜍。","拜舞銀鉤落，恩波錦帕舒。","此行非不濟，良友昔相於。","去斾依顏色，沿流想疾徐。","沈綿疲井臼，倚薄似樵漁。","乞米煩佳客，鈔詩聽小胥。","杜陵斜晚照，潏水帶寒淤。","莫話清溪髮，蕭蕭白暎梳。"]', '["往时中補右，扈蹕上元初。","反氣凌行在，妖星下直廬。","六龙瞻漢闕，万騎略姚墟。","玄朔迴天步，神都憶帝车。","一戎纔汗马，百姓免爲鱼。","通籍蟠螭印，差肩列鳳輿。","事殊迎代邸，喜異賞朱虛。","寇盜方归順，乾坤欲晏如。","不才同補衮，奉詔許牽裾。","鴛鷺叨云閣，麒麟滯玉除。","文园多病後，中散旧交疎。","飄泊哀相见，平生意有餘。","风煙巫峽远，台榭楚宮虛。","觸目非論故，新文尚起予。","清秋凋碧柳，別浦落紅蕖。","消息多旗幟，經過嘆里閭。","戰連唇齒国，軍急羽毛书。","幕府籌頻问，山家藥正鋤。","台星入朝謁，使節有吹噓。","西蜀災长弭，南翁憤始攄。","对敭抏士卒，乾沒費倉儲。","勢藉兵須用，功無禮忽諸。","御鞍金騕褭，宮硯玉蟾蜍。","拜舞銀鉤落，恩波錦帕舒。","此行非不濟，良友昔相於。","去斾依顏色，沿流想疾徐。","沈綿疲井臼，倚薄似樵漁。","乞米煩佳客，鈔诗听小胥。","杜陵斜晚照，潏水带寒淤。","莫話清溪髮，蕭蕭白暎梳。"]', '诗', 'shi', '', NULL, '贈李八祕書別三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d76232-2003-4be8-98d5-3a435a067c71', '寄劉峽州伯華使君四十韻', '寄劉峽州伯华使君四十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽內多雲雨，秋來尚鬱蒸。","遠山朝白帝，深水謁彝陵。","遲暮嗟爲客，西南喜得朋。","哀猨更起坐，落雁失飛騰。","伏枕思瓊樹，臨軒對玉繩。","青松寒不落，碧海闊逾澄。","昔歲文爲理，羣公價盡增。","家聲同令聞，時論以儒稱。","太后當朝肅，多才接跡昇。","翠虛捎魍魎，丹極上鵾鵬。","宴引春壺滿，恩分夏簟冰。","彫章五色筆，紫殿九華燈。","學並盧王敏，書偕褚薛能。","老兄真不墜，小子獨無承。","近有風流作，聊從月繼徵。","放蹄知赤驥，捩翅服蒼鷹。","卷軸來何晚，襟懷庶可憑。","會期吟諷數，益破旅愁凝。","雕刻初誰料，纖毫欲自矜。","神融躡飛動，戰勝洗侵凌。","妙取筌蹄棄，高宜百萬層。","白頭遺恨在，青竹幾人登。","迴首追談笑，勞歌跼寢興。","年華紛已矣，世故莽相仍。","刺史諸侯貴，郎官列宿應。","潘生驂閣遠，黃霸璽書增。","乳贙號攀石，飢鼯訴落藤。","藥囊親道士，灰劫問胡僧。","憑久烏皮折，簪稀白帽稜。","林居看蟻穴，野食行魚罾。","筋力交彫喪，飄零免戰兢。","皆爲百里宰，正似六安丞。","姹女縈新裹，丹砂冷舊秤。","但求椿壽永，莫慮杞天崩。","鍊骨調情性，張兵撓棘矜。","養生終自惜，伐數必全懲。","政術甘疎誕，詞場媿服膺。","展懷詩誦魯，割愛酒如澠。","咄咄寧書字，冥冥欲避矰。","江湖多白鳥，天地有青蠅。"]', '["峽內多云雨，秋来尚鬱蒸。","远山朝白帝，深水謁彝陵。","遲暮嗟爲客，西南喜得朋。","哀猨更起坐，落雁失飞腾。","伏枕思瓊樹，臨軒对玉繩。","青松寒不落，碧海闊逾澄。","昔歲文爲理，羣公價尽增。","家声同令闻，时論以儒稱。","太后當朝肅，多才接跡昇。","翠虛捎魍魎，丹極上鵾鵬。","宴引春壺满，恩分夏簟冰。","彫章五色笔，紫殿九华灯。","学並盧王敏，书偕褚薛能。","老兄真不墜，小子独無承。","近有风流作，聊從月繼徵。","放蹄知赤驥，捩翅服蒼鷹。","卷軸来何晚，襟懷庶可憑。","會期吟諷數，益破旅愁凝。","雕刻初誰料，纖毫欲自矜。","神融躡飞动，戰勝洗侵凌。","妙取筌蹄棄，高宜百万層。","白头遺恨在，青竹幾人登。","迴首追談笑，勞歌跼寢兴。","年华紛已矣，世故莽相仍。","刺史諸侯貴，郎官列宿應。","潘生驂閣远，黄霸璽书增。","乳贙號攀石，飢鼯訴落藤。","藥囊親道士，灰劫问胡僧。","憑久烏皮折，簪稀白帽稜。","林居看蟻穴，野食行鱼罾。","筋力交彫喪，飄零免戰兢。","皆爲百里宰，正似六安丞。","姹女縈新裹，丹砂冷旧秤。","但求椿壽永，莫慮杞天崩。","鍊骨調情性，張兵撓棘矜。","養生終自惜，伐數必全懲。","政術甘疎誕，词場媿服膺。","展懷诗誦魯，割愛酒如澠。","咄咄寧书字，冥冥欲避矰。","江湖多白鸟，天地有青蠅。"]', '诗', 'shi', '', NULL, '寄劉峽州伯華使君四十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7860ea4-d771-4091-8590-dbaa77bf1729', '夔府書懷四十韻', '夔府书懷四十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔罷河西尉，初興薊北師。","不才名位晚，敢恨省郎遲。","扈聖崆峒日，端居灧澦時。","萍流仍汲引，樗散尚恩慈。","遂阻雲臺宿，常懷湛露詩。","翠華森遠矣，白首颯淒其。","拙被林泉滯，生逢酒賦欺。","文園終寂寞，漢閣自磷緇。","病隔君臣議，慚紆德澤私。","揚鑣驚主辱，拔劒撥年衰。","社稷經綸地，風雲際會期。","血流紛在眼，涕灑亂交頤。","四瀆樓船汎，中原鼓角悲。","賊壕連白翟，戰瓦落丹墀。","先帝嚴靈寢，宗臣切受遺。","恆山猶突騎，遼海競張旗。","田父嗟膠漆，行人避蒺藜。","總戎存大體，降將餙卑詞。","楚貢何年絕，堯封舊俗疑。","長吁翻北寇，一望卷西夷。","不必陪玄圃，超然待具茨。","凶兵鑄農器，講殿闢書帷。","廟算高難測，天憂實在茲。","形容真潦倒，荅效莫支持。","使者分王命，羣公各典司。","恐乖均賦歛，不似問瘡痍。","萬里煩供給，孤城最怨思。","綠林寧小患，雲夢欲難追。","即事須嘗膽，蒼生可察眉。","議堂猶集鳳，正觀是元龜。","處處喧飛檄，家家急競錐。","蕭車安不定，蜀使下何之。","釣瀨疎墳籍，耕巖進弈棊。","地蒸餘破扇，冬煖更纖絺。","豺遘哀登楚麟傷泣象尼。","衣冠迷適越，藻繪憶遊睢。","賞月延秋桂，傾陽逐露葵。","大庭終反樸，京觀且僵尸。","高枕虛眠晝，哀歌欲和誰。","南宮載勳業，凡百慎交綏。"]', '["昔罷河西尉，初兴薊北師。","不才名位晚，敢恨省郎遲。","扈聖崆峒日，端居灧澦时。","萍流仍汲引，樗散尚恩慈。","遂阻云台宿，常懷湛露诗。","翠华森远矣，白首颯淒其。","拙被林泉滯，生逢酒賦欺。","文园終寂寞，漢閣自磷緇。","病隔君臣議，慚紆德澤私。","揚鑣驚主辱，拔劒撥年衰。","社稷經綸地，风云際會期。","血流紛在眼，涕灑亂交頤。","四瀆楼船汎，中原鼓角悲。","賊壕連白翟，戰瓦落丹墀。","先帝嚴靈寢，宗臣切受遺。","恆山猶突騎，遼海競張旗。","田父嗟膠漆，行人避蒺藜。","總戎存大體，降將餙卑词。","楚貢何年絕，堯封旧俗疑。","长吁翻北寇，一望卷西夷。","不必陪玄圃，超然待具茨。","凶兵鑄農器，講殿闢书帷。","廟算高难測，天憂實在茲。","形容真潦倒，荅效莫支持。","使者分王命，羣公各典司。","恐乖均賦歛，不似问瘡痍。","万里煩供給，孤城最怨思。","綠林寧小患，云梦欲难追。","即事須嘗膽，蒼生可察眉。","議堂猶集鳳，正观是元龟。","处处喧飞檄，家家急競錐。","蕭车安不定，蜀使下何之。","釣瀨疎墳籍，耕巖進弈棊。","地蒸餘破扇，冬煖更纖絺。","豺遘哀登楚麟傷泣象尼。","衣冠迷適越，藻繪憶游睢。","賞月延秋桂，傾陽逐露葵。","大庭終反樸，京观且僵尸。","高枕虛眠晝，哀歌欲和誰。","南宮載勳業，凡百慎交綏。"]', '诗', 'shi', '', NULL, '夔府書懷四十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18580212-5d9c-4483-a89d-bd5e0b9c62c9', '解悶十二首 一', '解悶十二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草閣柴扉星散居，浪翻江黑雨飛初。","山禽引子哺紅果，溪友得錢留白魚。"]', '["草閣柴扉星散居，浪翻江黑雨飞初。","山禽引子哺紅果，溪友得錢留白鱼。"]', '诗', 'shi', '', NULL, '解悶十二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379e8d48-0acb-460a-ad3f-4876e6eb6871', '解悶十二首 二', '解悶十二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["商胡離別下揚州，憶上西陵故驛樓。","爲問淮南米貴賤，老夫乘興欲東流。"]', '["商胡離別下揚州，憶上西陵故驛楼。","爲问淮南米貴賤，老夫乘兴欲东流。"]', '诗', 'shi', '', NULL, '解悶十二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde0bff4-e96a-477b-bcf2-1e6ecb389d21', '解悶十二首 三', '解悶十二首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一辭故國十經秋，每見秋瓜憶故丘。","今日南湖采薇蕨，何人爲覓鄭瓜州。"]', '["一辞故国十經秋，每见秋瓜憶故丘。","今日南湖采薇蕨，何人爲覓鄭瓜州。"]', '诗', 'shi', '', NULL, '解悶十二首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087495fe-5873-442a-9812-deba83408432', '解悶十二首 四', '解悶十二首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["沈范早知何水部，曹劉不待薛郎中。","獨當省署開文苑，兼泛滄浪學釣翁。"]', '["沈范早知何水部，曹劉不待薛郎中。","独當省署开文苑，兼泛滄浪学釣翁。"]', '诗', 'shi', '', NULL, '解悶十二首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef6c5d9-9aba-4405-9d2a-b97f0866e1f3', '解悶十二首 五', '解悶十二首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["李陵蘇武是吾師，孟子論文更不疑。","一飯未曾留俗客，數篇今見古人詩。"]', '["李陵蘇武是吾師，孟子論文更不疑。","一飯未曾留俗客，數篇今见古人诗。"]', '诗', 'shi', '', NULL, '解悶十二首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52903113-79ce-407c-8525-a5f93bef88f4', '解悶十二首 六', '解悶十二首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["復憶襄陽孟浩然，清詩句句盡堪傳。","即今耆舊無新語，漫釣槎頭縮頸鯿。"]', '["复憶襄陽孟浩然，清诗句句尽堪傳。","即今耆旧無新語，漫釣槎头縮頸鯿。"]', '诗', 'shi', '', NULL, '解悶十二首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce47635-1efb-4ec1-9bf3-54b11a23e311', '解悶十二首 七', '解悶十二首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陶冶性靈在底物，新詩改罷自長吟。","孰知二謝將能事，頗學陰何苦用心。"]', '["陶冶性靈在底物，新诗改罷自长吟。","孰知二謝將能事，頗学陰何苦用心。"]', '诗', 'shi', '', NULL, '解悶十二首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5ac262-5291-469f-9fb7-6421b006dd35', '解悶十二首 八', '解悶十二首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不見高人王右丞，藍田丘壑漫寒藤。","最傳秀句寰區滿，未絕風流相國能。"]', '["不见高人王右丞，藍田丘壑漫寒藤。","最傳秀句寰區满，未絕风流相国能。"]', '诗', 'shi', '', NULL, '解悶十二首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d45caed5-bc9a-4c16-836a-97e68e9b2f81', '解悶十二首 九', '解悶十二首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["先帝貴妃今寂寞，荔枝還復入長安。","炎方每續朱[櫻]獻，玉座應悲白露[團]。"]', '["先帝貴妃今寂寞，荔枝還复入长安。","炎方每續朱[櫻]獻，玉座應悲白露[團]。"]', '诗', 'shi', '', NULL, '解悶十二首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094c888f-a963-43dc-9e4e-b1b644c54abe', '解悶十二首 十', '解悶十二首 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶過瀘戎摘荔枝，青峰隱暎石逶迤。","京中舊見無顏色，紅顆酸甜只自知。"]', '["憶過瀘戎摘荔枝，青峰隐暎石逶迤。","京中旧见無顏色，紅顆酸甜只自知。"]', '诗', 'shi', '', NULL, '解悶十二首 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac97eedb-6cc1-4f92-99e2-96b5ea8d9f33', '解悶十二首 十一', '解悶十二首 十一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["翠瓜碧李沈玉甃，赤梨葡萄寒露成。","可憐先不異枝蔓，此物娟娟長遠生。"]', '["翠瓜碧李沈玉甃，赤梨葡萄寒露成。","可怜先不異枝蔓，此物娟娟长远生。"]', '诗', 'shi', '', NULL, '解悶十二首 十一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4485a172-5b62-4e71-b05f-813691727067', '解悶十二首 十二', '解悶十二首 十二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["側生野岸及江蒲，不熟丹宮滿玉壺。","雲壑布衣駘背死，勞生重馬翠眉須。"]', '["側生野岸及江蒲，不熟丹宮满玉壺。","云壑布衣駘背死，勞生重马翠眉須。"]', '诗', 'shi', '', NULL, '解悶十二首 十二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf2f562-6df5-40d1-9349-e17b5fe06ede', '復愁十二首 一', '复愁十二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["人煙生處僻，虎跡過新蹄。","野鶻翻窺草，村船逆上溪。"]', '["人煙生处僻，虎跡過新蹄。","野鶻翻窺草，村船逆上溪。"]', '诗', 'shi', '', NULL, '復愁十二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92d5da0-e175-46f5-b49f-4224da3994b7', '復愁十二首 二', '复愁十二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["釣艇收緡盡，昏鴉接翅歸。","月生初學扇，雲細不成衣。"]', '["釣艇收緡尽，昏鴉接翅归。","月生初学扇，云細不成衣。"]', '诗', 'shi', '', NULL, '復愁十二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a398f1df-df49-4789-bc09-bce62a11362d', '復愁十二首 三', '复愁十二首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬國尚防寇，故園今若何。","昔歸相識少，早已戰場多。"]', '["万国尚防寇，故园今若何。","昔归相識少，早已戰場多。"]', '诗', 'shi', '', NULL, '復愁十二首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3df8abc-67d3-4dbf-9e24-0e647dadb3dd', '復愁十二首 四', '复愁十二首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["身覺省郎在，家須農事歸。","年深荒草徑，老恐失柴扉。"]', '["身覺省郎在，家須農事归。","年深荒草徑，老恐失柴扉。"]', '诗', 'shi', '', NULL, '復愁十二首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741560f7-c9c5-48fd-8359-0134553a4aec', '復愁十二首 五', '复愁十二首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["金絲鏤箭鏃，皂尾製旗竿。","一自風塵起，猶嗟行路難。"]', '["金絲鏤箭鏃，皂尾製旗竿。","一自风塵起，猶嗟行路难。"]', '诗', 'shi', '', NULL, '復愁十二首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b281e104-63de-48ea-a879-fae61f49baf2', '復愁十二首 六', '复愁十二首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["胡虜何曾盛，干戈不肯休。","閭閻聽小子，談話覓封侯。"]', '["胡虜何曾盛，干戈不肯休。","閭閻听小子，談話覓封侯。"]', '诗', 'shi', '', NULL, '復愁十二首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c656a9b-c3d7-4818-bf6d-b9ba56028fa8', '復愁十二首 七', '复愁十二首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["貞觀銅牙弩，開元錦獸張。","花門小前好，此物棄沙場。"]', '["貞观銅牙弩，开元錦獸張。","花门小前好，此物棄沙場。"]', '诗', 'shi', '', NULL, '復愁十二首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc10c96-a26d-4899-8719-36b90da945ce', '復愁十二首 八', '复愁十二首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今日翔麟馬，先宜駕鼓車。","無勞問河北，諸將覺榮華。"]', '["今日翔麟马，先宜駕鼓车。","無勞问河北，諸將覺榮华。"]', '诗', 'shi', '', NULL, '復愁十二首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7daa779-d135-4486-aa2c-f9242bc55277', '復愁十二首 九', '复愁十二首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["任轉江淮粟，休添苑囿兵。","由來貔虎士，不滿鳳皇城。"]', '["任轉江淮粟，休添苑囿兵。","由来貔虎士，不满鳳皇城。"]', '诗', 'shi', '', NULL, '復愁十二首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd642541-4a30-4b42-9ded-0c6e4cc44e17', '復愁十二首 十', '复愁十二首 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江上亦秋色，火雲終不移。","巫山猶錦樹，南國且黃鸝。"]', '["江上亦秋色，火云終不移。","巫山猶錦樹，南国且黄鸝。"]', '诗', 'shi', '', NULL, '復愁十二首 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d953bb-1383-4a20-ab85-9313f0c82b7d', '復愁十二首 十一', '复愁十二首 十一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["每恨陶彭澤，無錢對菊花。","如今九日至，自覺酒須賒。"]', '["每恨陶彭澤，無錢对菊花。","如今九日至，自覺酒須賒。"]', '诗', 'shi', '', NULL, '復愁十二首 十一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b2608c-7a2c-40cf-9d74-c3d9a95e6ba9', '復愁十二首 十二', '复愁十二首 十二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["病減詩仍拙，吟多意有餘。","莫看江總老，猶被賞時魚。"]', '["病減诗仍拙，吟多意有餘。","莫看江總老，猶被賞时鱼。"]', '诗', 'shi', '', NULL, '復愁十二首 十二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('354d67cf-c1a3-4f2a-baba-0842ab66c099', '承聞河北諸道節度入朝歡喜口號絕句十二首 一', '承闻河北諸道節度入朝歡喜口號絕句十二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["祿山作逆降天誅，更有思明亦已無。","洶洶人寰猶不定，時時鬬戰欲何須。"]', '["祿山作逆降天誅，更有思明亦已無。","洶洶人寰猶不定，时时鬬戰欲何須。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a2e05d0-fefd-4db6-9e0c-8debd1a00056', '承聞河北諸道節度入朝歡喜口號絕句十二首 二', '承闻河北諸道節度入朝歡喜口號絕句十二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["社稷蒼生計必安，蠻夷雜種錯相干。","周宣漢武今王是，孝子忠臣後代看。"]', '["社稷蒼生計必安，蠻夷杂種錯相干。","周宣漢武今王是，孝子忠臣後代看。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b64c40-738b-4939-b39b-ba1edf4542d1', '承聞河北諸道節度入朝歡喜口號絕句十二首 三', '承闻河北諸道節度入朝歡喜口號絕句十二首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["喧喧道路多歌謠，河北將軍盡入朝。","始是乾坤王室正，却交江漢客魂銷。"]', '["喧喧道路多歌謠，河北將軍尽入朝。","始是乾坤王室正，却交江漢客魂銷。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4ea21d-8514-4a94-9303-c93b30773554', '承聞河北諸道節度入朝歡喜口號絕句十二首 四', '承闻河北諸道節度入朝歡喜口號絕句十二首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不道諸公無表來，茫然庶事遣人猜。","擁兵相學干戈銳，使者徒勞百萬迴。"]', '["不道諸公無表来，茫然庶事遣人猜。","擁兵相学干戈銳，使者徒勞百万迴。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc3fc21-0ada-4294-a6c2-f55679921fed', '承聞河北諸道節度入朝歡喜口號絕句十二首 五', '承闻河北諸道節度入朝歡喜口號絕句十二首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鳴玉鏘金盡正臣，修文偃武不無人。","興王會靜妖氛氣，聖壽宜過一萬春。"]', '["鳴玉鏘金尽正臣，修文偃武不無人。","兴王會静妖氛氣，聖壽宜過一万春。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6edfec2-2a10-48fe-a955-e9b7e0088017', '承聞河北諸道節度入朝歡喜口號絕句十二首 六', '承闻河北諸道節度入朝歡喜口號絕句十二首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["英雄見事若通神，聖哲爲心小一身。","燕趙休矜出佳麗，宮闈不擬選才人。"]', '["英雄见事若通神，聖哲爲心小一身。","燕趙休矜出佳丽，宮闈不擬選才人。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c26a722-4c4a-4ce6-bd36-e467290006c3', '承聞河北諸道節度入朝歡喜口號絕句十二首 七', '承闻河北諸道節度入朝歡喜口號絕句十二首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["抱病江天白首郎，空山樓閣暮春光。","衣冠是日朝天子，草奏何時入帝鄉。"]', '["抱病江天白首郎，空山楼閣暮春光。","衣冠是日朝天子，草奏何时入帝乡。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea054bd-aa0c-4d83-931b-7bd4cb9e4715', '承聞河北諸道節度入朝歡喜口號絕句十二首 八', '承闻河北諸道節度入朝歡喜口號絕句十二首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["澶漫山東一百州，削成如桉抱青丘。","苞茅重入歸關內，王祭還供盡海頭。"]', '["澶漫山东一百州，削成如桉抱青丘。","苞茅重入归关內，王祭還供尽海头。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761f8b22-e22e-4282-afe9-72db29e8f626', '承聞河北諸道節度入朝歡喜口號絕句十二首 九', '承闻河北諸道節度入朝歡喜口號絕句十二首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東逾遼水北滹沱，星象風雲喜共和。","紫氣關臨天地闊，黃金臺貯俊賢多。"]', '["东逾遼水北滹沱，星象风云喜共和。","紫氣关臨天地闊，黄金台貯俊賢多。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545f7e2c-bb6f-4c24-826d-e137da62626b', '承聞河北諸道節度入朝歡喜口號絕句十二首 十', '承闻河北諸道節度入朝歡喜口號絕句十二首 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漁陽突騎邯鄲兒，酒酣並轡金鞭垂。","意氣即歸雙闕舞，雄豪復遣五陵知。"]', '["漁陽突騎邯鄲兒，酒酣並轡金鞭垂。","意氣即归雙闕舞，雄豪复遣五陵知。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbf18e6-9759-411f-a1e9-dab17c501a16', '承聞河北諸道節度入朝歡喜口號絕句十二首 十一', '承闻河北諸道節度入朝歡喜口號絕句十二首 十一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["李相將軍擁薊門，白頭雖老赤心存。","竟能盡說諸侯入，知有從來天子尊。"]', '["李相將軍擁薊门，白头雖老赤心存。","竟能尽说諸侯入，知有從来天子尊。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 十一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c192f3-be92-462b-8691-98952318810e', '承聞河北諸道節度入朝歡喜口號絕句十二首 十二', '承闻河北諸道節度入朝歡喜口號絕句十二首 十二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["十二年來多戰場，天威已息陣堂堂。","神靈漢代中興主，功業汾陽異姓王。"]', '["十二年来多戰場，天威已息陣堂堂。","神靈漢代中兴主，功業汾陽異姓王。"]', '诗', 'shi', '', NULL, '承聞河北諸道節度入朝歡喜口號絕句十二首 十二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0a1a1a-b2fe-4221-823d-c49b6fe4cf45', '喜聞盜賊蕃寇總退口號五首 一', '喜闻盜賊蕃寇總退口號五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蕭關隴水入官軍，青海黃河卷塞雲。","北極轉愁龍虎氣，西戎休縱犬羊羣。"]', '["蕭关隴水入官軍，青海黄河卷塞云。","北極轉愁龙虎氣，西戎休縱犬羊羣。"]', '诗', 'shi', '', NULL, '喜聞盜賊蕃寇總退口號五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa08844b-7f32-4d6c-9754-a54ee4c31812', '喜聞盜賊蕃寇總退口號五首 二', '喜闻盜賊蕃寇總退口號五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["贊普多教使入秦，數通和好止煙塵。","朝廷忽用哥舒將，殺伐虛悲公主親。"]', '["贊普多教使入秦，數通和好止煙塵。","朝廷忽用哥舒將，殺伐虛悲公主親。"]', '诗', 'shi', '', NULL, '喜聞盜賊蕃寇總退口號五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf21098-d1cd-4576-8af7-7d19c49f1503', '喜聞盜賊蕃寇總退口號五首 三', '喜闻盜賊蕃寇總退口號五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["崆峒西極過崑崙，駝馬由來擁國門。","逆氣數年吹路斷，蕃人聞道漸星奔。"]', '["崆峒西極過崑崙，駝马由来擁国门。","逆氣數年吹路斷，蕃人闻道漸星奔。"]', '诗', 'shi', '', NULL, '喜聞盜賊蕃寇總退口號五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dacaacd-700f-495c-a03b-b20d4cba7bd7', '喜聞盜賊蕃寇總退口號五首 四', '喜闻盜賊蕃寇總退口號五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["勃律天西采玉河，堅昆碧盌最來多。","舊隨漢使千堆寶，少荅胡王萬匹羅。"]', '["勃律天西采玉河，堅昆碧盌最来多。","旧隨漢使千堆寶，少荅胡王万匹羅。"]', '诗', 'shi', '', NULL, '喜聞盜賊蕃寇總退口號五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50fd5a2b-0e04-410a-9030-1f1a3a75d0a3', '喜聞盜賊蕃寇總退口號五首 五', '喜闻盜賊蕃寇總退口號五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今春喜氣滿乾坤，南北東西拱至尊。","大曆二年調玉燭，玄元皇帝聖雲孫。"]', '["今春喜氣满乾坤，南北东西拱至尊。","大曆二年調玉燭，玄元皇帝聖云孫。"]', '诗', 'shi', '', NULL, '喜聞盜賊蕃寇總退口號五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b328c2-e211-4351-b921-2cfd04d05e99', '洞房', '洞房', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洞房環佩冷，玉殿起秋風。","秦地應新月，龍池滿舊宮。","繫舟今夜遠，清漏往時同。","萬里黃山北，園陵白露中。"]', '["洞房环佩冷，玉殿起秋风。","秦地應新月，龙池满旧宮。","繫舟今夜远，清漏往时同。","万里黄山北，园陵白露中。"]', '诗', 'shi', '', NULL, '洞房 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0366a5ab-545c-4240-96d7-556b4831e749', '宿昔', '宿昔', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宿昔青門裏，蓬萊仗數移。","花嬌迎雜樹，龍喜出平池。","落日留王母，微風倚少兒。","宮中行樂祕，少有外人知。"]', '["宿昔青门裏，蓬萊仗數移。","花嬌迎杂樹，龙喜出平池。","落日留王母，微风倚少兒。","宮中行乐祕，少有外人知。"]', '诗', 'shi', '', NULL, '宿昔 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3bb8b3e-8e4e-4501-83e1-e132d94286a5', '能畫', '能畫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["能畫毛延壽，投壺郭舍人。","每蒙天一笑，復似物皆春。","政化平如水，皇恩斷若神。","時時用抵戲，亦未雜風塵。"]', '["能畫毛延壽，投壺郭舍人。","每蒙天一笑，复似物皆春。","政化平如水，皇恩斷若神。","时时用抵戲，亦未杂风塵。"]', '诗', 'shi', '', NULL, '能畫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33085f30-6606-40c8-99b5-61c4c267e954', '鬬雞', '鬬雞', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鬬雞初賜錦，舞馬既登牀。","簾下宮人出，樓前御柳長。","仙遊終一閟，女樂久無香。","寂寞驪山道，清秋草木黃。"]', '["鬬雞初賜錦，舞马既登牀。","簾下宮人出，楼前御柳长。","仙游終一閟，女乐久無香。","寂寞驪山道，清秋草木黄。"]', '诗', 'shi', '', NULL, '鬬雞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4e5bbc-6394-4a18-8601-5a27899c7db6', '鸚鵡', '鸚鵡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鸚鵡含愁思，聰明憶別離。","翠衿渾短盡，紅觜漫多知。","未有開籠日，空殘舊宿枝。","世人憐復損，何用羽毛奇。"]', '["鸚鵡含愁思，聰明憶別離。","翠衿渾短尽，紅觜漫多知。","未有开籠日，空殘旧宿枝。","世人怜复損，何用羽毛奇。"]', '诗', 'shi', '', NULL, '鸚鵡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02310cb7-18e8-4d0d-909c-1ef240340ba3', '歷歷', '歷歷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歷歷開元事，分明在眼前。","無端盜賊起，忽已歲時遷。","巫峽西江外，秦城北斗邊。","爲郎從白首，臥病數秋天。"]', '["歷歷开元事，分明在眼前。","無端盜賊起，忽已歲时遷。","巫峽西江外，秦城北斗邊。","爲郎從白首，臥病數秋天。"]', '诗', 'shi', '', NULL, '歷歷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08057e56-deff-48fe-b60a-f58945fd4476', '洛陽', '洛陽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洛陽昔陷沒，胡馬犯潼關。","天子初愁思，都人慘別顏。","清笳去宮闕，翠蓋出關山。","故老仍流涕，龍髯幸再攀。"]', '["洛陽昔陷沒，胡马犯潼关。","天子初愁思，都人慘別顏。","清笳去宮闕，翠蓋出关山。","故老仍流涕，龙髯幸再攀。"]', '诗', 'shi', '', NULL, '洛陽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b36a292d-baa6-47fb-a1c2-1fea2127a5a2', '驪山', '驪山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驪山絕望幸，花萼罷登臨。","地下無朝燭，人間有賜金。","鼎湖龍去遠，銀海雁飛深。","萬歲蓬萊日，長懸舊羽林。"]', '["驪山絕望幸，花萼罷登臨。","地下無朝燭，人间有賜金。","鼎湖龙去远，銀海雁飞深。","万歲蓬萊日，长懸旧羽林。"]', '诗', 'shi', '', NULL, '驪山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef50a5e-24ba-44a0-a1f6-504aba9bac8e', '提封', '提封', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["提封漢天下，萬國尚同心。","借問懸車守，何如儉德臨。","時徵俊乂入，草竊犬羊侵。","願戒兵猶火，恩加四海深。"]', '["提封漢天下，万国尚同心。","借问懸车守，何如儉德臨。","时徵俊乂入，草竊犬羊侵。","願戒兵猶火，恩加四海深。"]', '诗', 'shi', '', NULL, '提封 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751820b9-7a08-41c7-8f9b-356cea9bbf6d', '覆舟二首 一', '覆舟二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫峽盤渦曉，黔陽貢物秋。","丹砂同隕石，翠羽共沈舟。","羈使空斜影，龍居閟積流。","篙工幸不溺，俄頃逐輕鷗。"]', '["巫峽盤渦晓，黔陽貢物秋。","丹砂同隕石，翠羽共沈舟。","羈使空斜影，龙居閟積流。","篙工幸不溺，俄頃逐轻鷗。"]', '诗', 'shi', '', NULL, '覆舟二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9108f782-355e-404d-9cf9-5a1c4a224d10', '覆舟二首 二', '覆舟二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竹宮時望拜，桂館或求仙。","姹女臨波日，神光照夜年。","徒聞斬蛟劒，無復爨犀船。","使者隨秋色，迢迢獨上天。"]', '["竹宮时望拜，桂館或求仙。","姹女臨波日，神光照夜年。","徒闻斬蛟劒，無复爨犀船。","使者隨秋色，迢迢独上天。"]', '诗', 'shi', '', NULL, '覆舟二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706b060f-bc6b-4d27-956f-c0f19481f770', '垂白', '垂白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["垂白馮唐老，清秋宋玉悲。","江喧長少睡，樓迥獨移時。","多難身何補，無家病不辭。","甘從千日醉，未許七哀詩。"]', '["垂白馮唐老，清秋宋玉悲。","江喧长少睡，楼迥独移时。","多难身何補，無家病不辞。","甘從千日醉，未許七哀诗。"]', '诗', 'shi', '', NULL, '垂白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef7a6cc-5c38-42fc-97ef-1cb713b162e3', '草閣', '草閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草閣臨無地，柴扉永不關。","魚龍迴夜水，星月動秋山。","久露清初濕，高雲薄未還。","汎舟慚小婦，飄泊損紅顏。"]', '["草閣臨無地，柴扉永不关。","鱼龙迴夜水，星月动秋山。","久露清初濕，高云薄未還。","汎舟慚小婦，飄泊損紅顏。"]', '诗', 'shi', '', NULL, '草閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5efef64-4159-4f6b-87b8-dade0c0e1d4c', '江月', '江月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江月光於水，高樓思殺人。","天邊長作客，老去一霑巾。","玉露團清影，銀河沒半輪。","誰家挑錦字，滅燭翠眉嚬。"]', '["江月光於水，高楼思殺人。","天邊长作客，老去一霑巾。","玉露團清影，銀河沒半輪。","誰家挑錦字，滅燭翠眉嚬。"]', '诗', 'shi', '', NULL, '江月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd37d952-4886-47b2-a34e-04a357320163', '江上', '江上', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江上日多雨，蕭蕭荆楚秋。","高風下木葉，永夜攬貂裘。","勳業頻看鏡，行藏獨倚樓。","時危思報主，衰謝不能休。"]', '["江上日多雨，蕭蕭荆楚秋。","高风下木葉，永夜攬貂裘。","勳業頻看镜，行藏独倚楼。","时危思報主，衰謝不能休。"]', '诗', 'shi', '', NULL, '江上 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608a59d1-b256-4b9a-ad3c-068df67a9caa', '中夜', '中夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中夜江山靜，危樓望北辰。","長爲萬里客，有媿百年身。","故國風雲氣，高堂戰伐塵。","胡雛負恩澤，嗟爾太平人。"]', '["中夜江山静，危楼望北辰。","长爲万里客，有媿百年身。","故国风云氣，高堂戰伐塵。","胡雛負恩澤，嗟爾太平人。"]', '诗', 'shi', '', NULL, '中夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d699470-bc8e-49d9-85e5-b1987b01c2dd', '江漢', '江漢', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江漢思歸客，乾坤一腐儒。","片雲天共遠，永夜月同孤。","落日心猶壯，秋風病欲疎。","古來存老馬，不必取長途。"]', '["江漢思归客，乾坤一腐儒。","片云天共远，永夜月同孤。","落日心猶壯，秋风病欲疎。","古来存老马，不必取长途。"]', '诗', 'shi', '', NULL, '江漢 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e998ebcb-484e-4633-b2c0-1af1d716695a', '白露', '白露', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白露團甘子，清晨散馬蹄。","圃開連石樹，船渡入江溪。","憑几看魚樂，迴鞭急鳥棲。","漸知秋實美，幽徑恐多蹊。"]', '["白露團甘子，清晨散马蹄。","圃开連石樹，船渡入江溪。","憑几看鱼乐，迴鞭急鸟棲。","漸知秋實美，幽徑恐多蹊。"]', '诗', 'shi', '', NULL, '白露 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8937e3-49b1-4ee9-93fe-4ea590143f89', '孟氏', '孟氏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孟氏好兄弟，養親唯小園。","承顏胝手足，坐客強盤[飧]。","負米力葵外，讀書秋樹根。","卜鄰慚近舍，訓子學誰門。"]', '["孟氏好兄弟，養親唯小园。","承顏胝手足，坐客強盤[飧]。","負米力葵外，读书秋樹根。","卜鄰慚近舍，訓子学誰门。"]', '诗', 'shi', '', NULL, '孟氏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7fe6b3-f2ec-49ca-9184-fefb6ac4791c', '吾宗', '吾宗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾宗老孫子，質樸古人風。","耕鑿安時論，衣冠與世同。","在家常早起，憂國願年豐。","語及君臣際，經書滿腹中。"]', '["吾宗老孫子，質樸古人风。","耕鑿安时論，衣冠與世同。","在家常早起，憂国願年豐。","語及君臣際，經书满腹中。"]', '诗', 'shi', '', NULL, '吾宗 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c325d79-2ab7-4b59-87f7-f02a76cf11f2', '有歎', '有歎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["壯心久零落，白首寄人間。","天下兵常鬬，江東客未還。","窮猨號雨雪，老馬怯關山。","武德開元際，蒼生豈重攀。"]', '["壯心久零落，白首寄人间。","天下兵常鬬，江东客未還。","窮猨號雨雪，老马怯关山。","武德开元際，蒼生豈重攀。"]', '诗', 'shi', '', NULL, '有歎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc0dd82-ef4d-4878-b78a-b57a0563df8c', '冬深', '冬深', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["花葉隨天意，江溪共石根。","早霞隨類影，寒水各依痕。","易下楊朱淚，難招楚客魂。","風濤暮不穩，舍棹宿誰門。"]', '["花葉隨天意，江溪共石根。","早霞隨類影，寒水各依痕。","易下楊朱泪，难招楚客魂。","风濤暮不穩，舍棹宿誰门。"]', '诗', 'shi', '', NULL, '冬深 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0fc134-55af-4890-bfee-97059e2711a8', '不寐', '不寐', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["瞿塘夜水黑，城內改更籌。","翳翳月沈霧，輝輝星近樓。","氣衰甘少寐，心弱恨和愁。","多壘滿山谷，桃源無處求。"]', '["瞿塘夜水黑，城內改更籌。","翳翳月沈霧，輝輝星近楼。","氣衰甘少寐，心弱恨和愁。","多壘满山谷，桃源無处求。"]', '诗', 'shi', '', NULL, '不寐 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b65f11-2127-42e5-a7a6-2def0df40161', '月圓', '月圓', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孤月當樓滿，寒江動夜扉。","委波金不定，照席綺逾依。","未缺空山靜，高懸列宿稀。","故園松桂發，萬里共清輝。"]', '["孤月當楼满，寒江动夜扉。","委波金不定，照席綺逾依。","未缺空山静，高懸列宿稀。","故园松桂發，万里共清輝。"]', '诗', 'shi', '', NULL, '月圓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59dca3f6-e269-4bf8-8bed-0898f4439b34', '中宵', '中宵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西閣百尋餘，中宵步綺疏。","飛星過水白，落月動沙虛。","擇木知幽鳥，潛波想巨魚。","親朋滿天地，兵甲少來書。"]', '["西閣百尋餘，中宵步綺疏。","飞星過水白，落月动沙虛。","擇木知幽鸟，潛波想巨鱼。","親朋满天地，兵甲少来书。"]', '诗', 'shi', '', NULL, '中宵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262a0118-2fc0-4a10-8d1f-6ada29acc66f', '遣愁', '遣愁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["養拙蓬爲戶，茫茫何所開。","江通神女館，地隔望鄉臺。","漸惜容顏老，無由弟妹來。","兵戈與人事，回首一悲哀。"]', '["養拙蓬爲戶，茫茫何所开。","江通神女館，地隔望乡台。","漸惜容顏老，無由弟妹来。","兵戈與人事，回首一悲哀。"]', '诗', 'shi', '', NULL, '遣愁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ca52f4-7ef9-4ec2-97b8-37b6818b4854', '秋清', '秋清', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高秋蘇病氣，白髮自能梳。","藥餌憎加減，門庭悶掃除。","杖藜還客拜，愛竹遣兒書。","十月江平穩，輕舟進所如。"]', '["高秋蘇病氣，白髮自能梳。","藥餌憎加減，门庭悶掃除。","杖藜還客拜，愛竹遣兒书。","十月江平穩，轻舟進所如。"]', '诗', 'shi', '', NULL, '秋清 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb2f973-0b17-49be-83d9-7f9d843b04d3', '傷秋', '傷秋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["林僻來人少，山長去鳥微。","高秋收畫扇，久客掩荆扉。","嬾慢頭時櫛，艱難帶減圍。","將軍猶汗馬，天子尚戎衣。","白蔣風飆脆，殷檉曉夜稀。","何年減豺虎，似有故園歸。"]', '["林僻来人少，山长去鸟微。","高秋收畫扇，久客掩荆扉。","嬾慢头时櫛，艱难带減圍。","將軍猶汗马，天子尚戎衣。","白蔣风飆脆，殷檉晓夜稀。","何年減豺虎，似有故园归。"]', '诗', 'shi', '', NULL, '傷秋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85451ae3-79af-4fe6-9cc9-09ebcfbea88a', '秋峽', '秋峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江濤萬古峽，肺氣久衰翁。","不寐防巴虎，全生狎楚童。","衣裳垂素髮，門巷落丹楓。","常怪商山老，兼存翊贊功。"]', '["江濤万古峽，肺氣久衰翁。","不寐防巴虎，全生狎楚童。","衣裳垂素髮，门巷落丹楓。","常怪商山老，兼存翊贊功。"]', '诗', 'shi', '', NULL, '秋峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db38a424-b607-4c6e-b95e-8d63c5535249', '南極', '南極', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南極青山衆，西江白谷分。","古城疏落木，荒戍密寒雲。","歲月虵常見，風飆虎或聞。","近身皆鳥道，殊俗自人羣。","睥睨登哀柝，矛弧照夕曛。","亂離多醉尉，愁殺李將軍。"]', '["南極青山衆，西江白谷分。","古城疏落木，荒戍密寒云。","歲月虵常见，风飆虎或闻。","近身皆鸟道，殊俗自人羣。","睥睨登哀柝，矛弧照夕曛。","亂離多醉尉，愁殺李將軍。"]', '诗', 'shi', '', NULL, '南極 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfab541a-0fbf-44c9-87c2-ce2805282869', '搖落', '搖落', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["搖落巫山暮，寒江東北流。","煙塵多戰鼓，風浪少行舟。","鵝費義之墨，貂餘季子裘。","長懷報明主，臥病復高秋。"]', '["搖落巫山暮，寒江东北流。","煙塵多戰鼓，风浪少行舟。","鵝費義之墨，貂餘季子裘。","长懷報明主，臥病复高秋。"]', '诗', 'shi', '', NULL, '搖落 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533e2212-7d88-4b6d-9f5f-a8d42f4d3627', '耳聾', '耳聾', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["生年鶡冠子，歎世鹿皮翁。","眼復幾時暗，耳從前月聾。","猨鳴秋淚缺，雀噪晚愁空。","黃落驚山樹，呼兒問朔風。"]', '["生年鶡冠子，歎世鹿皮翁。","眼复幾时暗，耳從前月聾。","猨鳴秋泪缺，雀噪晚愁空。","黄落驚山樹，呼兒问朔风。"]', '诗', 'shi', '', NULL, '耳聾 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0081cd-53fe-44ba-89cc-e449a3d4cd58', '獨坐二首 一', '独坐二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竟日雨冥冥，雙崖洗更青。","水花寒落岸，山鳥暮過庭。","煖老須燕玉，充飢憶楚萍。","胡笳在樓上，哀怨不堪聽。"]', '["竟日雨冥冥，雙崖洗更青。","水花寒落岸，山鸟暮過庭。","煖老須燕玉，充飢憶楚萍。","胡笳在楼上，哀怨不堪听。"]', '诗', 'shi', '', NULL, '獨坐二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd1e3f3-1e4f-4777-bf97-af23b1d1eb52', '獨坐二首 二', '独坐二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白狗斜臨北，黃牛更在東。","峽雲常照夜，江月會兼風。","曬藥安垂老，應門試小童。","亦知行不逮，苦恨耳多聾。"]', '["白狗斜臨北，黄牛更在东。","峽云常照夜，江月會兼风。","曬藥安垂老，應门試小童。","亦知行不逮，苦恨耳多聾。"]', '诗', 'shi', '', NULL, '獨坐二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9fe2f3f-ff6e-49b6-b0f8-e715036bb664', '遠遊', '远游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江闊浮高棟，雲長出斷山。","塵沙連越巂，風雨暗荆蠻。","雁矯銜蘆內，猨啼失木間。","弊裘蘇季子，歷國未知還。"]', '["江闊浮高棟，云长出斷山。","塵沙連越巂，风雨暗荆蠻。","雁矯銜蘆內，猨啼失木间。","弊裘蘇季子，歷国未知還。"]', '诗', 'shi', '', NULL, '遠遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8b99af-73d5-4546-9ff4-8b0380c75105', '夜', '夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["露下天高秋水清，空山獨夜旅魂驚。","疎燈自照孤帆宿，新月猶懸雙杵鳴。","南菊再逢人臥病，北書不至雁無情。","步蟾倚杖看牛斗，銀漢遙應接鳳城。"]', '["露下天高秋水清，空山独夜旅魂驚。","疎灯自照孤帆宿，新月猶懸雙杵鳴。","南菊再逢人臥病，北书不至雁無情。","步蟾倚杖看牛斗，銀漢遙應接鳳城。"]', '诗', 'shi', '', NULL, '夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3d0766-ae3c-4bc2-9ee4-eda61ed67a39', '暮春', '暮春', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["臥病擁塞在峽中，瀟湘洞庭虛暎空。","楚天不斷四時雨，巫峽常吹千里風。","沙上草閣柳新闇，城邊野池蓮欲紅。","暮春鴛鷺立洲渚，挾子翻飛還一叢。"]', '["臥病擁塞在峽中，瀟湘洞庭虛暎空。","楚天不斷四时雨，巫峽常吹千里风。","沙上草閣柳新闇，城邊野池蓮欲紅。","暮春鴛鷺立洲渚，挾子翻飞還一叢。"]', '诗', 'shi', '', NULL, '暮春 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1085d5c0-7e80-4469-a4e9-3b462ce3ffed', '晴二首 一', '晴二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久雨巫山暗，新晴錦繡文。","碧知湖外草，紅見海東雲。","竟日鶯相和，摩霄鶴數羣。","野花乾更落，風處急紛紛。"]', '["久雨巫山暗，新晴錦繡文。","碧知湖外草，紅见海东云。","竟日鶯相和，摩霄鹤數羣。","野花乾更落，风处急紛紛。"]', '诗', 'shi', '', NULL, '晴二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9135c693-7ee5-4872-b911-523cb07e9953', '晴二首 二', '晴二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["啼烏爭引子，鳴鶴不歸林。","下食遭泥去，高飛恨久陰。","雨聲衝塞盡，日氣射江深。","迴首周南客，驅馳魏闕心。"]', '["啼烏爭引子，鳴鹤不归林。","下食遭泥去，高飞恨久陰。","雨声衝塞尽，日氣射江深。","迴首周南客，驱驰魏闕心。"]', '诗', 'shi', '', NULL, '晴二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5b10a8-04af-4ffb-bf0e-53e2b12b3275', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["始賀天休雨，還嗟地出雷。","驟看浮峽過，密作渡江來。","牛馬行無色，蛟龍鬬不開。","干戈盛陰氣，未必自陽臺。"]', '["始賀天休雨，還嗟地出雷。","驟看浮峽過，密作渡江来。","牛马行無色，蛟龙鬬不开。","干戈盛陰氣，未必自陽台。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c23bd8-f03b-419f-aabe-bb56e2d8d5a6', '月三首 一', '月三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["斷續巫山雨，天河此夜新。","若無青嶂月，愁殺白頭人。","魍魎移深樹，蝦蟆動半輪。","故園當北斗，直指照西秦。"]', '["斷續巫山雨，天河此夜新。","若無青嶂月，愁殺白头人。","魍魎移深樹，蝦蟆动半輪。","故园當北斗，直指照西秦。"]', '诗', 'shi', '', NULL, '月三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690ec16d-1c00-4f82-afe0-98e4dd46ead0', '月三首 二', '月三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["併照巫山出，新窺楚水清。","羈棲愁裏見，二十四迴明。","必驗升沈體，如知進退情。","不違銀漢落，亦伴玉繩橫。"]', '["併照巫山出，新窺楚水清。","羈棲愁裏见，二十四迴明。","必驗升沈體，如知進退情。","不違銀漢落，亦伴玉繩橫。"]', '诗', 'shi', '', NULL, '月三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb36fab-99c2-40f7-9f51-bba8dd59741e', '月三首 三', '月三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里瞿塘峽，春來六上弦。","時時開暗室，故故滿青天。","爽合風襟靜，高當淚臉懸。","南飛有烏鵲，夜久落江邊。"]', '["万里瞿塘峽，春来六上弦。","时时开暗室，故故满青天。","爽合风襟静，高當泪臉懸。","南飞有烏鵲，夜久落江邊。"]', '诗', 'shi', '', NULL, '月三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10e1135b-1b0b-4b2d-8b21-a42b1291862c', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬木雲深隱，連山雨未開。","風扉掩不定，水鳥過仍迴。","鮫館如鳴杼，樵舟豈伐枚。","清涼破炎毒，衰意欲登臺。"]', '["万木云深隐，連山雨未开。","风扉掩不定，水鸟過仍迴。","鮫館如鳴杼，樵舟豈伐枚。","清涼破炎毒，衰意欲登台。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34086aad-f0b7-4bdf-8265-db2a77e6b991', '晚晴', '晚晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["返照斜初徹，浮雲薄未歸。","江虹明遠飲，峽雨落餘飛。","鳧雁終高去，熊羆覺自肥。","秋分客尚在，竹露夕微微。"]', '["返照斜初徹，浮云薄未归。","江虹明远饮，峽雨落餘飞。","鳧雁終高去，熊羆覺自肥。","秋分客尚在，竹露夕微微。"]', '诗', 'shi', '', NULL, '晚晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4933f2f1-a324-454a-a99a-17b8c57f1e35', '夜雨', '夜雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["小雨夜復密，迴風吹早秋。","野涼侵閉戶，江滿帶維舟。","通籍恨多病，爲郎忝薄遊。","天寒出巫峽，醉別仲宣樓。"]', '["小雨夜复密，迴风吹早秋。","野涼侵閉戶，江满带維舟。","通籍恨多病，爲郎忝薄游。","天寒出巫峽，醉別仲宣楼。"]', '诗', 'shi', '', NULL, '夜雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('413966c1-7c3f-44b8-b036-07e38c724d9f', '更題', '更題', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["只應踏初雪，騎馬發荆州。","直怕巫山雨，真傷白帝秋。","羣公蒼玉珮，天子翠雲裘。","同舍晨趨侍，胡爲淹此留。"]', '["只應踏初雪，騎马發荆州。","直怕巫山雨，真傷白帝秋。","羣公蒼玉珮，天子翠云裘。","同舍晨趨侍，胡爲淹此留。"]', '诗', 'shi', '', NULL, '更題 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15bf3c35-1b72-45e2-bf5b-8e3c7c682d7f', '歸', '归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["束帶還騎馬，東西却渡船。","林中才有地，峽外絕無天。","虛白高人靜，喧卑俗累牽。","他鄉悅遲暮，不敢廢詩篇。"]', '["束带還騎马，东西却渡船。","林中才有地，峽外絕無天。","虛白高人静，喧卑俗累牽。","他乡悅遲暮，不敢廢诗篇。"]', '诗', 'shi', '', NULL, '歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b864f4-8bc3-4611-a3c9-b062e67f196f', '返照', '返照', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚王宮北正黃昏，白帝城西過雨痕。","返照入江翻石壁，歸雲擁樹失山村。","衰年肺病唯高枕，絕塞愁時早閉門。","不可久留豺虎亂，南方實有未招魂。"]', '["楚王宮北正黄昏，白帝城西過雨痕。","返照入江翻石壁，归云擁樹失山村。","衰年肺病唯高枕，絕塞愁时早閉门。","不可久留豺虎亂，南方實有未招魂。"]', '诗', 'shi', '', NULL, '返照 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0336e989-ea54-4fdc-80b6-ffd5c6595a35', '熱三首 一', '熱三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雷霆空霹靂，雲雨竟虛無。","炎赫衣流汗，低垂氣不蘇。","乞爲寒水玉，願作冷秋菰。","何似兒童歲，風涼出舞雩。"]', '["雷霆空霹靂，云雨竟虛無。","炎赫衣流汗，低垂氣不蘇。","乞爲寒水玉，願作冷秋菰。","何似兒童歲，风涼出舞雩。"]', '诗', 'shi', '', NULL, '熱三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0efe7cc-4876-45cd-a1cc-8c8dc6b2753d', '熱三首 二', '熱三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["瘴雲終不滅，瀘水復西來。","閉戶人高臥，歸林鳥却迴。","峽中都似火，江上只空雷。","想見陰宮雪，風門颯踏開。"]', '["瘴云終不滅，瀘水复西来。","閉戶人高臥，归林鸟却迴。","峽中都似火，江上只空雷。","想见陰宮雪，风门颯踏开。"]', '诗', 'shi', '', NULL, '熱三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d24b59-60da-48d1-b004-e5c775f60cf4', '熱三首 三', '熱三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朱李沈不冷，彫胡炊屢新。","將衰骨盡痛，被褐味空頻。","歘翕炎蒸景，飄颻征戍人。","十年可解甲，爲爾一霑巾。"]', '["朱李沈不冷，彫胡炊屢新。","將衰骨尽痛，被褐味空頻。","歘翕炎蒸景，飄颻征戍人。","十年可解甲，爲爾一霑巾。"]', '诗', 'shi', '', NULL, '熱三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4eb47c-2993-49d6-b920-c33ce0533a76', '日暮', '日暮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["牛羊下來久，各已閉柴門。","風月自清夜，江山非故園。","石泉流暗壁，草露滴秋根。","頭白燈明裏，何須花燼繁。"]', '["牛羊下来久，各已閉柴门。","风月自清夜，江山非故园。","石泉流暗壁，草露滴秋根。","头白灯明裏，何須花燼繁。"]', '诗', 'shi', '', NULL, '日暮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68896e5-b85b-4a0b-abf4-4b732cd230e4', '八月十五夜月二首 一', '八月十五夜月二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["滿目飛明鏡，歸心折大刀。","轉蓬行地遠，攀桂仰天高。","水路疑霜雪，林棲見羽毛。","此時瞻白兔，直欲數秋毫。"]', '["满目飞明镜，归心折大刀。","轉蓬行地远，攀桂仰天高。","水路疑霜雪，林棲见羽毛。","此时瞻白兔，直欲數秋毫。"]', '诗', 'shi', '', NULL, '八月十五夜月二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5e2a47-232b-4a3c-bc62-67e808b758fe', '八月十五夜月二首 二', '八月十五夜月二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["稍下巫山峽，猶銜白帝城。","氣沈全浦暗，輪仄半樓明。","刁斗皆催曉，蟾蜍且自傾。","張弓倚殘魄，不獨漢家營。"]', '["稍下巫山峽，猶銜白帝城。","氣沈全浦暗，輪仄半楼明。","刁斗皆催晓，蟾蜍且自傾。","張弓倚殘魄，不独漢家營。"]', '诗', 'shi', '', NULL, '八月十五夜月二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bca90d8-d192-4088-b5a6-d32afe1f3eed', '十六夜翫月', '十六夜翫月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舊挹金波爽，皆傳玉露秋。","關山隨地闊，河漢近人流。","谷口樵歸唱，孤城笛起愁。","巴童渾不寢，半夜有行舟。"]', '["旧挹金波爽，皆傳玉露秋。","关山隨地闊，河漢近人流。","谷口樵归唱，孤城笛起愁。","巴童渾不寢，半夜有行舟。"]', '诗', 'shi', '', NULL, '十六夜翫月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874082d6-f3bb-4cb7-aced-c69d916cf87a', '十七夜對月', '十七夜对月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋月仍圓夜，江村獨老身。","捲簾還照客，倚杖更隨人。","光射潛虬動，明翻宿鳥頻。","茅齋依橘柚，清切露華新。"]', '["秋月仍圓夜，江村独老身。","捲簾還照客，倚杖更隨人。","光射潛虬动，明翻宿鸟頻。","茅斋依橘柚，清切露华新。"]', '诗', 'shi', '', NULL, '十七夜對月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013587ae-016b-4a6c-be0c-806ac0bc7a12', '村雨', '村雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨聲傳兩夜，寒事颯高秋。","挈帶看朱紱，開箱覩黑裘。","世情只益睡，盜賊敢忘憂。","松菊新霑洗，茅齊慰遠遊。"]', '["雨声傳兩夜，寒事颯高秋。","挈带看朱紱，开箱覩黑裘。","世情只益睡，盜賊敢忘憂。","松菊新霑洗，茅齊慰远游。"]', '诗', 'shi', '', NULL, '村雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d98c50d-4a8b-4238-af88-3f81b0500982', '雨晴', '雨晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨時山不改，晴罷峽如新。","天路看殊俗，秋江思殺人。","有猨揮淚盡，無犬附書頻。","故國愁眉外，長歌欲損神。"]', '["雨时山不改，晴罷峽如新。","天路看殊俗，秋江思殺人。","有猨揮泪尽，無犬附书頻。","故国愁眉外，长歌欲損神。"]', '诗', 'shi', '', NULL, '雨晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a352e426-485f-4d00-8ae5-98191e2c5a87', '晚晴吳郎見過北舍', '晚晴吳郎见過北舍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["圃畦新雨潤，媿子廢鉏來。","竹杖交頭拄，柴扉隔徑開。","欲棲羣鳥亂，未去小童催。","明日重陽酒，相迎自醱醅。"]', '["圃畦新雨潤，媿子廢鉏来。","竹杖交头拄，柴扉隔徑开。","欲棲羣鸟亂，未去小童催。","明日重陽酒，相迎自醱醅。"]', '诗', 'shi', '', NULL, '晚晴吳郎見過北舍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e5492a-ef96-4327-8f2d-20c50121a30f', '暝', '暝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日下四山陰，山庭嵐氣侵。","牛羊歸徑險，鳥雀聚枝深。","正枕當星劒，收書動玉琴。","半扉開燭影，欲掩見清砧。"]', '["日下四山陰，山庭嵐氣侵。","牛羊归徑險，鸟雀聚枝深。","正枕當星劒，收书动玉琴。","半扉开燭影，欲掩见清砧。"]', '诗', 'shi', '', NULL, '暝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a70ecbe-cc85-4aba-9a58-227f06152fbe', '雲', '云', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["龍似瞿唐會，江依白帝深。","終年常起峽，每夜必通林。","收穫辭霜渚，分明在夕岑。","高齋非一處，秀氣豁煩襟。"]', '["龙似瞿唐會，江依白帝深。","終年常起峽，每夜必通林。","收穫辞霜渚，分明在夕岑。","高斋非一处，秀氣豁煩襟。"]', '诗', 'shi', '', NULL, '雲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9c72c3-ad63-4979-8226-fceaa3fb581e', '月', '月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四更山吐月，殘夜水明樓。","塵匣元開鏡，風簾自上鉤。","兔應疑鶴髮，蟾亦戀貂裘。","斟酌姮娥寡，天寒耐九秋。"]', '["四更山吐月，殘夜水明楼。","塵匣元开镜，风簾自上鉤。","兔應疑鹤髮，蟾亦戀貂裘。","斟酌姮娥寡，天寒耐九秋。"]', '诗', 'shi', '', NULL, '月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1da5a7-27cc-4c6a-9ba9-aebded7e7a94', '雨四首 一', '雨四首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["微雨不滑道，斷雲疎復行。","紫崖奔處黑，白鳥去邊明。","秋日新霑影，寒江舊落聲。","柴扉臨野碓，半得搗香秔。"]', '["微雨不滑道，斷云疎复行。","紫崖奔处黑，白鸟去邊明。","秋日新霑影，寒江旧落声。","柴扉臨野碓，半得捣香秔。"]', '诗', 'shi', '', NULL, '雨四首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85cc5878-f657-4443-b3c2-08c9502a0417', '雨四首 二', '雨四首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江雨舊無時，天晴忽散絲。","暮秋霑物冷，今日過雲遲。","上馬迥休出，看鷗坐不辭。","高軒當灧澦，潤色靜書帷。"]', '["江雨旧無时，天晴忽散絲。","暮秋霑物冷，今日過云遲。","上马迥休出，看鷗坐不辞。","高軒當灧澦，潤色静书帷。"]', '诗', 'shi', '', NULL, '雨四首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c92bbd7-1c25-4ea2-8854-8db8e6de5284', '雨四首 三', '雨四首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["物色歲將晏，天隅人未歸。","朔風鳴淅淅，寒雨下霏霏。","多病久加飯，衰容新授衣。","時危覺凋喪，故舊短書稀。"]', '["物色歲將晏，天隅人未归。","朔风鳴淅淅，寒雨下霏霏。","多病久加飯，衰容新授衣。","时危覺凋喪，故旧短书稀。"]', '诗', 'shi', '', NULL, '雨四首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eada6f5e-c3ee-452b-898d-7bac588c7607', '雨四首 四', '雨四首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚雨石苔滋，京華消息遲。","山寒青兕呌，江晚白鷗飢。","神女花鈿落，鮫人織杼悲。","繁憂不自整，終日灑如絲。"]', '["楚雨石苔滋，京华消息遲。","山寒青兕呌，江晚白鷗飢。","神女花鈿落，鮫人织杼悲。","繁憂不自整，終日灑如絲。"]', '诗', 'shi', '', NULL, '雨四首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58d6a53-dec7-4aa2-a3a3-597d8a285a0c', '夜', '夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["絕岸風威動，寒房燭影微。","嶺猨霜外宿，江鳥夜深飛。","獨坐親雄劒，哀歌嘆短衣。","煙塵繞閶闔，白首壯心違。"]', '["絕岸风威动，寒房燭影微。","嶺猨霜外宿，江鸟夜深飞。","独坐親雄劒，哀歌嘆短衣。","煙塵繞閶闔，白首壯心違。"]', '诗', 'shi', '', NULL, '夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1b2f93-4583-49ea-88fd-4c73870865bb', '晨雨', '晨雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["小雨晨光內，初來葉上聞。","霧交纔灑地，風逆旋隨雲。","暫起柴荆色，輕霑鳥獸羣。","麝香山一半，亭午未全分。"]', '["小雨晨光內，初来葉上闻。","霧交纔灑地，风逆旋隨云。","暫起柴荆色，轻霑鸟獸羣。","麝香山一半，亭午未全分。"]', '诗', 'shi', '', NULL, '晨雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4abc2b1d-a598-4326-ad60-01e0f5e03b50', '返照', '返照', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["返照開巫峽，寒空半有無。","已低魚復暗，不盡白鹽孤。","荻岸如秋水，松門似畫圖。","牛羊識童僕，既夕應傳呼。"]', '["返照开巫峽，寒空半有無。","已低鱼复暗，不尽白鹽孤。","荻岸如秋水，松门似畫圖。","牛羊識童僕，既夕應傳呼。"]', '诗', 'shi', '', NULL, '返照 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5adb2b-8b62-4798-864c-a68fb6a42e1d', '向夕', '向夕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["畎畝孤城外，江村亂水中。","深山催短景，喬木易高風。","鶴下雲汀近，雞棲草屋同。","琴書散明燭，長夜始堪終。"]', '["畎畝孤城外，江村亂水中。","深山催短景，喬木易高风。","鹤下云汀近，雞棲草屋同。","琴书散明燭，长夜始堪終。"]', '诗', 'shi', '', NULL, '向夕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dcf8e32-9912-4634-bcf6-82dec4e0f31c', '曉望', '晓望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白帝更聲盡，陽臺曙色分。","高峯寒上日，疊嶺宿霾雲。","地坼江帆隱，天清木葉聞。","荆扉對麋鹿，應共爾爲羣。"]', '["白帝更声尽，陽台曙色分。","高峯寒上日，叠嶺宿霾云。","地坼江帆隐，天清木葉闻。","荆扉对麋鹿，應共爾爲羣。"]', '诗', 'shi', '', NULL, '曉望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324ddb41-56fb-48a4-9ae5-2a4cc08bfc74', '雷', '雷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫峽中宵動，滄江十月雷。","龍虵不成蟄，天地劃爭迴。","却碾空山過，深蟠絕壁來。","何須妒雲雨，霹靂楚王臺。"]', '["巫峽中宵动，滄江十月雷。","龙虵不成蟄，天地劃爭迴。","却碾空山過，深蟠絕壁来。","何須妒云雨，霹靂楚王台。"]', '诗', 'shi', '', NULL, '雷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f75444-32aa-439d-814d-317d7b3ce92c', '雨', '雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["冥冥甲子雨，已度立春時。","輕箑煩相向，纖絺恐自疑。","煙添纔有色，風引更如絲。","直覺巫山暮，兼催宋玉悲。"]', '["冥冥甲子雨，已度立春时。","轻箑煩相向，纖絺恐自疑。","煙添纔有色，风引更如絲。","直覺巫山暮，兼催宋玉悲。"]', '诗', 'shi', '', NULL, '雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe91db4-435e-411f-9466-27832046fefa', '朝二首 一', '朝二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清旭楚宮南，霜空萬嶺含。","野人時獨往，雲木曉相參。","俊鶻無聲過，飢烏下食貪。","病身終不動，搖落任江潭。"]', '["清旭楚宮南，霜空万嶺含。","野人时独往，云木晓相參。","俊鶻無声過，飢烏下食貪。","病身終不动，搖落任江潭。"]', '诗', 'shi', '', NULL, '朝二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ed53e6-3ceb-4ee2-841b-b7b650f6a181', '朝二首 二', '朝二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["浦帆晨初發，郊扉冷未開。","村疎黃葉墜，野靜白鷗來。","礎潤休全濕，雲晴欲半迴。","巫山冬可怪，昨夜有奔雷。"]', '["浦帆晨初發，郊扉冷未开。","村疎黄葉墜，野静白鷗来。","礎潤休全濕，云晴欲半迴。","巫山冬可怪，昨夜有奔雷。"]', '诗', 'shi', '', NULL, '朝二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043ea961-e63c-4290-9855-18f4a557fc99', '晚', '晚', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["杖藜尋晚巷，炙背近牆暄。","人見幽居僻，吾知拙養尊。","朝廷問府主，耕稼學山村。","歸翼飛棲定，寒燈亦閉門。"]', '["杖藜尋晚巷，炙背近牆暄。","人见幽居僻，吾知拙養尊。","朝廷问府主，耕稼学山村。","归翼飞棲定，寒灯亦閉门。"]', '诗', 'shi', '', NULL, '晚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5139b5-2036-43ab-8e97-dbe0a073e7ba', '夜二首 一', '夜二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白夜月休弦，燈花半委眠。","號山無定鹿，落樹有驚蟬。","暫憶江東鱠，兼懷雪下船。","蠻歌犯星起，空覺在天邊。"]', '["白夜月休弦，灯花半委眠。","號山無定鹿，落樹有驚蟬。","暫憶江东鱠，兼懷雪下船。","蠻歌犯星起，空覺在天邊。"]', '诗', 'shi', '', NULL, '夜二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942a3584-0241-43e2-ab41-0d63407f0677', '夜二首 二', '夜二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城郭悲笳暮，村墟過翼稀。","甲兵年數久，賦歛夜深歸。","暗樹依巖落，明河繞塞微。","斗斜人更望，月細鵲休飛。"]', '["城郭悲笳暮，村墟過翼稀。","甲兵年數久，賦歛夜深归。","暗樹依巖落，明河繞塞微。","斗斜人更望，月細鵲休飞。"]', '诗', 'shi', '', NULL, '夜二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e55ae3-1751-4afc-b2f9-00d2ad5b6f99', '宗武生日', '宗武生日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["小子何時見，高秋此日生。","自從都邑語，已伴老夫名。","詩是吾家事，人傳世上情。","熟精文選理，休覓綵衣輕。","凋瘵筵初秩，欹斜坐不成。","流霞分片片，涓滴就徐傾。"]', '["小子何时见，高秋此日生。","自從都邑語，已伴老夫名。","诗是吾家事，人傳世上情。","熟精文選理，休覓綵衣轻。","凋瘵筵初秩，欹斜坐不成。","流霞分片片，涓滴就徐傾。"]', '诗', 'shi', '', NULL, '宗武生日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b096aa9c-b7cd-424f-808e-aef597a16cc8', '又示宗武', '又示宗武', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["覓句新知律，攤書解滿牀。","試吟青玉案，莫羨紫羅囊。","假日從時飲，明年共我長。","應須飽經術，已似愛文章。","十五男兒志，三千弟子行。","曾參與游夏，達者得升堂。"]', '["覓句新知律，攤书解满牀。","試吟青玉案，莫羨紫羅囊。","假日從时饮，明年共我长。","應須飽經術，已似愛文章。","十五男兒志，三千弟子行。","曾參與游夏，達者得升堂。"]', '诗', 'shi', '', NULL, '又示宗武 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bf9a4a-a4fc-4ad0-95f0-ee3c63af195c', '熟食日示宗文宗武', '熟食日示宗文宗武', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["消渴游江漢，羇棲尚甲兵。","幾年逢熟食，萬里逼清明。","松柏邛山路，風花白帝城。","汝曹催我老，回首淚縱橫。"]', '["消渴游江漢，羇棲尚甲兵。","幾年逢熟食，万里逼清明。","松柏邛山路，风花白帝城。","汝曹催我老，回首泪縱橫。"]', '诗', 'shi', '', NULL, '熟食日示宗文宗武 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9479b1f-ab0c-445d-bf85-aafafbc341b0', '又示兩兒', '又示兩兒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["令節成吾老，他時見汝心。","浮生看物變，爲恨與年深。","長葛書難得，江州涕不禁。","團圓思弟妹，行坐白頭吟。"]', '["令節成吾老，他时见汝心。","浮生看物变，爲恨與年深。","长葛书难得，江州涕不禁。","團圓思弟妹，行坐白头吟。"]', '诗', 'shi', '', NULL, '又示兩兒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64534567-3196-4c84-bc73-077e7014b48b', '社日兩篇 一', '社日兩篇 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["九農成德業，百祀發光輝。","報効神如在，馨香舊不違。","南翁巴曲醉，北雁塞聲微。","尚想東方朔，詼諧割肉歸。"]', '["九農成德業，百祀發光輝。","報効神如在，馨香旧不違。","南翁巴曲醉，北雁塞声微。","尚想东方朔，詼諧割肉归。"]', '诗', 'shi', '', NULL, '社日兩篇 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9109b067-2471-4810-80e4-36e31f4d3c59', '社日兩篇 二', '社日兩篇 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陳平亦分肉，太史竟論功。","今日江南老，他時渭北童。","歡娛看絕塞，涕淚落秋風。","鴛鷺迴金闕，誰憐病峽中。"]', '["陳平亦分肉，太史竟論功。","今日江南老，他时渭北童。","歡娛看絕塞，涕泪落秋风。","鴛鷺迴金闕，誰怜病峽中。"]', '诗', 'shi', '', NULL, '社日兩篇 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f844a6-969b-4af7-be73-b1c12c0cd7fb', '九日五首 一', '九日五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["重陽獨酌杯中酒，抱病起登江上臺。","竹葉於人既無分，菊花從此不須開。","殊方日落玄猨哭，舊國霜前白雁來。","弟妹蕭條各何往，干戈衰謝兩相催。"]', '["重陽独酌杯中酒，抱病起登江上台。","竹葉於人既無分，菊花從此不須开。","殊方日落玄猨哭，旧国霜前白雁来。","弟妹蕭條各何往，干戈衰謝兩相催。"]', '诗', 'shi', '', NULL, '九日五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e32f511-cc12-47dd-9c32-b3ca629c807f', '九日五首 二', '九日五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舊日重陽日，傳杯不放杯。","即今蓬鬢改，但媿菊花開。","北闕心長戀，西江首獨回。","茱萸賜朝士，難得一枝來。"]', '["旧日重陽日，傳杯不放杯。","即今蓬鬢改，但媿菊花开。","北闕心长戀，西江首独回。","茱萸賜朝士，难得一枝来。"]', '诗', 'shi', '', NULL, '九日五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb68e82-7216-4179-9b85-6f04894890b0', '九日五首 三', '九日五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舊與蘇司業，兼隨鄭廣文。","采花香泛泛，坐客醉紛紛。","野樹歌還倚，秋砧醒却聞。","歡娛兩冥漠，西北有孤雲。"]', '["旧與蘇司業，兼隨鄭廣文。","采花香泛泛，坐客醉紛紛。","野樹歌還倚，秋砧醒却闻。","歡娛兩冥漠，西北有孤云。"]', '诗', 'shi', '', NULL, '九日五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c8db32-a5d6-4d73-869d-36bd63632165', '九日五首 四', '九日五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故里樊川菊，登高素滻源。","他時一笑後，今日幾人存。","巫峽蟠江路，終南對國門。","繫舟身萬里，伏枕淚雙痕。","爲客裁烏帽，從兒具綠尊。","佳辰對羣盜，愁絕更誰論。"]', '["故里樊川菊，登高素滻源。","他时一笑後，今日幾人存。","巫峽蟠江路，終南对国门。","繫舟身万里，伏枕泪雙痕。","爲客裁烏帽，從兒具綠尊。","佳辰对羣盜，愁絕更誰論。"]', '诗', 'shi', '', NULL, '九日五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99953267-a278-429d-8470-cc30ebcb23d8', '九日諸人集於林', '九日諸人集於林', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["九日明朝是，相要舊俗非。","老翁難早出，賢客幸知歸。","舊采黃花賸，新梳白髮微。","漫看年少樂，忍淚已霑衣。"]', '["九日明朝是，相要旧俗非。","老翁难早出，賢客幸知归。","旧采黄花賸，新梳白髮微。","漫看年少乐，忍泪已霑衣。"]', '诗', 'shi', '', NULL, '九日諸人集於林 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc51055-b8fa-4406-97d0-9a15a278e625', '大曆二年九月三十日', '大曆二年九月三十日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["爲客無時了，悲秋向夕終。","瘴餘夔子國，霜薄楚王宮。","草敵虛嵐翠，花禁冷葉紅。","年年小搖落，不與故園同。"]', '["爲客無时了，悲秋向夕終。","瘴餘夔子国，霜薄楚王宮。","草敵虛嵐翠，花禁冷葉紅。","年年小搖落，不與故园同。"]', '诗', 'shi', '', NULL, '大曆二年九月三十日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f359eb2d-3671-4965-b5fe-aff74c5291ae', '十月一日', '十月一日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有瘴非全歇，爲冬亦不難。","夜郎溪日暖，白帝峽風寒。","蒸裹如千室，焦糟幸一柈。","茲辰南國重，舊俗自相歡。"]', '["有瘴非全歇，爲冬亦不难。","夜郎溪日暖，白帝峽风寒。","蒸裹如千室，焦糟幸一柈。","茲辰南国重，旧俗自相歡。"]', '诗', 'shi', '', NULL, '十月一日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2964fb5-3402-47eb-875d-39a3c362aa45', '孟冬', '孟冬', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["殊俗還多事，方冬變所爲。","破甘霜落爪，嘗稻雪飜匙。","巫峽寒都薄，烏蠻瘴遠隨。","終然減灘瀨，暫喜息蛟螭。"]', '["殊俗還多事，方冬变所爲。","破甘霜落爪，嘗稻雪飜匙。","巫峽寒都薄，烏蠻瘴远隨。","終然減灘瀨，暫喜息蛟螭。"]', '诗', 'shi', '', NULL, '孟冬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b2f98c-604f-4705-9a4e-0c931115db82', '冬至', '冬至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["年年至日長爲客，忽忽窮愁泥殺人。","江上形容吾獨老，天邊風俗自相親。","杖蓼雪後臨丹壑，鳴玉朝來散紫宸。","心折此時無一寸，路迷何處見三秦。"]', '["年年至日长爲客，忽忽窮愁泥殺人。","江上形容吾独老，天邊风俗自相親。","杖蓼雪後臨丹壑，鳴玉朝来散紫宸。","心折此时無一寸，路迷何处见三秦。"]', '诗', 'shi', '', NULL, '冬至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fad2cd-27f2-41c4-8a73-609a47cb7ca8', '小至', '小至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天時人事日相催，冬至陽生春又來。","刺繡五紋添弱線，吹葭六琯動浮灰。","岸容待臘將舒柳，山意衝寒欲放梅。","雲物不殊鄉國異，教兒且覆掌中杯。"]', '["天时人事日相催，冬至陽生春又来。","刺繡五紋添弱線，吹葭六琯动浮灰。","岸容待臘將舒柳，山意衝寒欲放梅。","云物不殊乡国異，教兒且覆掌中杯。"]', '诗', 'shi', '', NULL, '小至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32118e72-1998-4024-8b55-9748d737ff19', '覽物', '覽物', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["曾爲掾吏趨三輔，憶在潼關詩興多。","巫峽忽如瞻華岳，蜀江猶似見黃河。","舟中得病移衾枕，洞口經春長薜蘿。","形勝有餘風土惡，幾時回首一高歌。"]', '["曾爲掾吏趨三輔，憶在潼关诗兴多。","巫峽忽如瞻华岳，蜀江猶似见黄河。","舟中得病移衾枕，洞口經春长薜蘿。","形勝有餘风土惡，幾时回首一高歌。"]', '诗', 'shi', '', NULL, '覽物 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f744f20-8aa2-452d-90d9-0a35661500b8', '憶鄭南玭', '憶鄭南玭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭南伏毒寺，瀟灑到江心。","石影銜珠閣，泉聲帶玉琴。","風杉曾曙倚，雲嶠憶春臨。","萬里滄浪外，龍蛇只自深。"]', '["鄭南伏毒寺，瀟灑到江心。","石影銜珠閣，泉声带玉琴。","风杉曾曙倚，云嶠憶春臨。","万里滄浪外，龙蛇只自深。"]', '诗', 'shi', '', NULL, '憶鄭南玭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f30df76-f2b1-4af1-812d-2141b289a801', '懷灞上游', '懷灞上游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["悵望東陵道，平生灞上游。","春濃停野騎，夜宿敞雲樓。","離別人誰在，經過老自休。","眼前今古意，江漢一歸舟。"]', '["悵望东陵道，平生灞上游。","春濃停野騎，夜宿敞云楼。","離別人誰在，經過老自休。","眼前今古意，江漢一归舟。"]', '诗', 'shi', '', NULL, '懷灞上游 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fcf79dd-3517-459b-8b4c-2d270073d8f9', '愁', '愁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江草日日喚愁生，巫峽泠泠非世情。","盤渦鷺浴底心性，獨樹花發自分明。","十年戎馬暗萬國，異域賓客老孤城。","渭水秦山得見否，人經罷病虎縱橫。"]', '["江草日日喚愁生，巫峽泠泠非世情。","盤渦鷺浴底心性，独樹花發自分明。","十年戎马暗万国，異域賓客老孤城。","渭水秦山得见否，人經罷病虎縱橫。"]', '诗', 'shi', '', NULL, '愁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af29ed64-419d-4eeb-803a-8466d45a7a2b', '晝夢', '晝梦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二月饒睡昏昏然，不獨夜短晝分眠。","桃花氣暖眼自醉，春渚日落夢相牽。","故鄉門巷荆棘底，中原君臣豺虎邊。","安得務農息戰鬬，普天無吏橫索錢。"]', '["二月饒睡昏昏然，不独夜短晝分眠。","桃花氣暖眼自醉，春渚日落梦相牽。","故乡门巷荆棘底，中原君臣豺虎邊。","安得務農息戰鬬，普天無吏橫索錢。"]', '诗', 'shi', '', NULL, '晝夢 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b3901b-45f3-44c6-a660-8b989e9d795f', '覽鏡呈柏中丞', '覽镜呈柏中丞', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["渭水流關內，終南在日邊。","膽銷豺虎窟，淚入犬羊天。","起晚堪從事，行遲更學仙。","鏡中衰謝色，萬一故人憐。"]', '["渭水流关內，終南在日邊。","膽銷豺虎窟，泪入犬羊天。","起晚堪從事，行遲更学仙。","镜中衰謝色，万一故人怜。"]', '诗', 'shi', '', NULL, '覽鏡呈柏中丞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d134030-f67d-48b9-b743-bc87db6edbd2', '即事', '即事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暮春三月巫峽長，皛皛行雲浮日光。","雷聲忽送千峰雨，花氣渾如百和香。","黃鶯過水飜迴去，燕子銜泥濕不妨。","飛閣卷簾圖畫里，虛無只少對瀟湘。"]', '["暮春三月巫峽长，皛皛行云浮日光。","雷声忽送千峰雨，花氣渾如百和香。","黄鶯過水飜迴去，燕子銜泥濕不妨。","飞閣卷簾圖畫里，虛無只少对瀟湘。"]', '诗', 'shi', '', NULL, '即事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f025f691-f758-4eab-b603-b3a6ea5fd5a2', '即事', '即事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天畔羣山孤草亭，江中風浪雨冥冥。","一雙白魚不受釣，三寸黃甘猶自青。","多病馬卿無日起，窮途阮籍幾時醒。","未聞細柳散金甲，腸斷秦川流濁涇。"]', '["天畔羣山孤草亭，江中风浪雨冥冥。","一雙白鱼不受釣，三寸黄甘猶自青。","多病马卿無日起，窮途阮籍幾时醒。","未闻細柳散金甲，腸斷秦川流濁涇。"]', '诗', 'shi', '', NULL, '即事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f436f0-773e-4950-955f-02fa11806b60', '悶', '悶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["瘴癘浮三蜀，風雲暗百蠻。","卷簾唯白水，隱几亦青山。","猨捷長難見，鷗輕故不還。","無錢從滯客，有鏡巧催顏。"]', '["瘴癘浮三蜀，风云暗百蠻。","卷簾唯白水，隐几亦青山。","猨捷长难见，鷗轻故不還。","無錢從滯客，有镜巧催顏。"]', '诗', 'shi', '', NULL, '悶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3971c6-08a0-4a9b-9afa-9f9bacedc485', '戲作俳諧體遣悶二首 一', '戲作俳諧體遣悶二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["異俗吁可怪，斯人難竝居。","家家養烏鬼，頓頓食黃魚。","舊識能爲態，新知已暗疎。","治生且耕鑿，只有不關渠。"]', '["異俗吁可怪，斯人难竝居。","家家養烏鬼，頓頓食黄鱼。","旧識能爲態，新知已暗疎。","治生且耕鑿，只有不关渠。"]', '诗', 'shi', '', NULL, '戲作俳諧體遣悶二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbe59952-b373-49cb-9578-fe33c09ba5c2', '戲作俳諧體遣悶二首 二', '戲作俳諧體遣悶二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西歷青羌板，南留白帝城。","於菟侵客恨，粔籹作人情。","瓦卜傳神語，畬田費火聲。","是非何處定，高枕笑浮生。"]', '["西歷青羌板，南留白帝城。","於菟侵客恨，粔籹作人情。","瓦卜傳神語，畬田費火声。","是非何处定，高枕笑浮生。"]', '诗', 'shi', '', NULL, '戲作俳諧體遣悶二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a80b6c10-6672-4efb-ba89-6ef86beab5bf', '得舍弟觀書自中都已達江陵今茲暮春月末行李合到夔州悲喜相兼團圓可待賦詩即事情見乎詞', '得舍弟观书自中都已達江陵今茲暮春月末行李合到夔州悲喜相兼團圓可待賦诗即事情见乎词', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["爾到江陵府，何時到峽州？","亂難生有別，聚集病應瘳。","颯颯開啼眼，朝朝上水樓。","老身須付託，白骨更何憂。"]', '["爾到江陵府，何时到峽州？","亂难生有別，聚集病應瘳。","颯颯开啼眼，朝朝上水楼。","老身須付託，白骨更何憂。"]', '诗', 'shi', '', NULL, '得舍弟觀書自中都已達江陵今茲暮春月末行李合到夔州悲喜相兼團圓可待賦詩即事情見乎詞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf68f337-d8fc-48a3-b89e-a828d08189a6', '喜觀即到復題短篇二首 一', '喜观即到复題短篇二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫峽千山暗，終南萬里春。","病中吾見弟，書到汝爲人。","意荅兒童問，來經戰伐新。","泊船悲喜後，款款話歸秦。"]', '["巫峽千山暗，終南万里春。","病中吾见弟，书到汝爲人。","意荅兒童问，来經戰伐新。","泊船悲喜後，款款話归秦。"]', '诗', 'shi', '', NULL, '喜觀即到復題短篇二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72f883a-a7ee-4905-8dea-a0315c738a02', '喜觀即到復題短篇二首 二', '喜观即到复題短篇二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["待爾嗔烏鵲，拋書示鶺鴒。","枝間喜不去，原上急曾經。","江閣嫌津柳，風帆數驛亭。","應論十年事，愁絕始星星。"]', '["待爾嗔烏鵲，拋书示鶺鴒。","枝间喜不去，原上急曾經。","江閣嫌津柳，风帆數驛亭。","應論十年事，愁絕始星星。"]', '诗', 'shi', '', NULL, '喜觀即到復題短篇二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e5281a-acc8-4fed-8465-8bb4571e1772', '舍弟觀歸藍田迎新婦送示兩篇 一', '舍弟观归藍田迎新婦送示兩篇 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝去迎妻子，高秋念却迴。","即今螢已亂，好與雁同來。","東望西江水，南游北戶開。","卜居期靜處，會有故人杯。"]', '["汝去迎妻子，高秋念却迴。","即今螢已亂，好與雁同来。","东望西江水，南游北戶开。","卜居期静处，會有故人杯。"]', '诗', 'shi', '', NULL, '舍弟觀歸藍田迎新婦送示兩篇 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc21a6b4-7895-4de7-ab76-e68938f6d000', '舍弟觀歸藍田迎新婦送示兩篇 二', '舍弟观归藍田迎新婦送示兩篇 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚塞難爲路，藍田莫滯留。","衣裳判白露，鞍馬信清秋。","滿峽重江水，開帆八月舟。","此時同一醉，應在仲宣樓。"]', '["楚塞难爲路，藍田莫滯留。","衣裳判白露，鞍马信清秋。","满峽重江水，开帆八月舟。","此时同一醉，應在仲宣楼。"]', '诗', 'shi', '', NULL, '舍弟觀歸藍田迎新婦送示兩篇 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d14e01f-3e98-434b-8861-c6335b7b8bfa', '第五弟豐獨在江左近三四載寂無消息覓使寄此二首 一', '第五弟豐独在江左近三四載寂無消息覓使寄此二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亂後嗟吾在，羇棲見汝難。","草黃騏驥病，沙晚鶺鴒寒。","楚設關城險，吳吞水府寬。","十年朝夕淚，衣袖不曾乾。"]', '["亂後嗟吾在，羇棲见汝难。","草黄騏驥病，沙晚鶺鴒寒。","楚設关城險，吳吞水府寬。","十年朝夕泪，衣袖不曾乾。"]', '诗', 'shi', '', NULL, '第五弟豐獨在江左近三四載寂無消息覓使寄此二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62fc4c1-c077-430f-b1e3-6cfab542626d', '第五弟豐獨在江左近三四載寂無消息覓使寄此二首 二', '第五弟豐独在江左近三四載寂無消息覓使寄此二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞汝依山寺，杭州定越州。","風塵淹別日，江漢失清秋。","影蓋啼猨樹，魂飄結蜃樓。","明年下春水，東盡白雲求。"]', '["闻汝依山寺，杭州定越州。","风塵淹別日，江漢失清秋。","影蓋啼猨樹，魂飄結蜃楼。","明年下春水，东尽白云求。"]', '诗', 'shi', '', NULL, '第五弟豐獨在江左近三四載寂無消息覓使寄此二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a248b0-23e9-4a15-b6b2-2e41eff3b430', '舍弟觀赴藍田取妻子到江陵喜寄三首 一', '舍弟观赴藍田取妻子到江陵喜寄三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝迎妻子達荆州，消息真傳解我憂。","鴻雁影來連峽內，鶺鴒飛急到沙頭。","嶢關險路今虛遠，禹鑿寒江正穩流。","朱紱即當隨彩鷁，青春不假報黃牛。"]', '["汝迎妻子達荆州，消息真傳解我憂。","鴻雁影来連峽內，鶺鴒飞急到沙头。","嶢关險路今虛远，禹鑿寒江正穩流。","朱紱即當隨彩鷁，青春不假報黄牛。"]', '诗', 'shi', '', NULL, '舍弟觀赴藍田取妻子到江陵喜寄三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066963f7-a2f3-44bf-821c-2a1778987a44', '舍弟觀赴藍田取妻子到江陵喜寄三首 二', '舍弟观赴藍田取妻子到江陵喜寄三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["馬度秦關雪正深，北來肌骨苦寒侵。","他鄉就我生春色，故國移居見客心。","賸欲提攜如意舞，喜多行坐白頭吟。","巡檐索共梅花笑，冷蘂疎枝半不禁。"]', '["马度秦关雪正深，北来肌骨苦寒侵。","他乡就我生春色，故国移居见客心。","賸欲提携如意舞，喜多行坐白头吟。","巡檐索共梅花笑，冷蘂疎枝半不禁。"]', '诗', 'shi', '', NULL, '舍弟觀赴藍田取妻子到江陵喜寄三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb1f819-6534-4a57-ac68-47df60a71dd8', '舍弟觀赴藍田取妻子到江陵喜寄三首 三', '舍弟观赴藍田取妻子到江陵喜寄三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["庾信羅含俱有宅，春來秋去作誰家。","短牆若在從殘草，喬木如存可假花。","卜築應同蔣詡徑，爲園須似邵平瓜。","比年病酒開涓滴，弟勸兄酬何怨嗟。"]', '["庾信羅含俱有宅，春来秋去作誰家。","短牆若在從殘草，喬木如存可假花。","卜築應同蔣詡徑，爲园須似邵平瓜。","比年病酒开涓滴，弟勸兄酬何怨嗟。"]', '诗', 'shi', '', NULL, '舍弟觀赴藍田取妻子到江陵喜寄三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27325080-ff2f-4215-80b3-5c9e56c319d2', '江雨有懷鄭典設', '江雨有懷鄭典設', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春雨闇闇塞峽中，早晚來自楚王宮。","亂波分披已打岸，弱雲狼籍不禁風。","寵光蕙葉與多碧，點注桃花舒小紅。","谷口子真正憶汝，岸高瀼滑限西東。"]', '["春雨闇闇塞峽中，早晚来自楚王宮。","亂波分披已打岸，弱云狼籍不禁风。","寵光蕙葉與多碧，点注桃花舒小紅。","谷口子真正憶汝，岸高瀼滑限西东。"]', '诗', 'shi', '', NULL, '江雨有懷鄭典設 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b39ff1f-95d3-43b6-ad22-561c8e97f329', '王十五前閣會', '王十五前閣會', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚岸收新雨，春臺引細風。","情人來石上，鮮膾出江中。","鄰舍煩書札，肩輿強老翁。","病身虛俊味，何幸飫兒童。"]', '["楚岸收新雨，春台引細风。","情人来石上，鲜膾出江中。","鄰舍煩书札，肩輿強老翁。","病身虛俊味，何幸飫兒童。"]', '诗', 'shi', '', NULL, '王十五前閣會 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f46788-340a-4f53-938d-fc410d36b6a5', '寄韋有夏郎中', '寄韋有夏郎中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["省郎憂病士，書信有柴胡。","飲子頻通汗，懷君想報珠。","親知天畔少，藥味峽中無。","歸楫生衣臥，春鷗洗翅呼。","猶聞上急水，早作取平途。","萬里皇華使，爲僚記腐儒。"]', '["省郎憂病士，书信有柴胡。","饮子頻通汗，懷君想報珠。","親知天畔少，藥味峽中無。","归楫生衣臥，春鷗洗翅呼。","猶闻上急水，早作取平途。","万里皇华使，爲僚記腐儒。"]', '诗', 'shi', '', NULL, '寄韋有夏郎中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11571817-7134-4718-aff3-78fbc55d9261', '陪柏中丞觀宴將士二首 一', '陪柏中丞观宴將士二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["極樂三軍士，誰知百戰場。","無私齊綺饌，久坐密金章。","醉客霑鸚鵡，佳人指鳳皇。","幾時來翠節，特地引紅妝。"]', '["極乐三軍士，誰知百戰場。","無私齊綺饌，久坐密金章。","醉客霑鸚鵡，佳人指鳳皇。","幾时来翠節，特地引紅妝。"]', '诗', 'shi', '', NULL, '陪柏中丞觀宴將士二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8a96faa-dbf2-4aee-9c9f-23e1294413dd', '陪柏中丞觀宴將士二首 二', '陪柏中丞观宴將士二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["繡段裝檐額，金花帖鼓腰。","一夫先舞劒，百戰後歌樵。","江樹城孤遠，雲臺使寂寥。","漢朝頻選將，應拜霍嫖姚。"]', '["繡段裝檐額，金花帖鼓腰。","一夫先舞劒，百戰後歌樵。","江樹城孤远，云台使寂寥。","漢朝頻選將，應拜霍嫖姚。"]', '诗', 'shi', '', NULL, '陪柏中丞觀宴將士二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2c4fcb-b84a-48a2-aa95-d224db25259a', '七月一日題終明府水樓二首 一', '七月一日題終明府水楼二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高棟曾軒已自涼，秋風此日灑衣裳。","翛然欲下陰山雪，不去非無漢署香。","絕辟過雲開錦繡，疎松夾水奏笙簧。","看君宜著王喬履，真賜還疑出尚方。"]', '["高棟曾軒已自涼，秋风此日灑衣裳。","翛然欲下陰山雪，不去非無漢署香。","絕辟過云开錦繡，疎松夾水奏笙簧。","看君宜著王喬履，真賜還疑出尚方。"]', '诗', 'shi', '', NULL, '七月一日題終明府水樓二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d87ed489-916b-4f7a-8a7d-fdf3078ef511', '七月一日題終明府水樓二首 二', '七月一日題終明府水楼二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宓子彈琴邑宰日，終軍棄繻英妙時。","承家節操尚不泯，爲政風流今在茲。","可憐賓客盡傾蓋，何處老翁來賦詩。","楚江巫峽半雲雨，清簟疎簾看弈棊。"]', '["宓子彈琴邑宰日，終軍棄繻英妙时。","承家節操尚不泯，爲政风流今在茲。","可怜賓客尽傾蓋，何处老翁来賦诗。","楚江巫峽半云雨，清簟疎簾看弈棊。"]', '诗', 'shi', '', NULL, '七月一日題終明府水樓二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfc3534-4103-4c5f-965e-72778db7bc01', '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 一', '季秋蘇五弟纓江楼夜宴崔十三評事韋少府姪三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["峽險江驚急，樓高月迥明。","一時今夕會，萬里故鄉情。","星落黃姑渚，秋辭白帝城。","老人因酒病，堅坐看君傾。"]', '["峽險江驚急，楼高月迥明。","一时今夕會，万里故乡情。","星落黄姑渚，秋辞白帝城。","老人因酒病，堅坐看君傾。"]', '诗', 'shi', '', NULL, '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe486143-8dbd-4391-ae7b-2a36a4858d2b', '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 二', '季秋蘇五弟纓江楼夜宴崔十三評事韋少府姪三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["明月生長好，浮雲薄漸遮。","悠悠照邊塞，悄悄憶京華。","清動杯中物，高隨海上查。","不眠瞻白兔，百過落烏紗。"]', '["明月生长好，浮云薄漸遮。","悠悠照邊塞，悄悄憶京华。","清动杯中物，高隨海上查。","不眠瞻白兔，百過落烏紗。"]', '诗', 'shi', '', NULL, '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a63d70ba-5ee4-4cce-9062-4cb425497f7f', '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 三', '季秋蘇五弟纓江楼夜宴崔十三評事韋少府姪三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["對月那無酒，登樓況有江。","聽歌驚白鬢，笑舞拓秋窗。","尊蟻添相續，沙鷗竝一雙。","盡憐君醉倒，更覺片心降。"]', '["对月那無酒，登楼況有江。","听歌驚白鬢，笑舞拓秋窗。","尊蟻添相續，沙鷗竝一雙。","尽怜君醉倒，更覺片心降。"]', '诗', 'shi', '', NULL, '季秋蘇五弟纓江樓夜宴崔十三評事韋少府姪三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab6e7da-29bb-4c2b-8dd5-c23ec5725d97', '九月一日過孟十二倉曹十四主簿兄弟', '九月一日過孟十二倉曹十四主簿兄弟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["藜杖侵寒露，蓬門啓曙煙。","力稀經樹歇，老困撥書眠。","秋覺追隨盡，來因孝友偏。","清談見滋味，爾輩可忘年。"]', '["藜杖侵寒露，蓬门啓曙煙。","力稀經樹歇，老困撥书眠。","秋覺追隨尽，来因孝友偏。","清談见滋味，爾輩可忘年。"]', '诗', 'shi', '', NULL, '九月一日過孟十二倉曹十四主簿兄弟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db532d17-1533-4e02-8355-5dd36690106f', '過客相尋', '過客相尋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["窮老真無事，江山已定居。","地幽忘盥櫛，客至罷琴書。","挂壁移筐果，呼兒問煮魚。","時聞繫舟楫，及此問吾廬。"]', '["窮老真無事，江山已定居。","地幽忘盥櫛，客至罷琴书。","挂壁移筐果，呼兒问煮鱼。","时闻繫舟楫，及此问吾廬。"]', '诗', 'shi', '', NULL, '過客相尋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6db70bd-85c9-4fc5-900d-878c34a96df7', '孟倉曹步趾領新酒醬二物滿器見遺老夫', '孟倉曹步趾領新酒醬二物满器见遺老夫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚岸通秋屐，胡牀面夕畦。","藉糟分汁滓，甕醬落提攜。","飯糲添香味，朋來有醉泥。","理生那免俗，方法報山妻。"]', '["楚岸通秋屐，胡牀面夕畦。","藉糟分汁滓，甕醬落提携。","飯糲添香味，朋来有醉泥。","理生那免俗，方法報山妻。"]', '诗', 'shi', '', NULL, '孟倉曹步趾領新酒醬二物滿器見遺老夫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97384a23-7f75-4d43-baee-ac6c4a6c6d14', '柳司馬至', '柳司马至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有使歸三峽，相過問兩京。","函關猶出將，渭水更屯兵。","設備邯鄲道，和親邏些城。","幽燕唯鳥去，商洛少人行。","衰謝身何補，蕭條病轉嬰。","霜天到宮闕，戀主寸心明。"]', '["有使归三峽，相過问兩京。","函关猶出將，渭水更屯兵。","設備邯鄲道，和親邏些城。","幽燕唯鸟去，商洛少人行。","衰謝身何補，蕭條病轉嬰。","霜天到宮闕，戀主寸心明。"]', '诗', 'shi', '', NULL, '柳司馬至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db1025d2-bf15-46df-af97-d96aa4b570e8', '簡吳郎司法', '簡吳郎司法', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有客乘舸自忠州，遣騎安置瀼西頭。","古堂本買藉疎豁，借汝遷居停宴遊。","雲石熒熒高葉曙，風江颯颯亂帆秋。","却爲姻婭過逢地，許坐曾軒數散愁。"]', '["有客乘舸自忠州，遣騎安置瀼西头。","古堂本買藉疎豁，借汝遷居停宴游。","云石熒熒高葉曙，风江颯颯亂帆秋。","却爲姻婭過逢地，許坐曾軒數散愁。"]', '诗', 'shi', '', NULL, '簡吳郎司法 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18b9273-a4d2-493b-8320-5025f2d174f7', '又呈吳郎', '又呈吳郎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["堂前撲棗任西鄰，無食無兒一婦人。","不爲困窮寧有此，祗緣恐懼轉須親。","即防遠客雖多事，使插疎籬却甚真。","已訴徵求貧到骨，正思戎馬淚盈巾。"]', '["堂前撲棗任西鄰，無食無兒一婦人。","不爲困窮寧有此，祗緣恐懼轉須親。","即防远客雖多事，使插疎籬却甚真。","已訴徵求貧到骨，正思戎马泪盈巾。"]', '诗', 'shi', '', NULL, '又呈吳郎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db033ee9-5ef8-4acb-8606-c777217f7ae8', '覃山人隱居', '覃山人隐居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南極老人自有星，北山移文誰勒銘。","徵君已去獨松菊，哀壑無光留戶庭。","予見亂離不得已，子知出處必須經。","高車駟馬帶傾覆，悵望秋天虛翠屏。"]', '["南極老人自有星，北山移文誰勒銘。","徵君已去独松菊，哀壑無光留戶庭。","予见亂離不得已，子知出处必須經。","高车駟马带傾覆，悵望秋天虛翠屏。"]', '诗', 'shi', '', NULL, '覃山人隱居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b51ca3b-92b6-4a73-b382-201a23ac190f', '柏學士茅屋', '柏学士茅屋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["碧山學士焚銀魚，白馬却走身巖居。","古人已用三冬足，年少今開萬卷餘。","晴雲滿戶團傾蓋，秋水浮階溜決渠。","富貴必從勤苦得，男兒須讀五車書。"]', '["碧山学士焚銀鱼，白马却走身巖居。","古人已用三冬足，年少今开万卷餘。","晴云满戶團傾蓋，秋水浮階溜決渠。","富貴必從勤苦得，男兒須读五车书。"]', '诗', 'shi', '', NULL, '柏學士茅屋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc1af26-0421-4d87-bc86-8a5f069f9618', '題柏大兄弟山居屋壁二首 一', '題柏大兄弟山居屋壁二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["叔父朱門貴，郎君玉樹高。","山居精典籍，文雅涉風騷。","江漢終吾老，雲林得爾曹。","哀弦繞白雪，未與俗人操。"]', '["叔父朱门貴，郎君玉樹高。","山居精典籍，文雅涉风騷。","江漢終吾老，云林得爾曹。","哀弦繞白雪，未與俗人操。"]', '诗', 'shi', '', NULL, '題柏大兄弟山居屋壁二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277fdcd3-6161-402c-a8c7-d7fc6e7b31f3', '題柏大兄弟山居屋壁二首 二', '題柏大兄弟山居屋壁二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野屋流寒水，山籬帶薄雲。","靜應連虎穴，喧已去人羣。","筆架霑窗雨，書籤映隙曛。","蕭蕭千里足，箇箇五花文。"]', '["野屋流寒水，山籬带薄云。","静應連虎穴，喧已去人羣。","笔架霑窗雨，书籤映隙曛。","蕭蕭千里足，箇箇五花文。"]', '诗', 'shi', '', NULL, '題柏大兄弟山居屋壁二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86cfbd16-96b4-47c6-9142-6a804159e696', '戲寄崔評事表姪蘇五表弟韋大少府諸姪', '戲寄崔評事表姪蘇五表弟韋大少府諸姪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["隱豹深愁雨，潛龍故起雲。","泥多仍徑曲，心醉阻賢羣。","忍待江山麗，還披鮑謝文。","高樓憶疎豁，秋興坐氛氳。"]', '["隐豹深愁雨，潛龙故起云。","泥多仍徑曲，心醉阻賢羣。","忍待江山丽，還披鲍謝文。","高楼憶疎豁，秋兴坐氛氳。"]', '诗', 'shi', '', NULL, '戲寄崔評事表姪蘇五表弟韋大少府諸姪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf55595-28d2-4205-af87-cc08359db896', '秋日寄題鄭監湖上亭三首 一', '秋日寄題鄭監湖上亭三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["碧草逢春意，沅湘萬里秋。","池要山簡馬，月淨庾公樓。","磨滅餘篇翰，平生一釣舟。","高唐寒浪減，髣髴識昭丘。"]', '["碧草逢春意，沅湘万里秋。","池要山簡马，月淨庾公楼。","磨滅餘篇翰，平生一釣舟。","高唐寒浪減，髣髴識昭丘。"]', '诗', 'shi', '', NULL, '秋日寄題鄭監湖上亭三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e04fb98-104f-4d84-8037-e1e6797e9039', '秋日寄題鄭監湖上亭三首 二', '秋日寄題鄭監湖上亭三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["新作湖邊宅，還聞賓客過。","自須開竹逕，誰道避雲蘿。","官序潘生拙，才名賈傅多。","舍舟應轉地，鄰接意如何。"]', '["新作湖邊宅，還闻賓客過。","自須开竹逕，誰道避云蘿。","官序潘生拙，才名賈傅多。","舍舟應轉地，鄰接意如何。"]', '诗', 'shi', '', NULL, '秋日寄題鄭監湖上亭三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75313436-93f3-4c30-a0ce-be80991b37bf', '秋日寄題鄭監湖上亭三首 三', '秋日寄題鄭監湖上亭三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暫阻蓬萊閣，終爲江海人。","揮金應物理，拖玉豈吾身。","羹煮秋蓴滑，杯迎露菊新。","賦詩分氣象，佳句莫頻頻。"]', '["暫阻蓬萊閣，終爲江海人。","揮金應物理，拖玉豈吾身。","羹煮秋蓴滑，杯迎露菊新。","賦诗分氣象，佳句莫頻頻。"]', '诗', 'shi', '', NULL, '秋日寄題鄭監湖上亭三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0fd6680-7e2c-4e1f-88bc-7ddd77c0789c', '謁真諦寺禪師', '謁真諦寺禪師', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蘭若山高處，煙霞嶂幾重。","凍泉依細石，晴雪落長松。","問法看詩忘，觀身向酒慵。","未能割妻子，卜宅近前峰。"]', '["蘭若山高处，煙霞嶂幾重。","凍泉依細石，晴雪落长松。","问法看诗忘，观身向酒慵。","未能割妻子，卜宅近前峰。"]', '诗', 'shi', '', NULL, '謁真諦寺禪師 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0201eede-b035-4751-a5b5-e2bfbdc6caa2', '別崔潩因寄薛據孟雲卿', '別崔潩因寄薛據孟云卿', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["志士惜妄動，知深難固辭。","如何久磨礪，但取不磷緇。","夙夜聽憂主，飛騰急濟時。","荆州過薛孟，爲報欲論詩。"]', '["志士惜妄动，知深难固辞。","如何久磨礪，但取不磷緇。","夙夜听憂主，飞腾急濟时。","荆州過薛孟，爲報欲論诗。"]', '诗', 'shi', '', NULL, '別崔潩因寄薛據孟雲卿 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e0d2da-d7db-4cd4-bdf8-a8f915a4834f', '送李八祕書赴杜相公幕', '送李八祕书赴杜相公幕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青簾白舫益州來，巫峽秋濤天地迴。","石出倒聽楓葉下，櫓搖背指菊花開。","貪趨相府今晨發，恐失佳期後命催。","南極一星朝北斗，五雲多處是三台。"]', '["青簾白舫益州来，巫峽秋濤天地迴。","石出倒听楓葉下，櫓搖背指菊花开。","貪趨相府今晨發，恐失佳期後命催。","南極一星朝北斗，五云多处是三台。"]', '诗', 'shi', '', NULL, '送李八祕書赴杜相公幕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7375da-6cc8-4663-8397-1f4497397a18', '巫峽敝廬奉贈侍御四舅別之澧朗', '巫峽敝廬奉贈侍御四舅別之澧朗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江城秋日落，山鬼閉門中。","行李淹吾舅，誅茅問老翁。","赤眉猶世亂，青眼只途窮。","傳語桃源客，人今出處同。"]', '["江城秋日落，山鬼閉门中。","行李淹吾舅，誅茅问老翁。","赤眉猶世亂，青眼只途窮。","傳語桃源客，人今出处同。"]', '诗', 'shi', '', NULL, '巫峽敝廬奉贈侍御四舅別之澧朗 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151ea59e-59ce-4a29-bdfa-26448921b811', '奉送十七舅下邵桂', '奉送十七舅下邵桂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["絕域三冬暮，浮生一病身。","感深辭舅氏，別後見何人。","飄緲蒼梧帝，推遷孟母鄰。","昏昏阻雲水，側望苦傷神。"]', '["絕域三冬暮，浮生一病身。","感深辞舅氏，別後见何人。","飄緲蒼梧帝，推遷孟母鄰。","昏昏阻云水，側望苦傷神。"]', '诗', 'shi', '', NULL, '奉送十七舅下邵桂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d93d2a-44ab-43e6-9ba9-bbc9842ccd8f', '送覃二判官', '送覃二判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["先帝弓劒遠，小臣餘此生。","蹉跎病江漢，不復謁承明。","餞爾白頭日，永懷丹鳳城。","遲遲戀屈宋，渺渺臥荆衡。","魂斷航舸失，天寒沙水清。","肺肝若稍愈，亦上赤霄行。"]', '["先帝弓劒远，小臣餘此生。","蹉跎病江漢，不复謁承明。","餞爾白头日，永懷丹鳳城。","遲遲戀屈宋，渺渺臥荆衡。","魂斷航舸失，天寒沙水清。","肺肝若稍愈，亦上赤霄行。"]', '诗', 'shi', '', NULL, '送覃二判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ffde4f-9b57-4829-848c-948b12846150', '季夏送鄉弟韶陪黃門從叔朝謁', '季夏送乡弟韶陪黄门從叔朝謁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["令弟尚爲蒼水使，名家莫出杜陵人。","比來相國兼安蜀，歸赴朝廷已入秦。","舍舟策馬論兵地，拖玉腰金報主身。","莫度清秋吟蟋蟀，早聞黃閣畫麒麟。"]', '["令弟尚爲蒼水使，名家莫出杜陵人。","比来相国兼安蜀，归赴朝廷已入秦。","舍舟策马論兵地，拖玉腰金報主身。","莫度清秋吟蟋蟀，早闻黄閣畫麒麟。"]', '诗', 'shi', '', NULL, '季夏送鄉弟韶陪黃門從叔朝謁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807194fc-963a-4171-94f7-0b8ade8d98b2', '送十五弟侍御使蜀', '送十五弟侍御使蜀', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["喜弟文章進，添余別興牽。","數杯巫峽酒，百丈內江船。","未息豺狼鬬，空催犬馬年。","歸朝多便道，搏擊望秋天。"]', '["喜弟文章進，添余別兴牽。","數杯巫峽酒，百丈內江船。","未息豺狼鬬，空催犬马年。","归朝多便道，搏擊望秋天。"]', '诗', 'shi', '', NULL, '送十五弟侍御使蜀 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f9005f-2a05-4f87-918a-155cb2c81221', '送田四弟將軍將夔州柏中丞命起居江陵節度陽城郡王衛公幕', '送田四弟將軍將夔州柏中丞命起居江陵節度陽城郡王衛公幕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["離筵罷多酒，起地發寒塘。","回首中丞座，馳牋異姓王。","燕辭楓樹日，雁度麥城霜。","空醉山翁酒，遙憐似葛強。"]', '["離筵罷多酒，起地發寒塘。","回首中丞座，驰牋異姓王。","燕辞楓樹日，雁度麦城霜。","空醉山翁酒，遙怜似葛強。"]', '诗', 'shi', '', NULL, '送田四弟將軍將夔州柏中丞命起居江陵節度陽城郡王衛公幕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df82a0f-70f4-488f-afbb-8923dbbe29da', '送王十六判官', '送王十六判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客下荆南盡，君今復入舟。","買薪猶白帝，鳴櫓少沙頭。","衡霍生春早，瀟湘共海浮。","荒林庾信宅，爲仗主人留。"]', '["客下荆南尽，君今复入舟。","買薪猶白帝，鳴櫓少沙头。","衡霍生春早，瀟湘共海浮。","荒林庾信宅，爲仗主人留。"]', '诗', 'shi', '', NULL, '送王十六判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334efb9b-c7a8-482a-a971-fd8aa7b0b3c6', '奉送卿二翁統節度鎮軍還江陵', '奉送卿二翁統節度鎮軍還江陵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["火旗還錦纜，白馬出江城。","嘹唳吟笳發，簫條別浦清。","寒空巫峽曙，落日渭陽明。","留滯嗟衰疾，何時見息兵。"]', '["火旗還錦纜，白马出江城。","嘹唳吟笳發，簫條別浦清。","寒空巫峽曙，落日渭陽明。","留滯嗟衰疾，何时见息兵。"]', '诗', 'shi', '', NULL, '奉送卿二翁統節度鎮軍還江陵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd11e7d-2617-4fc3-9b26-8a0ff5bc2ed2', '送鮮于萬州遷巴州', '送鲜于万州遷巴州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["京兆先時傑，琳琅照一門。","朝廷偏注意，接近與名藩。","祖帳排舟數，寒江觸石喧。","看君妙爲政，他日有殊恩。"]', '["京兆先时傑，琳琅照一门。","朝廷偏注意，接近與名藩。","祖帳排舟數，寒江觸石喧。","看君妙爲政，他日有殊恩。"]', '诗', 'shi', '', NULL, '送鮮于萬州遷巴州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586773dd-0a2a-4bef-a704-7d6d647df4c9', '寄杜位', '寄杜位', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒日經檐短，窮猨失木悲。","峽中爲客恨，江上憶君時。","天地身何在，風塵病敢辭。","封書兩行淚，霑灑裛新詩。"]', '["寒日經檐短，窮猨失木悲。","峽中爲客恨，江上憶君时。","天地身何在，风塵病敢辞。","封书兩行泪，霑灑裛新诗。"]', '诗', 'shi', '', NULL, '寄杜位 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471d2960-d646-4055-8242-ef298fb6aa7b', '奉寄李十五祕書二首 一', '奉寄李十五祕书二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["避暑雲安縣，秋風早下來。","暫留魚復浦，同過楚王臺。","猨鳥千崖窄，江湖萬里開。","竹枝歌未好，畫舸莫遲回。"]', '["避暑云安縣，秋风早下来。","暫留鱼复浦，同過楚王台。","猨鸟千崖窄，江湖万里开。","竹枝歌未好，畫舸莫遲回。"]', '诗', 'shi', '', NULL, '奉寄李十五祕書二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef10e28c-207f-41f0-9345-91d09ef08bf1', '奉寄李十五祕書二首 二', '奉寄李十五祕书二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["行李千金贈，衣冠八尺身。","飛騰知有策，意度不無神。","班秩兼通貴，公侯出異人。","玄成負文彩，世業豈沈淪。"]', '["行李千金贈，衣冠八尺身。","飞腾知有策，意度不無神。","班秩兼通貴，公侯出異人。","玄成負文彩，世業豈沈淪。"]', '诗', 'shi', '', NULL, '奉寄李十五祕書二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e0454e-6d35-47fb-80c1-15f9d6632cea', '奉送韋中丞之晉赴湖南', '奉送韋中丞之晉赴湖南', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寵渥徵黃漸，權宜借寇頻。","湖南安背水，峽內憶行春。","王室仍多故，蒼生倚大臣。","還將徐孺子，處處待高人。"]', '["寵渥徵黄漸，權宜借寇頻。","湖南安背水，峽內憶行春。","王室仍多故，蒼生倚大臣。","還將徐孺子，处处待高人。"]', '诗', 'shi', '', NULL, '奉送韋中丞之晉赴湖南 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64528c95-a028-4b37-923d-698bed06ae4c', '送李功曹之荆州充鄭侍御判官重贈', '送李功曹之荆州充鄭侍御判官重贈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["曾聞宋玉宅，每欲到荆州。","此地生涯晚，遙悲水國秋。","孤城一柱觀，落日九江流。","使者雖光彩，青楓遠自愁。"]', '["曾闻宋玉宅，每欲到荆州。","此地生涯晚，遙悲水国秋。","孤城一柱观，落日九江流。","使者雖光彩，青楓远自愁。"]', '诗', 'shi', '', NULL, '送李功曹之荆州充鄭侍御判官重贈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fcabe4-cdf3-454d-8cbd-b2f78765e6c8', '送孟十二倉曹赴東京選', '送孟十二倉曹赴东京選', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君行別老親，此去苦家貧。","藻鏡留連客，江山顦顇人。","秋風楚竹冷，夜雪鞏梅春。","朝夕高堂念，應宜綵服新。"]', '["君行別老親，此去苦家貧。","藻镜留連客，江山顦顇人。","秋风楚竹冷，夜雪鞏梅春。","朝夕高堂念，應宜綵服新。"]', '诗', 'shi', '', NULL, '送孟十二倉曹赴東京選 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fc978a-c284-4c06-8f72-eb5041b21e56', '憑孟倉曹將書覓土婁舊莊', '憑孟倉曹將书覓土婁旧莊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["平居喪亂後，不到洛陽岑。","爲歷雲山問，無辭荆棘深。","北風黃葉下，南浦白頭吟。","十載江湖客，茫茫遲暮心。"]', '["平居喪亂後，不到洛陽岑。","爲歷云山问，無辞荆棘深。","北风黄葉下，南浦白头吟。","十載江湖客，茫茫遲暮心。"]', '诗', 'shi', '', NULL, '憑孟倉曹將書覓土婁舊莊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0901271a-f225-4a78-b7cf-bcd2fb3e0d7e', '別蘇徯（赴湖南幕）', '別蘇徯（赴湖南幕）', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故人有遊子，棄擲傍天隅。","他日憐才命，居然屈壯圖。","十年猶塌翼，絕倒爲驚吁。","消渴今如在，提攜媿老夫。","豈知臺閣舊，先拂鳳皇雛。","得實飜蒼竹，棲枝把翠梧。","北辰當宇宙，南岳據江湖。","國帶風塵色，兵張虎豹符。","數論封內事，揮發府中趨。","贈爾秦人策，莫鞭轅下駒。"]', '["故人有游子，棄擲傍天隅。","他日怜才命，居然屈壯圖。","十年猶塌翼，絕倒爲驚吁。","消渴今如在，提携媿老夫。","豈知台閣旧，先拂鳳皇雛。","得實飜蒼竹，棲枝把翠梧。","北辰當宇宙，南岳據江湖。","国带风塵色，兵張虎豹符。","數論封內事，揮發府中趨。","贈爾秦人策，莫鞭轅下駒。"]', '诗', 'shi', '', NULL, '別蘇徯（赴湖南幕） 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf1ba79-ab9c-4f01-ad7c-0f31bad80f4d', '存歿口號二首 一', '存歿口號二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["席謙不見近彈棊，畢曜仍傳舊小詩。","玉局他年無限笑，白楊今日幾人悲。"]', '["席謙不见近彈棊，畢曜仍傳旧小诗。","玉局他年無限笑，白楊今日幾人悲。"]', '诗', 'shi', '', NULL, '存歿口號二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e5870f-b85d-4297-96cb-8cff7d558433', '存歿口號二首 二', '存歿口號二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭公粉繪隨長夜，曹霸丹青已白頭。","天下何曾有山水，人間不解重驊騮。"]', '["鄭公粉繪隨长夜，曹霸丹青已白头。","天下何曾有山水，人间不解重驊騮。"]', '诗', 'shi', '', NULL, '存歿口號二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8055804-4c69-4e9d-b63c-d649c86a6b5f', '奉漢中王手札報韋侍御蕭尊師亡', '奉漢中王手札報韋侍御蕭尊師亡', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋日蕭韋逝，淮王報峽中。","少年疑柱史，多術怪仙公。","不但時人惜，祗應吾道窮。","一哀侵疾病，相識自兒童。","處處鄰家笛，飄飄客子蓬。","強吟懷舊賦，已作白頭翁。"]', '["秋日蕭韋逝，淮王報峽中。","少年疑柱史，多術怪仙公。","不但时人惜，祗應吾道窮。","一哀侵疾病，相識自兒童。","处处鄰家笛，飄飄客子蓬。","強吟懷旧賦，已作白头翁。"]', '诗', 'shi', '', NULL, '奉漢中王手札報韋侍御蕭尊師亡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d43a33-1a9f-4f37-b216-0b0e2d1de5fb', '哭王彭州掄', '哭王彭州掄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["執友驚淪沒，斯人已寂寥。","新文生沈謝，異骨降松喬。","北部初高選，東堂早見招。","蛟龍纏倚劒，鸞鳳夾吹簫。","歷職漢庭久，中年胡馬驕。","兵戈闇兩觀，寵辱事三朝。","蜀路江干窄，彭門地里遙。","解龜生碧草，諫獵阻清霄。","頃壯戎麾出，叨陪幕府要。","將軍臨氣候，猛士寒風飆。","井漏泉誰汲，烽疎火不燒。","前籌自多暇，隱几接終朝。","翠石俄雙表，寒松竟後凋。","贈詩焉敢墜，染翰欲無聊。","再哭經過罷，離魂去住銷。","之官方玉折，寄葬與萍漂。","曠望渥洼道，霏微河漢橋。","夫人先即世，令子各清標。","巫峽長雲雨，秦城近斗杓。","馮唐毛髮白，歸興日蕭蕭。"]', '["執友驚淪沒，斯人已寂寥。","新文生沈謝，異骨降松喬。","北部初高選，东堂早见招。","蛟龙纏倚劒，鸾鳳夾吹簫。","歷職漢庭久，中年胡马驕。","兵戈闇兩观，寵辱事三朝。","蜀路江干窄，彭门地里遙。","解龟生碧草，諫獵阻清霄。","頃壯戎麾出，叨陪幕府要。","將軍臨氣候，猛士寒风飆。","井漏泉誰汲，烽疎火不燒。","前籌自多暇，隐几接終朝。","翠石俄雙表，寒松竟後凋。","贈诗焉敢墜，染翰欲無聊。","再哭經過罷，離魂去住銷。","之官方玉折，寄葬與萍漂。","曠望渥洼道，霏微河漢橋。","夫人先即世，令子各清標。","巫峽长云雨，秦城近斗杓。","馮唐毛髮白，归兴日蕭蕭。"]', '诗', 'shi', '', NULL, '哭王彭州掄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1a05e7-b53a-431b-ad36-844319dd3a17', '見螢火', '见螢火', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巫山秋夜螢火飛，簾疎巧入坐人衣。","忽驚屋裏琴書冷，復亂檐邊星宿稀。","却繞井闌添箇箇，偶經花蘂弄輝輝。","蒼江白髮愁看汝，來歲如今歸未歸。"]', '["巫山秋夜螢火飞，簾疎巧入坐人衣。","忽驚屋裏琴书冷，复亂檐邊星宿稀。","却繞井闌添箇箇，偶經花蘂弄輝輝。","蒼江白髮愁看汝，来歲如今归未归。"]', '诗', 'shi', '', NULL, '見螢火 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98db730a-8bb5-4c96-81a9-b8c700e1b628', '吹笛', '吹笛', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吹笛秋山風月清，誰家巧作斷腸聲。","風飄律呂相和切，月傍關山幾處明。","胡騎中宵堪北走，武陵一曲想南征。","故園楊柳今搖落，何得愁中曲盡生。"]', '["吹笛秋山风月清，誰家巧作斷腸声。","风飄律呂相和切，月傍关山幾处明。","胡騎中宵堪北走，武陵一曲想南征。","故园楊柳今搖落，何得愁中曲尽生。"]', '诗', 'shi', '', NULL, '吹笛 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b75eb2-255e-4071-bf01-a5db4d409051', '孤雁', '孤雁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孤雁不飲啄，飛鳴聲念羣。","誰憐一片影，相失萬重雲。","望盡似猶見，哀多如更聞。","野鵶無意緒，鳴噪自紛紛。"]', '["孤雁不饮啄，飞鳴声念羣。","誰怜一片影，相失万重云。","望尽似猶见，哀多如更闻。","野鵶無意緒，鳴噪自紛紛。"]', '诗', 'shi', '', NULL, '孤雁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16986240-98d2-47da-a4a9-cf487c2c2f0e', '鷗', '鷗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江浦寒鷗戲，無他亦自饒。","却思飜玉羽，隨意點春苗。","雪暗還須浴，風生一任飄。","幾羣滄海上，清影日蕭蕭。"]', '["江浦寒鷗戲，無他亦自饒。","却思飜玉羽，隨意点春苗。","雪暗還須浴，风生一任飄。","幾羣滄海上，清影日蕭蕭。"]', '诗', 'shi', '', NULL, '鷗 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('677b004c-36ac-4456-b584-0b0764d34c79', '猨', '猨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["褭褭啼虛壁，蕭蕭挂冷枝。","艱難人不見，隱見爾如知。","慣習元從衆，全生或用奇。","前林騰每及，父子莫相離。"]', '["褭褭啼虛壁，蕭蕭挂冷枝。","艱难人不见，隐见爾如知。","慣習元從衆，全生或用奇。","前林腾每及，父子莫相離。"]', '诗', 'shi', '', NULL, '猨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a542e23a-2907-416f-8451-04cbd6779e25', '黃魚', '黄鱼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日見巴東峽，黃魚出浪新。","脂膏兼飼犬，長大不容身。","筒桶相沿久，風雷肯爲神。","泥沙卷涎沫，回首怪龍鱗。"]', '["日见巴东峽，黄鱼出浪新。","脂膏兼飼犬，长大不容身。","筒桶相沿久，风雷肯爲神。","泥沙卷涎沫，回首怪龙鱗。"]', '诗', 'shi', '', NULL, '黃魚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('998bd0c7-23f3-4c26-b669-9ea415363143', '白小', '白小', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白小羣分命，天然二寸魚。","細微霑水族，風俗當園蔬。","入肆銀花亂，傾箱雪片虛。","生成猶拾卵，盡取義何如。"]', '["白小羣分命，天然二寸鱼。","細微霑水族，风俗當园蔬。","入肆銀花亂，傾箱雪片虛。","生成猶拾卵，尽取義何如。"]', '诗', 'shi', '', NULL, '白小 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48906931-dcfc-4a6a-a2ea-764bf78f71b5', '麂', '麂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["永與清溪別，蒙將玉饌俱。","無才逐仙隱，不敢恨庖廚。","亂世輕全物，微聲及禍樞。","衣冠兼盜賊，饕餮用斯須。"]', '["永與清溪別，蒙將玉饌俱。","無才逐仙隐，不敢恨庖廚。","亂世轻全物，微声及禍樞。","衣冠兼盜賊，饕餮用斯須。"]', '诗', 'shi', '', NULL, '麂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67d9e71-047a-4304-8b41-b7abb86cbbdb', '雞', '雞', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["紀德名標五，初鳴度必三。","殊方聽有異，失次曉無慙。","問俗人情似，充庖爾輩堪。","氣交亭育際，巫峽漏司南。"]', '["紀德名標五，初鳴度必三。","殊方听有異，失次晓無慙。","问俗人情似，充庖爾輩堪。","氣交亭育際，巫峽漏司南。"]', '诗', 'shi', '', NULL, '雞 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8584c5a1-b204-481e-b6fd-3eb4b70ec209', '玉腕騮', '玉腕騮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞說荆南馬，尚書玉腕騮。","頓驂飄赤汗，踞蹐顧長楸。","胡虜三年入，乾坤一戰收。","舉鞭如有問，欲伴習池遊。"]', '["闻说荆南马，尚书玉腕騮。","頓驂飄赤汗，踞蹐顧长楸。","胡虜三年入，乾坤一戰收。","舉鞭如有问，欲伴習池游。"]', '诗', 'shi', '', NULL, '玉腕騮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e359ecda-4561-43e9-aaa0-4a5ab5d1f3fd', '見王監兵馬使說近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飛避暖勁翮思秋之甚眇不可見請余賦詩 一', '见王監兵马使说近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飞避暖勁翮思秋之甚眇不可见請余賦诗 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雪飛玉立盡清秋，不惜奇毛恣遠遊。","在野只教心力破，千人何事網羅求。","一生自獵知無敵，百中爭能恥下韝。","鵬礙九天須却避，兔藏三穴莫深憂。"]', '["雪飞玉立尽清秋，不惜奇毛恣远游。","在野只教心力破，千人何事網羅求。","一生自獵知無敵，百中爭能恥下韝。","鵬礙九天須却避，兔藏三穴莫深憂。"]', '诗', 'shi', '', NULL, '見王監兵馬使說近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飛避暖勁翮思秋之甚眇不可見請余賦詩 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e81bbb-8a37-4a43-882c-884d34a754e9', '見王監兵馬使說近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飛避暖勁翮思秋之甚眇不可見請余賦詩 二', '见王監兵马使说近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飞避暖勁翮思秋之甚眇不可见請余賦诗 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黑鷹不省人間有，度海疑從北極來。","正翮摶風超紫塞，立冬幾夜宿陽臺。","虞羅自各虛施巧，春雁同歸必見猜。","萬里寒空祗一日，金眸玉爪不凡才。"]', '["黑鷹不省人间有，度海疑從北極来。","正翮摶风超紫塞，立冬幾夜宿陽台。","虞羅自各虛施巧，春雁同归必见猜。","万里寒空祗一日，金眸玉爪不凡才。"]', '诗', 'shi', '', NULL, '見王監兵馬使說近山有白黑二鷹羅者久取竟未能得王以爲毛骨有異他鷹恐臘後春生鶱飛避暖勁翮思秋之甚眇不可見請余賦詩 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4dc63c-db19-48ac-84e5-480042f3df86', '太歲日', '太歲日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚岸行將老，巫山坐復春。","病多猶是客，謀拙竟何人。","閶闔開黃道，衣冠拜紫宸。","榮光懸日月，賜與出金銀。","愁寂鴛行斷，參差虎穴鄰。","西江元下蜀，北斗故臨秦。","散地逾高枕，生涯脫要津。","天邊梅柳樹，相見幾回新。"]', '["楚岸行將老，巫山坐复春。","病多猶是客，謀拙竟何人。","閶闔开黄道，衣冠拜紫宸。","榮光懸日月，賜與出金銀。","愁寂鴛行斷，參差虎穴鄰。","西江元下蜀，北斗故臨秦。","散地逾高枕，生涯脫要津。","天邊梅柳樹，相见幾回新。"]', '诗', 'shi', '', NULL, '太歲日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471d5abe-d0cf-4dd2-a94b-ab5552be07d9', '元日示宗武', '元日示宗武', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝啼吾手戰，吾笑汝身長。","處處逢正月，迢迢滯遠方。","飄零還柏酒，衰病只藜牀。","訓喻青衿子，名慙白首郎。","賦詩猶落筆，獻壽更稱觴。","不見江東弟，高歌淚數行。"]', '["汝啼吾手戰，吾笑汝身长。","处处逢正月，迢迢滯远方。","飄零還柏酒，衰病只藜牀。","訓喻青衿子，名慙白首郎。","賦诗猶落笔，獻壽更稱觴。","不见江东弟，高歌泪數行。"]', '诗', 'shi', '', NULL, '元日示宗武 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49255a86-1217-48f7-b480-0f562a4dcf91', '遠懷舍弟穎觀等', '远懷舍弟穎观等', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["陽翟空知處，荆南近得書。","積年仍遠別，多難不安居。","江漢春風起，冰霜昨夜除。","雲天猶錯莫，花萼尚蕭疎。","對酒都疑夢，吟詩正憶渠。","舊時元日會，鄉黨羨吾廬。"]', '["陽翟空知处，荆南近得书。","積年仍远別，多难不安居。","江漢春风起，冰霜昨夜除。","云天猶錯莫，花萼尚蕭疎。","对酒都疑梦，吟诗正憶渠。","旧时元日會，乡黨羨吾廬。"]', '诗', 'shi', '', NULL, '遠懷舍弟穎觀等 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48daf1c-17c9-427b-9614-b54de152e3f9', '續得觀書迎就當陽居止正月中旬定出三峽', '續得观书迎就當陽居止正月中旬定出三峽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自汝到荆府，書來數喚吾。","頌椒添諷詠，禁火卜歡娛。","舟楫因人動，形骸用杖扶。","天旋夔子國，春近岳陽湖。","發日排南喜，傷神散北吁。","飛鳴還接翅，行序密銜蘆。","俗薄江山好，時危草木蘇。","馮唐雖晚達，終覬在皇都。"]', '["自汝到荆府，书来數喚吾。","頌椒添諷詠，禁火卜歡娛。","舟楫因人动，形骸用杖扶。","天旋夔子国，春近岳陽湖。","發日排南喜，傷神散北吁。","飞鳴還接翅，行序密銜蘆。","俗薄江山好，时危草木蘇。","馮唐雖晚達，終覬在皇都。"]', '诗', 'shi', '', NULL, '續得觀書迎就當陽居止正月中旬定出三峽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ddc488-66be-4acd-b680-049fa13875c5', '將別巫峽贈南卿兄瀼西果園四十畝', '將別巫峽贈南卿兄瀼西果园四十畝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苔竹素所好，萍蓬無定居。","遠遊長兒子，幾地別林廬。","雜蘂紅相對，他時錦不如。","具舟將出峽，巡圃念攜鋤。","正月喧鶯末，茲辰放鷁初。","雪籬梅可折，風榭柳微舒。","託贈卿家有，因歌野興疎。","殘生逗江漢，何處狎樵漁。"]', '["苔竹素所好，萍蓬無定居。","远游长兒子，幾地別林廬。","杂蘂紅相对，他时錦不如。","具舟將出峽，巡圃念携鋤。","正月喧鶯末，茲辰放鷁初。","雪籬梅可折，风榭柳微舒。","託贈卿家有，因歌野兴疎。","殘生逗江漢，何处狎樵漁。"]', '诗', 'shi', '', NULL, '將別巫峽贈南卿兄瀼西果園四十畝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60f3c484-4e4f-4612-9f93-e753c7c67c02', '送大理封主簿五郎親事不合却赴通州主簿前閬州賢子余與主簿平章鄭氏女子垂欲納鄭氏伯父京書至女子已前許他族親事遂停', '送大理封主簿五郎親事不合却赴通州主簿前閬州賢子余與主簿平章鄭氏女子垂欲納鄭氏伯父京书至女子已前許他族親事遂停', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["禁臠去東牀，趨庭赴北堂。","風波空遠涉，琴瑟幾虛張。","渥水出騏驥，崑山生鳳皇。","兩家誠款款，中道許蒼蒼。","頗謂秦晉匹，從來王謝郎。","青春動才調，白首缺輝光。","玉潤終孤立，珠明得闇藏。","餘寒折花卉，恨別滿江鄉。"]', '["禁臠去东牀，趨庭赴北堂。","风波空远涉，琴瑟幾虛張。","渥水出騏驥，崑山生鳳皇。","兩家誠款款，中道許蒼蒼。","頗謂秦晉匹，從来王謝郎。","青春动才調，白首缺輝光。","玉潤終孤立，珠明得闇藏。","餘寒折花卉，恨別满江乡。"]', '诗', 'shi', '', NULL, '送大理封主簿五郎親事不合却赴通州主簿前閬州賢子余與主簿平章鄭氏女子垂欲納鄭氏伯父京書至女子已前許他族親事遂停 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f45104c8-145d-4f09-ac5d-1b9ac85dad65', '人日兩篇 一', '人日兩篇 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["元日到人日，未有不陰時。","冰雪鶯難至，春寒花較遲。","雲隨白水落，風振紫山悲。","蓬鬢稀疎久，無勞比素絲。"]', '["元日到人日，未有不陰时。","冰雪鶯难至，春寒花較遲。","云隨白水落，风振紫山悲。","蓬鬢稀疎久，無勞比素絲。"]', '诗', 'shi', '', NULL, '人日兩篇 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe5a657-b087-4fe3-b3f0-d4d5d97da755', '人日兩篇 二', '人日兩篇 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此日此時人共得，一談一笑俗相看。","尊前柏葉休隨酒，勝裏金花巧耐寒。","佩劒衝星聊暫拔，匣琴流水自須彈。","早春重引江湖興，直道無憂行路難。"]', '["此日此时人共得，一談一笑俗相看。","尊前柏葉休隨酒，勝裏金花巧耐寒。","佩劒衝星聊暫拔，匣琴流水自須彈。","早春重引江湖兴，直道無憂行路难。"]', '诗', 'shi', '', NULL, '人日兩篇 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a4d4f1-b9bb-42c4-8201-8b84b88c5531', '江梅', '江梅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["梅蘂臘前破，梅花年後多。","絕知春意好，最奈客愁何。","雪樹元同色，江風亦自波。","故園不可見，巫岫鬱嵯峨。"]', '["梅蘂臘前破，梅花年後多。","絕知春意好，最奈客愁何。","雪樹元同色，江风亦自波。","故园不可见，巫岫鬱嵯峨。"]', '诗', 'shi', '', NULL, '江梅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b47ba92-18b5-4dc4-8dc6-fd74a117c242', '庭草', '庭草', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚草經寒碧，逢春入眼濃。","舊低收葉舉，新掩卷牙重。","步履宜輕過，開筵得屢供。","看花隨節序，不敢強爲容。"]', '["楚草經寒碧，逢春入眼濃。","旧低收葉舉，新掩卷牙重。","步履宜轻過，开筵得屢供。","看花隨節序，不敢強爲容。"]', '诗', 'shi', '', NULL, '庭草 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef36b0a2-6327-47a2-b777-ccf669af3ebb', '大曆三年春白帝城放船出瞿塘峽久居夔府將適江陵漂泊有詩凡四十韻', '大曆三年春白帝城放船出瞿塘峽久居夔府將適江陵漂泊有诗凡四十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老向巴人裏，今辭楚塞隅。","入舟飜不樂，解纜獨長吁。","窄轉深啼狖，虛隨亂浴鳧。","石苔凌几杖，空翠撲肌膚。","疊壁排霜劒，奔泉濺水珠。","杳冥藤上下，濃澹樹榮枯。","神女峰娟妙，昭君宅有無。","曲留明怨惜，夢盡失歡娛。","擺闔盤渦沸，欹斜激浪輸。","風雷纏地脈，冰雪耀天衢。","鹿角真走險，狼頭如跋胡。","惡灘寧變色，高臥負微軀。","書史全傾撓，裝囊半壓濡。","生涯臨臬兀，死地脫斯須。","不有平川決，焉知衆壑趨。","乾坤霾漲海，雨露洗春蕪。","歐鳥牽絲颺，驪龍濯錦紆。","落霞沈綠綺，殘月壞金樞。","泥筍苞初荻，沙茸出小蒲。","雁兒爭水馬，燕子逐檣烏。","絕島容煙霧，環洲納曉晡。","前聞辨陶牧，轉眄拂宜都。","縣郭南畿好，津亭北望孤。","勞心依憩息，朗詠劃昭蘇。","意遣樂還笑，衰迷賢與愚。","飄蕭將素髮，汩沒聽洪鑪。","丘壑曾忘返，文章敢自誣。","此生遭聖代，誰分哭窮途。","臥疾淹爲客，蒙恩早厠儒。","廷爭酬造化，樸直乞江湖。","灧澦險相迫，滄浪深可逾。","浮名尋已已，嬾計却區區。","喜近天皇寺，先披古畫圖。","應經帝子渚，同泣舜蒼梧。","朝士兼戎服，君王按湛盧。","旄頭初俶擾，鶉首麗泥塗。","甲卒身雖貴，書生道固殊。","出塵皆野鶴，歷塊匪轅駒。","伊呂終難降，韓彭不易呼。","五雲高太甲，六月曠摶扶。","回首黎元病，爭權將帥誅。","山林託疲苶，未必免崎嶇。"]', '["老向巴人裏，今辞楚塞隅。","入舟飜不乐，解纜独长吁。","窄轉深啼狖，虛隨亂浴鳧。","石苔凌几杖，空翠撲肌膚。","叠壁排霜劒，奔泉濺水珠。","杳冥藤上下，濃澹樹榮枯。","神女峰娟妙，昭君宅有無。","曲留明怨惜，梦尽失歡娛。","擺闔盤渦沸，欹斜激浪輸。","风雷纏地脈，冰雪耀天衢。","鹿角真走險，狼头如跋胡。","惡灘寧变色，高臥負微軀。","书史全傾撓，裝囊半壓濡。","生涯臨臬兀，死地脫斯須。","不有平川決，焉知衆壑趨。","乾坤霾漲海，雨露洗春蕪。","歐鸟牽絲颺，驪龙濯錦紆。","落霞沈綠綺，殘月壞金樞。","泥筍苞初荻，沙茸出小蒲。","雁兒爭水马，燕子逐檣烏。","絕島容煙霧，环洲納晓晡。","前闻辨陶牧，轉眄拂宜都。","縣郭南畿好，津亭北望孤。","勞心依憩息，朗詠劃昭蘇。","意遣乐還笑，衰迷賢與愚。","飄蕭將素髮，汩沒听洪鑪。","丘壑曾忘返，文章敢自誣。","此生遭聖代，誰分哭窮途。","臥疾淹爲客，蒙恩早厠儒。","廷爭酬造化，樸直乞江湖。","灧澦險相迫，滄浪深可逾。","浮名尋已已，嬾計却區區。","喜近天皇寺，先披古畫圖。","應經帝子渚，同泣舜蒼梧。","朝士兼戎服，君王按湛盧。","旄头初俶擾，鶉首丽泥塗。","甲卒身雖貴，书生道固殊。","出塵皆野鹤，歷塊匪轅駒。","伊呂終难降，韓彭不易呼。","五云高太甲，六月曠摶扶。","回首黎元病，爭權將帥誅。","山林託疲苶，未必免崎嶇。"]', '诗', 'shi', '', NULL, '大曆三年春白帝城放船出瞿塘峽久居夔府將適江陵漂泊有詩凡四十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d30278-2a20-4eac-a99e-4c31c476146a', '巫山縣汾州唐使君十八弟宴別兼諸公攜酒樂相送率題小詩留於屋壁，', '巫山縣汾州唐使君十八弟宴別兼諸公携酒乐相送率題小诗留於屋壁，', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["臥病巴東久，今年強作歸。","故人猶遠謫，茲日倍多違。","接宴身兼杖，聽歌淚滿衣。","諸公不相棄，擁別惜光輝。"]', '["臥病巴东久，今年強作归。","故人猶远謫，茲日倍多違。","接宴身兼杖，听歌泪满衣。","諸公不相棄，擁別惜光輝。"]', '诗', 'shi', '', NULL, '巫山縣汾州唐使君十八弟宴別兼諸公攜酒樂相送率題小詩留於屋壁， 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee06ff18-c97c-41bf-8839-3e628f84df56', '春夜峽州田侍御長史津亭留宴', '春夜峽州田侍御长史津亭留宴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北斗三更席，西江萬里船。","杖藜登水榭，揮翰宿春天。","白髮煩多酒，明星惜此筵。","始知雲雨峽，忽盡下牢邊。"]', '["北斗三更席，西江万里船。","杖藜登水榭，揮翰宿春天。","白髮煩多酒，明星惜此筵。","始知云雨峽，忽尽下牢邊。"]', '诗', 'shi', '', NULL, '春夜峽州田侍御長史津亭留宴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83b6f8c7-9df6-4a6d-975b-15b582055495', '泊松滋江亭', '泊松滋江亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["沙帽隨鷗鳥，扁舟繫此亭。","江湖深更白，松竹遠微青。","一柱全應近，高唐莫再經。","今宵南極外，甘作老人星。"]', '["沙帽隨鷗鸟，扁舟繫此亭。","江湖深更白，松竹远微青。","一柱全應近，高唐莫再經。","今宵南極外，甘作老人星。"]', '诗', 'shi', '', NULL, '泊松滋江亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60416453-6d7f-42e7-932c-493495a224e1', '行次古城店泛江作不揆鄙拙奉呈江陵幕府諸公', '行次古城店泛江作不揆鄙拙奉呈江陵幕府諸公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老年常道路，遲日復山川。","白屋花開裏，孤城麥秀邊。","濟江元自闊，下水不勞牽。","風蝶勤依漿，春鷗嬾避船。","王門高德業，幕府盛才賢。","行色兼多病，蒼茫泛愛前。"]', '["老年常道路，遲日复山川。","白屋花开裏，孤城麦秀邊。","濟江元自闊，下水不勞牽。","风蝶勤依漿，春鷗嬾避船。","王门高德業，幕府盛才賢。","行色兼多病，蒼茫泛愛前。"]', '诗', 'shi', '', NULL, '行次古城店泛江作不揆鄙拙奉呈江陵幕府諸公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e326a87d-30e8-4981-8278-d38ecaf8b213', '乘雨入行軍六弟宅', '乘雨入行軍六弟宅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["曙角凌雲罷，春城帶雨長。","水花分塹弱，巢燕得泥忙。","令弟雄軍佐，凡才污省郎。","萍漂忍流涕，衰颯近中堂。"]', '["曙角凌云罷，春城带雨长。","水花分塹弱，巢燕得泥忙。","令弟雄軍佐，凡才污省郎。","萍漂忍流涕，衰颯近中堂。"]', '诗', 'shi', '', NULL, '乘雨入行軍六弟宅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69df3f32-fc62-40b8-9cd2-1f98cc3e3076', '宴胡侍御書堂', '宴胡侍御书堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江湖春欲暮，牆宇日猶微。","闇闇春籍滿，輕輕花絮飛。","翰林名有素，墨客興無違。","今夜文星動，吾儕醉不歸。"]', '["江湖春欲暮，牆宇日猶微。","闇闇春籍满，轻轻花絮飞。","翰林名有素，墨客兴無違。","今夜文星动，吾儕醉不归。"]', '诗', 'shi', '', NULL, '宴胡侍御書堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea32b290-7412-4a01-b660-42821f8730d0', '書堂飲既夜復邀李尚書下馬月下賦絕句', '书堂饮既夜复邀李尚书下马月下賦絕句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["湖水林風相與清，殘尊下馬復同傾。","久判野鶴如霜鬢，遮莫鄰雞下五更。"]', '["湖水林风相與清，殘尊下马复同傾。","久判野鹤如霜鬢，遮莫鄰雞下五更。"]', '诗', 'shi', '', NULL, '書堂飲既夜復邀李尚書下馬月下賦絕句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2161c1d-c64e-46dd-bf17-9e3bb5a9be47', '上巳日徐司錄林園宴集', '上巳日徐司錄林园宴集', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鬢毛垂領白，花蘂亞枝紅。","欹倒衰年廢，招尋令節同。","薄衣臨積水，吹面受和風。","有喜留攀桂，無勞問轉蓬。"]', '["鬢毛垂領白，花蘂亞枝紅。","欹倒衰年廢，招尋令節同。","薄衣臨積水，吹面受和风。","有喜留攀桂，無勞问轉蓬。"]', '诗', 'shi', '', NULL, '上巳日徐司錄林園宴集 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17454a63-af1d-4f71-97c9-55eba184d068', '奉送蘇州李二十五長史丈之任', '奉送蘇州李二十五长史丈之任', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["星坼台衡地，曾爲人所憐。","公侯終必復，經術昔相傳。","食德見從事，克家何妙年。","一毛生鳳穴，三尺獻龍泉。","赤壁浮春暮，姑蘇落海邊。","客間頭最白，惆悵此離筵。"]', '["星坼台衡地，曾爲人所怜。","公侯終必复，經術昔相傳。","食德见從事，克家何妙年。","一毛生鳳穴，三尺獻龙泉。","赤壁浮春暮，姑蘇落海邊。","客间头最白，惆悵此離筵。"]', '诗', 'shi', '', NULL, '奉送蘇州李二十五長史丈之任 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd0c2d9-0382-4b51-a19f-8361be58a31d', '暮春江陵送馬大卿公恩命追赴闕下', '暮春江陵送马大卿公恩命追赴闕下', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自古求忠孝，名家信有之。","吾賢富才術，此道未磷緇。","玉府標孤映，霜蹄去不疑。","激揚音韻徹，籍甚衆多推。","潘陸應同調，孫吳亦異時。","北辰徵事業，南紀赴恩私。","卿月升金掌，王春度玉墀。","熏風行應律，湛露即歌詩。","天意高難問，人情老易悲。","尊前江漢闊，後會且深期。"]', '["自古求忠孝，名家信有之。","吾賢富才術，此道未磷緇。","玉府標孤映，霜蹄去不疑。","激揚音韻徹，籍甚衆多推。","潘陸應同調，孫吳亦異时。","北辰徵事業，南紀赴恩私。","卿月升金掌，王春度玉墀。","熏风行應律，湛露即歌诗。","天意高难问，人情老易悲。","尊前江漢闊，後會且深期。"]', '诗', 'shi', '', NULL, '暮春江陵送馬大卿公恩命追赴闕下 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac88cc63-7c2c-472f-b65e-3c357334b0fd', '暮春陪李尚書李中丞過鄭監湖亭泛舟', '暮春陪李尚书李中丞過鄭監湖亭泛舟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["海內文章伯，湖邊意緒多。","玉尊移晚興，桂楫帶酣歌。","春日繁魚鳥，江天足芰荷。","鄭莊賓客地，衰白遠來過。"]', '["海內文章伯，湖邊意緒多。","玉尊移晚兴，桂楫带酣歌。","春日繁鱼鸟，江天足芰荷。","鄭莊賓客地，衰白远来過。"]', '诗', 'shi', '', NULL, '暮春陪李尚書李中丞過鄭監湖亭泛舟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921df201-3eb0-44bb-b6b8-2d001fa71074', '奉送蜀州柏二別駕將中丞命赴江陵起居衛尚書太夫人因示從弟行軍司馬佐', '奉送蜀州柏二別駕將中丞命赴江陵起居衛尚书太夫人因示從弟行軍司马佐', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中丞問俗畫熊頻，愛弟傳書彩鷁新。","遷轉五州防禦使，起居八座太夫人。","楚宮臘送荆門水，白帝雲偷碧海春。","報與惠連詩不惜，知吾斑鬢總如銀。"]', '["中丞问俗畫熊頻，愛弟傳书彩鷁新。","遷轉五州防禦使，起居八座太夫人。","楚宮臘送荆门水，白帝云偷碧海春。","報與惠連诗不惜，知吾斑鬢總如銀。"]', '诗', 'shi', '', NULL, '奉送蜀州柏二別駕將中丞命赴江陵起居衛尚書太夫人因示從弟行軍司馬佐 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0c8118-d665-4dc1-be2b-901ae13395ed', '夏日楊長寧宅送崔侍御常正字入京', '夏日楊长寧宅送崔侍御常正字入京', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["醉酒揚雄宅，升堂子賤琴。","不堪垂老鬢，還對欲分襟。","天地西江遠，星辰北斗深。","烏臺俯麟閣，長夏白頭吟。"]', '["醉酒揚雄宅，升堂子賤琴。","不堪垂老鬢，還对欲分襟。","天地西江远，星辰北斗深。","烏台俯麟閣，长夏白头吟。"]', '诗', 'shi', '', NULL, '夏日楊長寧宅送崔侍御常正字入京 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a83aed-b9e5-42f9-bd70-ac220655820d', '和江陵宋大少府暮春雨後同諸公及舍弟宴書齋', '和江陵宋大少府暮春雨後同諸公及舍弟宴书斋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["渥洼汗血種，天上麒麟兒。","才士得神秀，書齋聞爾爲。","棣華晴雨好，綵服暮春宜。","朋酒日歡會，老夫今始知。"]', '["渥洼汗血種，天上麒麟兒。","才士得神秀，书斋闻爾爲。","棣华晴雨好，綵服暮春宜。","朋酒日歡會，老夫今始知。"]', '诗', 'shi', '', NULL, '和江陵宋大少府暮春雨後同諸公及舍弟宴書齋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e9f169-b4de-493a-b6f1-9b63d1f8f32a', '宇文晁尚書之甥崔彧司業之孫尚書之子重泛鄭監前湖', '宇文晁尚书之甥崔彧司業之孫尚书之子重泛鄭監前湖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["郊扉俗遠長幽寂，野水春來更接連。","錦席淹留還出浦，葛巾欹側未迴船。","尊當霞綺輕初散，櫂拂荷珠碎却圓。","不但習池歸酩酊，君看鄭谷去夤緣。"]', '["郊扉俗远长幽寂，野水春来更接連。","錦席淹留還出浦，葛巾欹側未迴船。","尊當霞綺轻初散，櫂拂荷珠碎却圓。","不但習池归酩酊，君看鄭谷去夤緣。"]', '诗', 'shi', '', NULL, '宇文晁尚書之甥崔彧司業之孫尚書之子重泛鄭監前湖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b443f8f6-d94d-4399-bbe4-6816d1ae0126', '多病執熱奉懷李尚書', '多病執熱奉懷李尚书', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衰年正苦病侵凌，首夏何須氣鬱蒸。","大水淼茫炎海接，奇峰硉兀火雲升。","思霑道暍黃梅雨，敢望宮恩玉井冰。","不是尚書期不顧山陰野雪興難乘。"]', '["衰年正苦病侵凌，首夏何須氣鬱蒸。","大水淼茫炎海接，奇峰硉兀火云升。","思霑道暍黄梅雨，敢望宮恩玉井冰。","不是尚书期不顧山陰野雪兴难乘。"]', '诗', 'shi', '', NULL, '多病執熱奉懷李尚書 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47177306-ac64-4cba-a655-5e4fdf44bee6', '水宿遣興奉呈羣公', '水宿遣兴奉呈羣公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["魯鈍仍多病，逢迎遠復迷。","耳聾須畫字，髮短不勝蓖。","澤國雖勤雨，炎天竟淺泥。","小江還積浪，弱纜且長堤。","歸路非關北，行舟却向西。","暮年漂泊恨，今夕亂離啼。","童稚頻書札，盤餐詎糝藜。","我行何到此，物理直難齊。","高枕飜星月，嚴城疊鼓鞞。","風號聞虎豹，水宿伴鳧鷖。","異縣驚虛往，同人惜解攜。","蹉跎長泛鷁，展轉屢鳴雞。","嶷嶷瑚璉器，陰陰桃李蹊。","餘波期救涸，費日苦輕齎。","支策門闌邃，肩輿羽翮低。","自傷甘賤役，誰愍強幽棲。","巨海能無釣，浮雲亦有梯。","勳庸思樹立，語默可端倪。","贈粟囷應指，登橋柱必題。","丹心老未折，時訪武陵溪。"]', '["魯鈍仍多病，逢迎远复迷。","耳聾須畫字，髮短不勝蓖。","澤国雖勤雨，炎天竟淺泥。","小江還積浪，弱纜且长堤。","归路非关北，行舟却向西。","暮年漂泊恨，今夕亂離啼。","童稚頻书札，盤餐詎糝藜。","我行何到此，物理直难齊。","高枕飜星月，嚴城叠鼓鞞。","风號闻虎豹，水宿伴鳧鷖。","異縣驚虛往，同人惜解携。","蹉跎长泛鷁，展轉屢鳴雞。","嶷嶷瑚璉器，陰陰桃李蹊。","餘波期救涸，費日苦轻齎。","支策门闌邃，肩輿羽翮低。","自傷甘賤役，誰愍強幽棲。","巨海能無釣，浮云亦有梯。","勳庸思樹立，語默可端倪。","贈粟囷應指，登橋柱必題。","丹心老未折，时訪武陵溪。"]', '诗', 'shi', '', NULL, '水宿遣興奉呈羣公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c08a55b-3506-4770-a3fb-66b0d021835e', '奉賀陽城郡王太夫人恩命加鄧國太夫人', '奉賀陽城郡王太夫人恩命加鄧国太夫人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衛幕銜恩重，潘輿送喜頻。","濟時瞻上將，錫號戴慈親。","富貴當如此，尊榮邁等倫。","郡依封土舊，國與大名新。","紫誥鸞迴紙，清朝燕賀人。","遠傳冬筍味，更覺綵衣春。","奕葉班姑史，芬芳孟母鄰。","義方兼有訓，詞翰兩如神。","委曲承顏體，騫飛報主身。","可憐忠與孝，雙美畫騏麟。"]', '["衛幕銜恩重，潘輿送喜頻。","濟时瞻上將，錫號戴慈親。","富貴當如此，尊榮邁等倫。","郡依封土旧，国與大名新。","紫誥鸾迴紙，清朝燕賀人。","远傳冬筍味，更覺綵衣春。","奕葉班姑史，芬芳孟母鄰。","義方兼有訓，词翰兩如神。","委曲承顏體，騫飞報主身。","可怜忠與孝，雙美畫騏麟。"]', '诗', 'shi', '', NULL, '奉賀陽城郡王太夫人恩命加鄧國太夫人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383ea645-4277-41c8-af4e-8d03d1497a87', '江陵望幸', '江陵望幸', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雄都元壯麗，望幸歘威神。","地利西通蜀，天文北照秦。","風煙含越鳥，舟楫控吳人。","未枉周王駕，終期漢武巡。","甲兵分聖旨，居守付宗臣。","早發雲臺杖，恩波起涸鱗。"]', '["雄都元壯丽，望幸歘威神。","地利西通蜀，天文北照秦。","风煙含越鸟，舟楫控吳人。","未枉周王駕，終期漢武巡。","甲兵分聖旨，居守付宗臣。","早發云台杖，恩波起涸鱗。"]', '诗', 'shi', '', NULL, '江陵望幸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683085c0-248c-4545-998b-a04be7b8fd48', '江邊星月二首 一', '江邊星月二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驟雨清秋夜，金波耿玉繩。","天河元自白，江浦向來澄。","映物連珠斷，緣空一鏡升。","餘光隱更漏，況乃露華凝。"]', '["驟雨清秋夜，金波耿玉繩。","天河元自白，江浦向来澄。","映物連珠斷，緣空一镜升。","餘光隐更漏，況乃露华凝。"]', '诗', 'shi', '', NULL, '江邊星月二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1130a58d-d738-46e6-8052-1252a540540d', '江邊星月二首 二', '江邊星月二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江月辭風纜，江星別霧船。","雞鳴還曙色，鷺浴自清川。","歷歷竟誰種，悠悠何處圓。","客愁殊未已，他夕始相鮮。"]', '["江月辞风纜，江星別霧船。","雞鳴還曙色，鷺浴自清川。","歷歷竟誰種，悠悠何处圓。","客愁殊未已，他夕始相鲜。"]', '诗', 'shi', '', NULL, '江邊星月二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac2ae13-b8bc-45ad-9657-e34cbc3906c5', '舟月對驛近寺', '舟月对驛近寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["更深不假燭，月朗自明船。","金剎清楓外，朱樓白水邊。","城烏啼眇眇，野鷺宿娟娟。","皓首江湖客，鉤簾獨未眠。"]', '["更深不假燭，月朗自明船。","金剎清楓外，朱楼白水邊。","城烏啼眇眇，野鷺宿娟娟。","皓首江湖客，鉤簾独未眠。"]', '诗', 'shi', '', NULL, '舟月對驛近寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9929c7fe-f4ad-449c-85f4-a0aebd0f4de8', '舟中', '舟中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風餐江柳下，雨臥驛樓邊。","結纜排魚網，連檣竝米船。","今朝雲細薄，昨夜月清圓。","飄泊南庭老，祗應學水仙。"]', '["风餐江柳下，雨臥驛楼邊。","結纜排鱼網，連檣竝米船。","今朝云細薄，昨夜月清圓。","飄泊南庭老，祗應学水仙。"]', '诗', 'shi', '', NULL, '舟中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2fc78d-b575-49ac-abbc-e548d9fe1457', '遣悶', '遣悶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["地闊平沙岸，舟虛小洞房。","使塵來驛道，城日避烏檣。","暑雨留蒸濕，江風借夕涼。","行雲星隱見，疊浪月光芒。","螢鑒緣帷徹，蛛絲罥鬢長。","哀箏猶凭几，鳴笛竟霑裳。","倚著如秦贅，過逢類楚狂。","氣衝看劒匣，穎脫撫錐囊。","妖孽關東臭，兵戈隴右創。","時清疑武略，世亂跼文場。","餘力浮於海，端憂問彼蒼。","百年從萬事，故國耿難忘。"]', '["地闊平沙岸，舟虛小洞房。","使塵来驛道，城日避烏檣。","暑雨留蒸濕，江风借夕涼。","行云星隐见，叠浪月光芒。","螢鑒緣帷徹，蛛絲罥鬢长。","哀箏猶凭几，鳴笛竟霑裳。","倚著如秦贅，過逢類楚狂。","氣衝看劒匣，穎脫撫錐囊。","妖孽关东臭，兵戈隴右創。","时清疑武略，世亂跼文場。","餘力浮於海，端憂问彼蒼。","百年從万事，故国耿难忘。"]', '诗', 'shi', '', NULL, '遣悶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db42110-bda6-490a-b3e0-61a5dfffad79', '江陵節度陽城郡王新樓成王請嚴侍御判官賦七字句同作', '江陵節度陽城郡王新楼成王請嚴侍御判官賦七字句同作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樓上炎天冰雪生，高飛燕雀賀新成。","碧窗宿霧濛濛濕，朱栱浮雲細細輕。","杖鉞褰帷瞻具美，投壺散帙有餘清。","自公多暇延參佐，江漢風流萬古情。"]', '["楼上炎天冰雪生，高飞燕雀賀新成。","碧窗宿霧濛濛濕，朱栱浮云細細轻。","杖鉞褰帷瞻具美，投壺散帙有餘清。","自公多暇延參佐，江漢风流万古情。"]', '诗', 'shi', '', NULL, '江陵節度陽城郡王新樓成王請嚴侍御判官賦七字句同作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee24af9-5477-4a56-b579-4ccdf8150bd5', '又作此奉衛公', '又作此奉衛公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西北樓成雄楚都，遠開山岳散江湖。","二儀清濁還高下，三伏炎蒸定有無。","推轂幾年唯鎮靜，曳裾終日盛文儒。","白頭授簡焉能賦，媿似相如爲大夫。"]', '["西北楼成雄楚都，远开山岳散江湖。","二儀清濁還高下，三伏炎蒸定有無。","推轂幾年唯鎮静，曳裾終日盛文儒。","白头授簡焉能賦，媿似相如爲大夫。"]', '诗', 'shi', '', NULL, '又作此奉衛公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72dc154a-f628-4c7c-9a53-71891cdcdba4', '舟出江陵南浦奉寄鄭少尹', '舟出江陵南浦奉寄鄭少尹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["更欲投何處，飄然去此都。","形骸元土木，舟檝復江湖。","社稷纏妖氣，干戈送老儒。","百年同棄物，萬國盡窮途。","雨洗平沙靜，天銜闊岸紆。","鳴螿隨泛梗，別燕赴秋菰。","棲託難高臥，飢寒迫向隅。","寂寥相喣沫，浩蕩報恩珠。","溟漲鯨波動，衡陽雁影徂。","南征問懸榻，東逝想乘桴。","濫竊商歌聽，時憂卞泣誅。","經過憶鄭驛，斟酌旅情孤。"]', '["更欲投何处，飄然去此都。","形骸元土木，舟檝复江湖。","社稷纏妖氣，干戈送老儒。","百年同棄物，万国尽窮途。","雨洗平沙静，天銜闊岸紆。","鳴螿隨泛梗，別燕赴秋菰。","棲託难高臥，飢寒迫向隅。","寂寥相喣沫，浩蕩報恩珠。","溟漲鯨波动，衡陽雁影徂。","南征问懸榻，东逝想乘桴。","濫竊商歌听，时憂卞泣誅。","經過憶鄭驛，斟酌旅情孤。"]', '诗', 'shi', '', NULL, '舟出江陵南浦奉寄鄭少尹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5b1a15-0b5c-4578-8f31-1b60030633a4', '江南逢李龜年', '江南逢李龟年', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歧王宅裏尋常見，崔九堂前幾度聞。","正是江南好風景，落花時節又逢君。"]', '["歧王宅裏尋常见，崔九堂前幾度闻。","正是江南好风景，落花时節又逢君。"]', '诗', 'shi', '', NULL, '江南逢李龜年 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0e3340b-44e1-40fb-8566-bc8338573e7b', '官亭夕坐戲簡顏十少府', '官亭夕坐戲簡顏十少府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南國調寒杵，西江浸日車。","客愁連蟋蟀，亭古帶蒹葭。","不返青絲鞚，虛燒夜燭花。","老翁須地主，細細酌流霞。"]', '["南国調寒杵，西江浸日车。","客愁連蟋蟀，亭古带蒹葭。","不返青絲鞚，虛燒夜燭花。","老翁須地主，細細酌流霞。"]', '诗', 'shi', '', NULL, '官亭夕坐戲簡顏十少府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1168c377-42c2-4c1f-a283-1ba089165dab', '秋日荆南述懷三十韻', '秋日荆南述懷三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔承推獎分，媿匪挺生材。","遲暮宮臣忝，艱危衮職陪。","揚鑣隨日馭，折檻出雲臺。","罪戾寬猶活，干戈塞未開。","星霜玄鳥變，身世白駒催。","伏枕因超忽，扁舟任往來。","九鑽巴噀火，三蟄楚祠雷。","望帝傳應實，昭王問不迴。","蛟螭深作橫，豺虎亂雄猜。","素業行已矣，浮名安在哉？","琴烏曲怨憤，庭鶴舞摧頹。","秋雨漫湘水，陰風過嶺梅。","苦搖求食尾，常曝報恩顋。","結舌防讒柄，探腸有禍胎。","蒼茫步兵哭，展轉仲宣哀。","飢籍家家米，愁徵處處杯。","休爲貧士歎，任受衆人咍。","得喪初難識，榮枯劃易該。","差池分組冕，合沓起蒿萊。","不必伊周地，皆知屈宋才。","漢庭和異域，晉史坼中台。","霸業尋常體，忠臣忌諱災。","羣公紛戮力，聖慮窅裴回。","數見銘鍾鼎，真宜法斗魁。","願聞鋒鏑鑄，莫使棟梁摧。","盤石圭多翦，凶門轂少推。","垂旒資穆穆，祝網但恢恢。","赤雀飜然至，黃龍詎假媒。","賢非夢傅野，隱類鑿顏坯。","自古江湖客，冥心苦死灰。"]', '["昔承推獎分，媿匪挺生材。","遲暮宮臣忝，艱危衮職陪。","揚鑣隨日馭，折檻出云台。","罪戾寬猶活，干戈塞未开。","星霜玄鸟变，身世白駒催。","伏枕因超忽，扁舟任往来。","九鑽巴噀火，三蟄楚祠雷。","望帝傳應實，昭王问不迴。","蛟螭深作橫，豺虎亂雄猜。","素業行已矣，浮名安在哉？","琴烏曲怨憤，庭鹤舞摧頹。","秋雨漫湘水，陰风過嶺梅。","苦搖求食尾，常曝報恩顋。","結舌防讒柄，探腸有禍胎。","蒼茫步兵哭，展轉仲宣哀。","飢籍家家米，愁徵处处杯。","休爲貧士歎，任受衆人咍。","得喪初难識，榮枯劃易該。","差池分組冕，合沓起蒿萊。","不必伊周地，皆知屈宋才。","漢庭和異域，晉史坼中台。","霸業尋常體，忠臣忌諱災。","羣公紛戮力，聖慮窅裴回。","數见銘鍾鼎，真宜法斗魁。","願闻鋒鏑鑄，莫使棟梁摧。","盤石圭多翦，凶门轂少推。","垂旒資穆穆，祝網但恢恢。","赤雀飜然至，黄龙詎假媒。","賢非梦傅野，隐類鑿顏坯。","自古江湖客，冥心苦死灰。"]', '诗', 'shi', '', NULL, '秋日荆南述懷三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d0412b-b79c-4643-a730-f980bf7e088a', '秋日荆南送石首薛明府辭滿告別奉寄薛尚書頌德敍懷斐然之作三十韻', '秋日荆南送石首薛明府辞满告別奉寄薛尚书頌德敍懷斐然之作三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南征爲客久，西候別君初。","歲滿歸鳧舄，秋來把雁書。","荆門留美化，姜被就離居。","聞道和親人，垂名報國餘。","連枝不日竝，八座幾時除。","往者胡星孛，恭惟漢網疎。","風塵相澒洞，天地一丘墟。","殿瓦鴛鴦坼，宮簾翡翠虛。","鉤陳摧徼道，槍櫐失儲胥。","文物陪巡守，親賢病拮据。","公時呵䝟貐，首唱却鯨魚。","勢愜宗蕭相，材非一范雎。","屍填太行道，血走浚儀渠。","滏口師仍會，函關憤已攄。","紫微臨大角，皇極正乘輿。","賞從頻峨冕，殊私再直廬。","豈惟高衛霍，曾是接應徐。","降集飜翔鳳，追攀絕衆狙。","侍臣雙宋玉，戰策兩穰苴。","鑒澈勞懸鏡，荒蕪已荷鋤。","嚮來披述作，重此憶吹噓。","白髮甘凋喪，青雲亦卷舒。","經綸功不朽，跋涉體何如。","應訝耽湖橘，常餐占野蔬。","十年嬰藥餌，萬里狎樵漁。","揚子淹投閣，鄒生惜曳裾。","但驚飛熠耀，不記改蟾蜍。","煙雨封巫峽，江淮略孟諸。","湯池雖險固，遼海尚填淤。","努力輸肝膽，休煩獨起予。"]', '["南征爲客久，西候別君初。","歲满归鳧舄，秋来把雁书。","荆门留美化，姜被就離居。","闻道和親人，垂名報国餘。","連枝不日竝，八座幾时除。","往者胡星孛，恭惟漢網疎。","风塵相澒洞，天地一丘墟。","殿瓦鴛鴦坼，宮簾翡翠虛。","鉤陳摧徼道，槍櫐失儲胥。","文物陪巡守，親賢病拮据。","公时呵䝟貐，首唱却鯨鱼。","勢愜宗蕭相，材非一范雎。","屍填太行道，血走浚儀渠。","滏口師仍會，函关憤已攄。","紫微臨大角，皇極正乘輿。","賞從頻峨冕，殊私再直廬。","豈惟高衛霍，曾是接應徐。","降集飜翔鳳，追攀絕衆狙。","侍臣雙宋玉，戰策兩穰苴。","鑒澈勞懸镜，荒蕪已荷鋤。","嚮来披述作，重此憶吹噓。","白髮甘凋喪，青云亦卷舒。","經綸功不朽，跋涉體何如。","應訝耽湖橘，常餐占野蔬。","十年嬰藥餌，万里狎樵漁。","揚子淹投閣，鄒生惜曳裾。","但驚飞熠耀，不記改蟾蜍。","煙雨封巫峽，江淮略孟諸。","湯池雖險固，遼海尚填淤。","努力輸肝膽，休煩独起予。"]', '诗', 'shi', '', NULL, '秋日荆南送石首薛明府辭滿告別奉寄薛尚書頌德敍懷斐然之作三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c62445-9249-4c6b-8628-0058dfda0dd5', '哭李尚書', '哭李尚书', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漳濱與蒿里，逝水竟同年。","欲挂留徐劒，猶迴憶戴船。","相知成白首，此別間黃泉。","風雨嗟何及，江湖涕泫然。","修文將管輅，奉使失張騫。","史閣行人在，詩家秀句傳。","客亭鞍馬絕，旅櫬網蟲懸。","復魄昭丘遠，歸魂素滻偏。","樵蘇封葬地，喉舌罷朝天。","秋色凋春草，王孫若箇邊。"]', '["漳濱與蒿里，逝水竟同年。","欲挂留徐劒，猶迴憶戴船。","相知成白首，此別间黄泉。","风雨嗟何及，江湖涕泫然。","修文將管輅，奉使失張騫。","史閣行人在，诗家秀句傳。","客亭鞍马絕，旅櫬網蟲懸。","复魄昭丘远，归魂素滻偏。","樵蘇封葬地，喉舌罷朝天。","秋色凋春草，王孫若箇邊。"]', '诗', 'shi', '', NULL, '哭李尚書 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('511b0ab5-253f-4f98-b82e-6029d875abcf', '重題', '重題', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["涕泗不能收，哭君余白頭。","兒童相識盡，宇宙此生浮。","江雨銘旌濕，湖風井徑秋。","還瞻魏太子，賓客減應劉。"]', '["涕泗不能收，哭君余白头。","兒童相識尽，宇宙此生浮。","江雨銘旌濕，湖风井徑秋。","還瞻魏太子，賓客減應劉。"]', '诗', 'shi', '', NULL, '重題 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96dbd7f8-f385-4e71-aea2-f8e4f743418f', '獨坐', '独坐', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["悲愁回白首，倚杖背孤城。","江斂洲渚出，天虛風物清。","滄溟服衰謝，朱紱負平生。","仰羨黃昏鳥，投林羽翮輕。"]', '["悲愁回白首，倚杖背孤城。","江斂洲渚出，天虛风物清。","滄溟服衰謝，朱紱負平生。","仰羨黄昏鸟，投林羽翮轻。"]', '诗', 'shi', '', NULL, '獨坐 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b37acd-dfd9-45b0-b28a-425c5f453a35', '暮歸', '暮归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["霜黃碧梧白鶴樓，城上擊拆復烏啼。","客子入門月皎皎，誰家擣練風淒淒。","南渡桂水關舟檝，北歸秦川多鼓鞞。","年過半百不稱意，明日看雲還杖藜。"]', '["霜黄碧梧白鹤楼，城上擊拆复烏啼。","客子入门月皎皎，誰家擣練风淒淒。","南渡桂水关舟檝，北归秦川多鼓鞞。","年過半百不稱意，明日看云還杖藜。"]', '诗', 'shi', '', NULL, '暮歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc16aa10-9068-4f48-8f38-fd4ee1872954', '移居公安敬贈衛大郎', '移居公安敬贈衛大郎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衛侯不易得，余病汝知之。","雅量涵高遠，清襟照等夷。","平生感意氣，少小愛文辭。","河海由來合，風雲若有期。","形容勞宇宙，質樸謝軒墀。","自古幽人泣，留年壯士悲。","水煙通徑草，秋露接園葵。","入邑豺狼鬬，傷弓鳥雀飢。","白頭供宴語，烏几伴棲遲。","交態遭輕薄，今朝豁所思。"]', '["衛侯不易得，余病汝知之。","雅量涵高远，清襟照等夷。","平生感意氣，少小愛文辞。","河海由来合，风云若有期。","形容勞宇宙，質樸謝軒墀。","自古幽人泣，留年壯士悲。","水煙通徑草，秋露接园葵。","入邑豺狼鬬，傷弓鸟雀飢。","白头供宴語，烏几伴棲遲。","交態遭轻薄，今朝豁所思。"]', '诗', 'shi', '', NULL, '移居公安敬贈衛大郎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d283f99-14dc-476d-97f3-8a0245bb1ce4', '公安送韋二少府匡贊', '公安送韋二少府匡贊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["逍遙公後世多賢，送爾維舟惜此筵。","念我能書數字至，將詩不必萬人傳。","時危兵甲黃塵裏，日短江湖白髮前。","古往今來皆涕淚，斷腸分手各風煙。"]', '["逍遙公後世多賢，送爾維舟惜此筵。","念我能书數字至，將诗不必万人傳。","时危兵甲黄塵裏，日短江湖白髮前。","古往今来皆涕泪，斷腸分手各风煙。"]', '诗', 'shi', '', NULL, '公安送韋二少府匡贊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a94b5e1-665b-4d40-a9a4-66703d0b9f09', '贈虞十五司馬', '贈虞十五司马', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遠師虞祕監，今喜識玄孫。","形像丹青逼，家聲器宇存。","淒涼憐筆勢，浩蕩問詞源。","爽氣金天豁，清談玉露繁。","佇鳴南岳鳳，欲化北溟鯤。","交態知浮俗，儒流不異門。","過逢聯客位，日夜倒芳尊。","沙岸風吹葉，雲江月上軒。","百年嗟已半，四座敢辭喧。","書籍終相與，青山隔故園。"]', '["远師虞祕監，今喜識玄孫。","形像丹青逼，家声器宇存。","淒涼怜笔勢，浩蕩问词源。","爽氣金天豁，清談玉露繁。","佇鳴南岳鳳，欲化北溟鯤。","交態知浮俗，儒流不異门。","過逢聯客位，日夜倒芳尊。","沙岸风吹葉，云江月上軒。","百年嗟已半，四座敢辞喧。","书籍終相與，青山隔故园。"]', '诗', 'shi', '', NULL, '贈虞十五司馬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b0af5b-c537-4546-aadd-07e0b35d86ea', '公安縣懷古', '公安縣懷古', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野曠呂蒙營，江深劉備城。","寒天催日短，風浪與雲平。","灑落君臣契，飛騰戰伐名。","維舟倚前浦，長嘯一含情。"]', '["野曠呂蒙營，江深劉備城。","寒天催日短，风浪與云平。","灑落君臣契，飞腾戰伐名。","維舟倚前浦，长嘯一含情。"]', '诗', 'shi', '', NULL, '公安縣懷古 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd30e4e-275a-4d8e-afa0-b0e03200f8ef', '公安送李二十九弟晉肅入蜀余下沔鄂', '公安送李二十九弟晉肅入蜀余下沔鄂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["正解柴桑纜，仍看蜀道行。","檣烏相背發，塞雁一行鳴。","南紀連銅柱，西江接錦城。","憑將百錢卜，飄泊問君平。"]', '["正解柴桑纜，仍看蜀道行。","檣烏相背發，塞雁一行鳴。","南紀連銅柱，西江接錦城。","憑將百錢卜，飄泊问君平。"]', '诗', 'shi', '', NULL, '公安送李二十九弟晉肅入蜀余下沔鄂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc426bc-334e-4fd8-bc4c-3ba0e3fcbe4e', '宴王使君宅題二首 一', '宴王使君宅題二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢主追韓信，蒼生起謝安。","吾徒自漂泊，世事各艱難。","逆旅招邀近，他鄉思緒寬。","不材甘朽質，高臥豈泥蟠。"]', '["漢主追韓信，蒼生起謝安。","吾徒自漂泊，世事各艱难。","逆旅招邀近，他乡思緒寬。","不材甘朽質，高臥豈泥蟠。"]', '诗', 'shi', '', NULL, '宴王使君宅題二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4874778c-f3c9-456b-a64d-4cfe107b40c4', '宴王使君宅題二首 二', '宴王使君宅題二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["泛愛容霜髮，留歡卜夜閒。","自吟詩送老，相勸酒開顏。","戎馬今何地，鄉園獨舊山。","江湖墮清月，酩酊任扶還。"]', '["泛愛容霜髮，留歡卜夜閒。","自吟诗送老，相勸酒开顏。","戎马今何地，乡园独旧山。","江湖墮清月，酩酊任扶還。"]', '诗', 'shi', '', NULL, '宴王使君宅題二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b70cf4d-91c2-4f35-88b6-27719132e234', '留別公安太易沙門', '留別公安太易沙门', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["隱居欲就廬山遠，麗藻初逢休上人。","數問舟航留製作，長開篋笥擬心神。","沙村白雪仍含凍，江縣紅梅已放春。","先蹋爐峰置蘭若，徐飛錫杖出風塵。"]', '["隐居欲就廬山远，丽藻初逢休上人。","數问舟航留製作，长开篋笥擬心神。","沙村白雪仍含凍，江縣紅梅已放春。","先蹋爐峰置蘭若，徐飞錫杖出风塵。"]', '诗', 'shi', '', NULL, '留別公安太易沙門 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62a3f41-1b77-4897-823e-c6f080f4b488', '曉發公安', '晓發公安', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北城擊柝復欲罷，東方明星亦不遲。","鄰雞野哭如昨日，物色生態能幾時。","舟檝眇然自此去，江湖遠適無前期。","出門轉眄已陳迹，藥餌扶吾隨所之。"]', '["北城擊柝复欲罷，东方明星亦不遲。","鄰雞野哭如昨日，物色生態能幾时。","舟檝眇然自此去，江湖远適無前期。","出门轉眄已陳迹，藥餌扶吾隨所之。"]', '诗', 'shi', '', NULL, '曉發公安 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa01fa86-99b8-4f58-b591-1007b5d3b010', '泊岳陽城下', '泊岳陽城下', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江國踰千里，山城僅百層。","岸風飜夕浪，舟雪灑寒燈。","留滯才難盡，艱危氣益增。","圖南未可料，變化有鯤鵬。"]', '["江国踰千里，山城僅百層。","岸风飜夕浪，舟雪灑寒灯。","留滯才难尽，艱危氣益增。","圖南未可料，变化有鯤鵬。"]', '诗', 'shi', '', NULL, '泊岳陽城下 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d16ccaa-a7a3-45e6-b0d9-6e94e3e1d99d', '纜船苦風戲題四韻奉簡鄭十三判官', '纜船苦风戲題四韻奉簡鄭十三判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚岸朔風疾，天寒鶬鴰呼。","漲沙霾草樹，舞雪渡江湖。","吹帽時時落，維舟日日孤。","因聲置驛外，爲覓酒家壚。"]', '["楚岸朔风疾，天寒鶬鴰呼。","漲沙霾草樹，舞雪渡江湖。","吹帽时时落，維舟日日孤。","因声置驛外，爲覓酒家壚。"]', '诗', 'shi', '', NULL, '纜船苦風戲題四韻奉簡鄭十三判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d05fef6-e4aa-48e5-917d-c29d0e6d6b33', '登岳陽樓', '登岳陽楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔聞洞庭水，今上岳陽樓。","吳楚東南坼，乾坤日夜浮。","親朋無一字，老病有孤舟。","戎馬關山北，憑軒涕泗流。"]', '["昔闻洞庭水，今上岳陽楼。","吳楚东南坼，乾坤日夜浮。","親朋無一字，老病有孤舟。","戎马关山北，憑軒涕泗流。"]', '诗', 'shi', '', NULL, '登岳陽樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70bf788-5565-441d-a424-8a6d0580dc8b', '陪裴使君登岳陽樓', '陪裴使君登岳陽楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["湖闊兼雲霧，樓孤屬晚晴。","禮加徐孺子，詩接謝宣城。","雪岸叢梅發，春泥百草生。","敢違漁父問，從此更南征。"]', '["湖闊兼云霧，楼孤屬晚晴。","禮加徐孺子，诗接謝宣城。","雪岸叢梅發，春泥百草生。","敢違漁父问，從此更南征。"]', '诗', 'shi', '', NULL, '陪裴使君登岳陽樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5525bf-6b4c-4bfc-ac1d-ecef40a745f2', '過南岳入洞庭湖', '過南岳入洞庭湖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洪波忽爭道，岸轉異江湖。","鄂渚分雲樹，衡山引舳艫。","翠牙穿裛槳，碧節上寒蒲。","病渴身何去，春生力更無。","壤童犂雨雪，漁屋架泥塗。","欹側風帆滿，微冥水驛孤。","悠悠迴赤壁，浩浩略蒼梧。","帝子留遺恨，曹公屈壯圖。","聖朝光御極，殘孽駐艱虞。","才淑隨廝養，名賢隱鍛鑪。","邵平元入漢，張翰後歸吳。","莫怪啼痕數，危檣逐夜烏。"]', '["洪波忽爭道，岸轉異江湖。","鄂渚分云樹，衡山引舳艫。","翠牙穿裛槳，碧節上寒蒲。","病渴身何去，春生力更無。","壤童犂雨雪，漁屋架泥塗。","欹側风帆满，微冥水驛孤。","悠悠迴赤壁，浩浩略蒼梧。","帝子留遺恨，曹公屈壯圖。","聖朝光御極，殘孽駐艱虞。","才淑隨廝養，名賢隐鍛鑪。","邵平元入漢，張翰後归吳。","莫怪啼痕數，危檣逐夜烏。"]', '诗', 'shi', '', NULL, '過南岳入洞庭湖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0599e6cd-e57a-4b90-ac98-f65a23cebae0', '宿青草湖', '宿青草湖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洞庭猶在目，青草續爲名。","宿槳依農事，郵籤報水程。","寒冰爭倚薄，雲月遞微明。","湖雁雙雙起，人來故北征。"]', '["洞庭猶在目，青草續爲名。","宿槳依農事，郵籤報水程。","寒冰爭倚薄，云月遞微明。","湖雁雙雙起，人来故北征。"]', '诗', 'shi', '', NULL, '宿青草湖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5a763f-80a5-4af8-93c0-083856a6aeb6', '宿白沙驛', '宿白沙驛', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["水宿仍餘照，人煙復此亭。","驛邊沙舊白，湖外草新青。","萬象皆春氣，孤槎自客星。","隨波無限月，的的近南溟。"]', '["水宿仍餘照，人煙复此亭。","驛邊沙旧白，湖外草新青。","万象皆春氣，孤槎自客星。","隨波無限月，的的近南溟。"]', '诗', 'shi', '', NULL, '宿白沙驛 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20dd694b-d037-4c84-bcde-26b98a9c689a', '湘夫人祠', '湘夫人祠', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["肅肅湘妃廟，空牆碧水春。","蟲書玉佩蘚，燕舞翠帷塵。","晚泊登汀樹，微馨借渚蘋。","蒼梧恨不盡，染淚在叢筠。"]', '["肅肅湘妃廟，空牆碧水春。","蟲书玉佩蘚，燕舞翠帷塵。","晚泊登汀樹，微馨借渚蘋。","蒼梧恨不尽，染泪在叢筠。"]', '诗', 'shi', '', NULL, '湘夫人祠 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad112c4f-ec1f-410d-9e8a-9784c3a8a355', '祠南夕望', '祠南夕望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百丈牽江色，孤舟泛日斜。","興來猶杖屨，目斷更雲沙。","山鬼迷春竹，湘娥倚暮花。","湖南清絕地，萬古一長嗟。"]', '["百丈牽江色，孤舟泛日斜。","兴来猶杖屨，目斷更云沙。","山鬼迷春竹，湘娥倚暮花。","湖南清絕地，万古一长嗟。"]', '诗', 'shi', '', NULL, '祠南夕望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2ba157-9d10-4c65-8da8-9b277d0ebeb3', '登白馬潭', '登白马潭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["水生春纜沒，日出野船開。","宿鳥行猶去，叢花笑不來。","人人傷白首，處處接金杯。","莫道新知要，南征且未回。"]', '["水生春纜沒，日出野船开。","宿鸟行猶去，叢花笑不来。","人人傷白首，处处接金杯。","莫道新知要，南征且未回。"]', '诗', 'shi', '', NULL, '登白馬潭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7a0111-98f9-43e5-bad4-9c73c5336389', '歸雁', '归雁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道今春雁，南歸自廣州。","見花辭漲海，避雪到羅浮。","是物關兵氣，何時免客愁。","年年霜露隔，不過五湖秋。"]', '["闻道今春雁，南归自廣州。","见花辞漲海，避雪到羅浮。","是物关兵氣，何时免客愁。","年年霜露隔，不過五湖秋。"]', '诗', 'shi', '', NULL, '歸雁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11ed6db-b3a6-46f9-b51e-94a0d8606406', '野望', '野望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["納納乾坤大，行行郡國遙。","雲山兼五嶺，風壤帶三苗。","野樹侵江闊，春蒲長雪消。","扁舟空老去，無補聖明朝。"]', '["納納乾坤大，行行郡国遙。","云山兼五嶺，风壤带三苗。","野樹侵江闊，春蒲长雪消。","扁舟空老去，無補聖明朝。"]', '诗', 'shi', '', NULL, '野望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f334fa1b-6b29-4a14-a769-828fa8fd2ec9', '入喬口', '入喬口', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漠漠舊京遠，遲遲歸路賒。","殘年傍水國，落日對春華。","樹蜜早蠭亂，江泥輕燕斜。","賈生骨已朽，悽惻近長沙。"]', '["漠漠旧京远，遲遲归路賒。","殘年傍水国，落日对春华。","樹蜜早蠭亂，江泥轻燕斜。","賈生骨已朽，悽惻近长沙。"]', '诗', 'shi', '', NULL, '入喬口 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272095aa-4f8c-4674-b704-e626118c81db', '銅官渚守風', '銅官渚守风', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不夜楚帆落，避風湘渚間。","水耕先浸草，春火更燒山。","早泊雲物晦，逆行波浪慳。","飛來雙白鶴，過去杳難攀。"]', '["不夜楚帆落，避风湘渚间。","水耕先浸草，春火更燒山。","早泊云物晦，逆行波浪慳。","飞来雙白鹤，過去杳难攀。"]', '诗', 'shi', '', NULL, '銅官渚守風 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f8bb74-5673-41a8-96ac-6a5e3a906382', '北風', '北风', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春生南國瘴，氣待北風蘇。","向晚霾殘日，初宵鼓大鑪。","爽攜卑濕地，聲拔洞庭湖。","萬里魚龍伏，三更鳥獸呼。","滌除貪破浪，愁絕付摧枯。","執熱沈沈在，凌寒往往須。","且知寬疾胏，不敢恨危途。","再宿煩舟子，衰容問僕夫。","今晨非盛怒，便道即長驅。","隱几看帆席，雲州湧坐隅。"]', '["春生南国瘴，氣待北风蘇。","向晚霾殘日，初宵鼓大鑪。","爽携卑濕地，声拔洞庭湖。","万里鱼龙伏，三更鸟獸呼。","滌除貪破浪，愁絕付摧枯。","執熱沈沈在，凌寒往往須。","且知寬疾胏，不敢恨危途。","再宿煩舟子，衰容问僕夫。","今晨非盛怒，便道即长驱。","隐几看帆席，云州湧坐隅。"]', '诗', 'shi', '', NULL, '北風 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767a621a-7b99-49c1-813f-1537932d9297', '雙楓浦', '雙楓浦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["輟櫂青楓浦，雙楓舊已摧。","自驚衰謝力，不道棟梁材。","浪足浮紗帽，皮須截錦苔。","江邊地有主，暫借上天迴。"]', '["輟櫂青楓浦，雙楓旧已摧。","自驚衰謝力，不道棟梁材。","浪足浮紗帽，皮須截錦苔。","江邊地有主，暫借上天迴。"]', '诗', 'shi', '', NULL, '雙楓浦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78368c3c-4a50-4662-9fe2-261dcb331ab3', '奉送王信州崟北歸', '奉送王信州崟北归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝廷防盜賊，供給愍誅求。","下詔選郎署，傳聲能典州。","蒼生今日困，天子嚮時憂。","井屋有煙起，瘡痍無血流。","壤歌唯海甸，畫角自山樓。","白髮寐常早，荒榛農復秋。","解龜踰臥轍，遣騎覓扁舟。","徐榻不知倦，潁川何以酬。","塵生彤管筆，寒膩黑貂裘。","高義終焉在，斯文去矣休。","別離同雨散，行止各雲浮。","林熱鳥開口，江渾魚掉頭。","尉佗雖北拜，太史尚南留。","軍旅應都息，寰區要盡收。","九重思諫諍，八極念懷柔。","徙倚瞻王室，從容仰廟謀。","故人持雅論，絕塞豁窮愁。","復見陶唐理，甘爲汗漫遊。"]', '["朝廷防盜賊，供給愍誅求。","下詔選郎署，傳声能典州。","蒼生今日困，天子嚮时憂。","井屋有煙起，瘡痍無血流。","壤歌唯海甸，畫角自山楼。","白髮寐常早，荒榛農复秋。","解龟踰臥轍，遣騎覓扁舟。","徐榻不知倦，潁川何以酬。","塵生彤管笔，寒膩黑貂裘。","高義終焉在，斯文去矣休。","別離同雨散，行止各云浮。","林熱鸟开口，江渾鱼掉头。","尉佗雖北拜，太史尚南留。","軍旅應都息，寰區要尽收。","九重思諫諍，八極念懷柔。","徙倚瞻王室，從容仰廟謀。","故人持雅論，絕塞豁窮愁。","复见陶唐理，甘爲汗漫游。"]', '诗', 'shi', '', NULL, '奉送王信州崟北歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e3f5313-7c69-4bfb-9be8-4cf31afd0f12', '江閣臥病走筆寄呈崔盧兩侍御', '江閣臥病走笔寄呈崔盧兩侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客子庖廚薄，江樓枕席清。","衰年病祗瘦，長夏想爲情。","滑憶彫胡飯，香聞錦帶羹。","溜匙兼暖腹，誰欲致杯甖。"]', '["客子庖廚薄，江楼枕席清。","衰年病祗瘦，长夏想爲情。","滑憶彫胡飯，香闻錦带羹。","溜匙兼暖腹，誰欲致杯甖。"]', '诗', 'shi', '', NULL, '江閣臥病走筆寄呈崔盧兩侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a50da07-221c-4d47-848f-5bc81a0644b8', '潭州送韋員外牧韶州', '潭州送韋員外牧韶州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["炎海韶州牧，風流漢署郎。","分符先令望，同舍有輝光。","白首多年疾，秋天昨夜涼。","洞庭無過雁，書疏莫相忘。"]', '["炎海韶州牧，风流漢署郎。","分符先令望，同舍有輝光。","白首多年疾，秋天昨夜涼。","洞庭無過雁，书疏莫相忘。"]', '诗', 'shi', '', NULL, '潭州送韋員外牧韶州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4661e4b6-82bb-4897-a21c-559468a25ca7', '江閣對雨有懷行營裴二端公', '江閣对雨有懷行營裴二端公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南紀風濤壯，陰晴屢不分。","野流行地日，江入度山雲。","層閣憑雷殷，長空水面文。","雨來銅柱北，應洗伏波軍。"]', '["南紀风濤壯，陰晴屢不分。","野流行地日，江入度山云。","層閣憑雷殷，长空水面文。","雨来銅柱北，應洗伏波軍。"]', '诗', 'shi', '', NULL, '江閣對雨有懷行營裴二端公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06503227-08cb-4d3e-aa95-9471d4f5b22f', '酬韋韶州見寄', '酬韋韶州见寄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["養拙江湖外，朝廷記憶疎。","深慙長者轍，重得故人書。","白髮絲難理，新詩錦不如。","雖無南去雁，看取北來魚。"]', '["養拙江湖外，朝廷記憶疎。","深慙长者轍，重得故人书。","白髮絲难理，新诗錦不如。","雖無南去雁，看取北来鱼。"]', '诗', 'shi', '', NULL, '酬韋韶州見寄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e72f4403-6f48-473d-96d4-730900a4eb10', '千秋節有感二首 一', '千秋節有感二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自罷千秋節，頻傷八月來。","先朝常宴會，壯觀已塵埃。","鳳紀編生日，龍池塹劫灰。","湘川新涕淚，秦樹遠樓臺。","寶鏡羣臣得，金吾萬國迴。","衢尊不重飲，白首獨餘哀。"]', '["自罷千秋節，頻傷八月来。","先朝常宴會，壯观已塵埃。","鳳紀編生日，龙池塹劫灰。","湘川新涕泪，秦樹远楼台。","寶镜羣臣得，金吾万国迴。","衢尊不重饮，白首独餘哀。"]', '诗', 'shi', '', NULL, '千秋節有感二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77e5692-4182-472f-8b19-6fa83cc74e5b', '千秋節有感二首 二', '千秋節有感二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["御氣雲樓敞，含風綵仗高。","仙人張內樂，王母獻宮桃。","羅襪紅蕖豔，金羈白雪毛。","舞階銜壽酒，走索背秋毫。","聖主他年貴，邊心此日勞。","桂江流向北，滿眼送波濤。"]', '["御氣云楼敞，含风綵仗高。","仙人張內乐，王母獻宮桃。","羅襪紅蕖豔，金羈白雪毛。","舞階銜壽酒，走索背秋毫。","聖主他年貴，邊心此日勞。","桂江流向北，满眼送波濤。"]', '诗', 'shi', '', NULL, '千秋節有感二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca9f283-25e2-4e86-a080-3f2ab565154d', '晚秋長沙蔡五侍御飲筵送殷六參軍歸澧州覲省', '晚秋长沙蔡五侍御饮筵送殷六參軍归澧州覲省', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["佳士欣相識，慈顏望遠遊。","甘從投轄飲，肯作置書郵。","高鳥黃雲暮，寒蟬碧樹秋。","湖南冬不雪，吾病得淹留。"]', '["佳士欣相識，慈顏望远游。","甘從投轄饮，肯作置书郵。","高鸟黄云暮，寒蟬碧樹秋。","湖南冬不雪，吾病得淹留。"]', '诗', 'shi', '', NULL, '晚秋長沙蔡五侍御飲筵送殷六參軍歸澧州覲省 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5728a2f1-e337-4f6d-95b1-ff5e51693d44', '湖中送敬十使君適廣陵', '湖中送敬十使君適廣陵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["相見各頭白，其如離別何。","幾年一會面，今日復悲歌。","少壯樂難得，歲寒心匪他。","氣纏霜匣滿，冰置玉壺多。","遭亂實漂泊，濟時曾琢磨。","形容吾校老，膽力爾誰過。","秋晚岳增翠，風高湖湧波。","騫騰訪知己，淮海莫磋跎。"]', '["相见各头白，其如離別何。","幾年一會面，今日复悲歌。","少壯乐难得，歲寒心匪他。","氣纏霜匣满，冰置玉壺多。","遭亂實漂泊，濟时曾琢磨。","形容吾校老，膽力爾誰過。","秋晚岳增翠，风高湖湧波。","騫腾訪知己，淮海莫磋跎。"]', '诗', 'shi', '', NULL, '湖中送敬十使君適廣陵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d16ff1c-ae92-41ad-9278-195c506463fc', '長沙送李十一', '长沙送李十一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["與子避地西康州，洞庭相逢十二秋。","遠媿尚方曾賜履，竟非吾土倦登樓。","久存膠漆應難竝，一辱泥塗遂晚收。","李杜齊名真忝竊，朔雲寒菊倍離憂。"]', '["與子避地西康州，洞庭相逢十二秋。","远媿尚方曾賜履，竟非吾土倦登楼。","久存膠漆應难竝，一辱泥塗遂晚收。","李杜齊名真忝竊，朔云寒菊倍離憂。"]', '诗', 'shi', '', NULL, '長沙送李十一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3aa647-68e8-4ab9-8a5c-eabf83671ad8', '重送劉十弟判官', '重送劉十弟判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["分源豕韋派，別浦雁賓秋。","年事推兄忝，人才覺弟優。","經過辨豐劒，意氣逐吳鉤。","垂翅徒衰老，先鞭不滯留。","本枝凌歲晚，高義豁窮愁。","他日臨江待，長沙舊驛樓。"]', '["分源豕韋派，別浦雁賓秋。","年事推兄忝，人才覺弟優。","經過辨豐劒，意氣逐吳鉤。","垂翅徒衰老，先鞭不滯留。","本枝凌歲晚，高義豁窮愁。","他日臨江待，长沙旧驛楼。"]', '诗', 'shi', '', NULL, '重送劉十弟判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03835a84-cf65-4775-8f22-fd98bf907b5e', '奉贈盧五丈參謀', '奉贈盧五丈參謀', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["恭惟同自出，妙選異高標。","入幕知孫楚，披襟得鄭僑。","丈人藉才地，門閥冠雲霄。","老矣逢迎拙，相於契託饒。","賜錢傾府待，爭米駐船遙。","鄰好艱難薄，氓心杼軸焦。","客星空伴使，寒水不成潮。","素髮乾垂領，銀章破在腰。","說詩能累夜，醉酒或連朝。","藻翰惟牽率，湖山合動搖。","時清非造次，興盡却蕭條。","天子多恩澤，蒼生轉寂寥。","休傳鹿是馬，莫信鵩如鴞。","未解依依袂，還斟泛泛瓢。","流年疲蟋蟀，體物幸鷦鷯。","辜負滄州願，誰云晚見招。"]', '["恭惟同自出，妙選異高標。","入幕知孫楚，披襟得鄭僑。","丈人藉才地，门閥冠云霄。","老矣逢迎拙，相於契託饒。","賜錢傾府待，爭米駐船遙。","鄰好艱难薄，氓心杼軸焦。","客星空伴使，寒水不成潮。","素髮乾垂領，銀章破在腰。","说诗能累夜，醉酒或連朝。","藻翰惟牽率，湖山合动搖。","时清非造次，兴尽却蕭條。","天子多恩澤，蒼生轉寂寥。","休傳鹿是马，莫信鵩如鴞。","未解依依袂，還斟泛泛瓢。","流年疲蟋蟀，體物幸鷦鷯。","辜負滄州願，誰云晚见招。"]', '诗', 'shi', '', NULL, '奉贈盧五丈參謀 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232e1f32-4d09-4689-b3ba-6d434f6aacf7', '登舟將適漢陽', '登舟將適漢陽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春宅棄汝去，秋帆催客歸。","庭蔬尚在眼，浦浪已吹衣。","生理飄蕩拙，有心遲暮歸。","中原戎馬盛，遠道素書稀。","塞雁與時集，檣烏終歲飛。","鹿門自此往，永息漢陰機。"]', '["春宅棄汝去，秋帆催客归。","庭蔬尚在眼，浦浪已吹衣。","生理飄蕩拙，有心遲暮归。","中原戎马盛，远道素书稀。","塞雁與时集，檣烏終歲飞。","鹿门自此往，永息漢陰機。"]', '诗', 'shi', '', NULL, '登舟將適漢陽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b424b44-0b51-483b-9936-1a92c6a23993', '暮秋將歸秦留別湖南幕府親友', '暮秋將归秦留別湖南幕府親友', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["水闊蒼梧野，天高白帝秋。","途窮那免哭，身老不禁愁。","大府才能會，諸公德業優。","北歸衝雨雪，誰憫敝貂裘。"]', '["水闊蒼梧野，天高白帝秋。","途窮那免哭，身老不禁愁。","大府才能會，諸公德業優。","北归衝雨雪，誰憫敝貂裘。"]', '诗', 'shi', '', NULL, '暮秋將歸秦留別湖南幕府親友 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01524421-e3e5-49f3-a237-ae1c44d720b9', '送盧十四弟侍御護韋尚書靈櫬歸上都二十韻', '送盧十四弟侍御護韋尚书靈櫬归上都二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["素幕渡江遠，朱幡登陸微。","悲鳴駟馬顧，失涕萬人揮。","參佐哭辭畢，門闌誰送歸。","從公伏事久，之子俊才稀。","長路更執紼，此心猶倒衣。","感恩義不小，懷舊禮無違。","墓待龍驤詔，臺迎獬豸威。","深衷見士則，雅論在兵機。","戎狄乘妖氣，塵沙落禁闈。","往年朝謁斷，他日埽除非。","但促銅壺箭，休添玉帳旂。","動詢黃閣老，肯慮白登圍。","萬姓瘡痍合，羣凶嗜慾肥。","刺規多諫諍，端拱自光輝。","儉約前王體，風流後代希。","對敭期特達，衰朽再芳菲。","空裏愁書字，山中疾采薇。","撥杯要忽罷，抱被宿何依。","眼冷看征蓋，兒扶立釣磯。","清霜洞庭葉，故就別時飛。"]', '["素幕渡江远，朱幡登陸微。","悲鳴駟马顧，失涕万人揮。","參佐哭辞畢，门闌誰送归。","從公伏事久，之子俊才稀。","长路更執紼，此心猶倒衣。","感恩義不小，懷旧禮無違。","墓待龙驤詔，台迎獬豸威。","深衷见士則，雅論在兵機。","戎狄乘妖氣，塵沙落禁闈。","往年朝謁斷，他日埽除非。","但促銅壺箭，休添玉帳旂。","动詢黄閣老，肯慮白登圍。","万姓瘡痍合，羣凶嗜慾肥。","刺規多諫諍，端拱自光輝。","儉約前王體，风流後代希。","对敭期特達，衰朽再芳菲。","空裏愁书字，山中疾采薇。","撥杯要忽罷，抱被宿何依。","眼冷看征蓋，兒扶立釣磯。","清霜洞庭葉，故就別时飞。"]', '诗', 'shi', '', NULL, '送盧十四弟侍御護韋尚書靈櫬歸上都二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('135919ac-449e-4c24-b088-c71de153f199', '哭李常侍嶧二首 一', '哭李常侍嶧二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一代風流盡，修文地下深。","斯人不重見，將老失知音。","短日行梅嶺，寒山落桂林。","長安若箇畔，猶想映貂金。"]', '["一代风流尽，修文地下深。","斯人不重见，將老失知音。","短日行梅嶺，寒山落桂林。","长安若箇畔，猶想映貂金。"]', '诗', 'shi', '', NULL, '哭李常侍嶧二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f418e9-b030-4998-bd2f-d1f21ade4e5a', '哭李常侍嶧二首 二', '哭李常侍嶧二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青瑣陪雙入，銅梁阻一辭。","風塵逢我地，江漢哭君時。","次第尋書札，呼兒檢贈詩。","發揮王子表，不媿史臣詞。"]', '["青瑣陪雙入，銅梁阻一辞。","风塵逢我地，江漢哭君时。","次第尋书札，呼兒檢贈诗。","發揮王子表，不媿史臣词。"]', '诗', 'shi', '', NULL, '哭李常侍嶧二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d1a893-b647-4f14-a083-ae4b9a99edbb', '哭韋大夫之晉', '哭韋大夫之晉', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["悽愴郇瑕色，差池弱冠年。","丈人叨禮數，文律早周旋。","臺閣黃圖裏，簪裾紫蓋邊。","尊榮真不忝，端雅獨翛然。","貢喜音容間，馮招病疾纏。","南過駭倉卒，北思悄聯緜。","鵩鳥長沙諱，犀牛蜀郡憐。","素車猶慟哭，寶劒欲高懸。","漢道中興盛，韋經亞相傳。","沖融標世業，磊落映時賢。","城府深朱夏，江湖眇霽天。","綺樓關樹頂，飛旐汎堂前。","帟幕疑風燕，笳簫急暮蟬。","興殘虛白室，跡斷孝廉船。","童孺交遊盡，喧卑俗事牽。","老來多涕淚，情在強詩篇。","誰寄方隅理，朝難將帥權。","春秋褒貶例，名器重雙全。"]', '["悽愴郇瑕色，差池弱冠年。","丈人叨禮數，文律早周旋。","台閣黄圖裏，簪裾紫蓋邊。","尊榮真不忝，端雅独翛然。","貢喜音容间，馮招病疾纏。","南過駭倉卒，北思悄聯緜。","鵩鸟长沙諱，犀牛蜀郡怜。","素车猶慟哭，寶劒欲高懸。","漢道中兴盛，韋經亞相傳。","沖融標世業，磊落映时賢。","城府深朱夏，江湖眇霽天。","綺楼关樹頂，飞旐汎堂前。","帟幕疑风燕，笳簫急暮蟬。","兴殘虛白室，跡斷孝廉船。","童孺交游尽，喧卑俗事牽。","老来多涕泪，情在強诗篇。","誰寄方隅理，朝难將帥權。","春秋褒貶例，名器重雙全。"]', '诗', 'shi', '', NULL, '哭韋大夫之晉 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a3131f-aaa2-4557-9233-aeceb9edbb63', '舟中夜雪有懷盧十四侍御弟', '舟中夜雪有懷盧十四侍御弟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朔風吹桂水，朔雪夜紛紛。","暗度南樓月，寒深北渚雲。","燭斜初近見，舟重竟無聞。","不識山陰道，聽雞更憶君。"]', '["朔风吹桂水，朔雪夜紛紛。","暗度南楼月，寒深北渚云。","燭斜初近见，舟重竟無闻。","不識山陰道，听雞更憶君。"]', '诗', 'shi', '', NULL, '舟中夜雪有懷盧十四侍御弟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6b1d10-773b-41cc-ba18-6cf545884231', '對雪', '对雪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北雪犯長沙，胡雲冷萬家。","隨風且間葉，帶雨不成花。","金錯囊從罄，銀壺酒易賒。","無人竭浮蟻，有待至昏鴉。"]', '["北雪犯长沙，胡云冷万家。","隨风且间葉，带雨不成花。","金錯囊從罄，銀壺酒易賒。","無人竭浮蟻，有待至昏鴉。"]', '诗', 'shi', '', NULL, '對雪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580369cf-1eb5-4463-8e49-579462e0cc2a', '樓上', '楼上', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天地空搔首，頻抽白玉簪。","皇輿三極北，身事五湖南。","戀闕勞肝肺，論材媿杞柟。","亂離難自救，終是老湘潭。"]', '["天地空搔首，頻抽白玉簪。","皇輿三極北，身事五湖南。","戀闕勞肝肺，論材媿杞柟。","亂離难自救，終是老湘潭。"]', '诗', 'shi', '', NULL, '樓上 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13d98fa-8cde-4b47-8bb7-ffdafb0de067', '冬晚送長孫漸舍人歸州', '冬晚送长孫漸舍人归州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["參卿休坐幄，蕩子不還鄉。","南客瀟湘外，西戎鄠杜旁。","衰年傾蓋晚，費日繫舟長。","會面思來札，銷魂逐去檣。","雲晴鷗更舞，風逆雁無行。","匣裏雌雄劒，吹毛任選將。"]', '["參卿休坐幄，蕩子不還乡。","南客瀟湘外，西戎鄠杜旁。","衰年傾蓋晚，費日繫舟长。","會面思来札，銷魂逐去檣。","云晴鷗更舞，风逆雁無行。","匣裏雌雄劒，吹毛任選將。"]', '诗', 'shi', '', NULL, '冬晚送長孫漸舍人歸州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159f0579-ff84-4cca-a001-9b5709cbf122', '暮冬送蘇四郎徯兵曹適桂州', '暮冬送蘇四郎徯兵曹適桂州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["飄飄蘇季子，六印佩何遲。","早作諸侯客，兼工古體詩。","爾賢埋照久，余病長年悲。","盧綰須征日，樓蘭要斬時。","歲陽初盛動，王化久磷緇。","爲人蒼梧廟，看雲哭九疑。"]', '["飄飄蘇季子，六印佩何遲。","早作諸侯客，兼工古體诗。","爾賢埋照久，余病长年悲。","盧綰須征日，楼蘭要斬时。","歲陽初盛动，王化久磷緇。","爲人蒼梧廟，看云哭九疑。"]', '诗', 'shi', '', NULL, '暮冬送蘇四郎徯兵曹適桂州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a8cc9a-28f6-44d0-8195-d44de3bd0a8b', '風疾舟中伏枕書懷三十六韻奉呈湖南親友', '风疾舟中伏枕书懷三十六韻奉呈湖南親友', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["軒轅休製律，虞舜罷彈琴。","尚錯雄鳴管，猶傷半死心。","聖賢名古邈，羇旅病年侵。","舟泊常依震，湖平早見參。","如聞馬融笛，若倚仲宣襟。","故國悲寒望，羣雲慘歲陰。","水鄉霾白屋，楓岸疊青岑。","鬱鬱冬炎瘴，濛濛雨滯淫。","鼓迎非祭鬼，彈落似鴞禽。","興盡纔無悶，愁來遽不禁。","生涯相汩沒，時物自蕭森。","疑惑尊中弩，淹留冠上簪。","牽裾驚魏帝，投閣爲劉歆。","狂走終奚適，微才謝所欽。","吾安藜不糝，汝貴玉爲琛。","烏几重重縛，鶉衣寸寸鍼。","哀傷同庾信，述作異陳琳。","十暑岷山葛，三霜楚戶砧。","叨陪錦帳座，久放白頭吟。","反樸時難遇，忘機陸易沈。","應過數粒食，得近四知金。","春草封歸恨，源花費獨尋。","轉蓬憂悄悄，行藥病涔涔。","瘞夭追潘岳，持危覓鄧林。","蹉跎飜學步，感激在知音。","却假蘇張舌，高誇周宋鐔。","納流迷浩汗，峻址得嶔崟。","城府開清旭，松筠起碧潯。","披顏爭倩倩，逸足競駸駸。","朗鑒存愚直，皇天實照臨。","公孫仍恃險，侯景未生擒。","書信中原闊，干戈北斗深。","畏人千里井，問俗九州箴。","戰血流依舊，軍聲動至今。","葛洪尸定解，許靖力還任。","家事丹砂訣，無成涕作霖。"]', '["軒轅休製律，虞舜罷彈琴。","尚錯雄鳴管，猶傷半死心。","聖賢名古邈，羇旅病年侵。","舟泊常依震，湖平早见參。","如闻马融笛，若倚仲宣襟。","故国悲寒望，羣云慘歲陰。","水乡霾白屋，楓岸叠青岑。","鬱鬱冬炎瘴，濛濛雨滯淫。","鼓迎非祭鬼，彈落似鴞禽。","兴尽纔無悶，愁来遽不禁。","生涯相汩沒，时物自蕭森。","疑惑尊中弩，淹留冠上簪。","牽裾驚魏帝，投閣爲劉歆。","狂走終奚適，微才謝所欽。","吾安藜不糝，汝貴玉爲琛。","烏几重重縛，鶉衣寸寸鍼。","哀傷同庾信，述作異陳琳。","十暑岷山葛，三霜楚戶砧。","叨陪錦帳座，久放白头吟。","反樸时难遇，忘機陸易沈。","應過數粒食，得近四知金。","春草封归恨，源花費独尋。","轉蓬憂悄悄，行藥病涔涔。","瘞夭追潘岳，持危覓鄧林。","蹉跎飜学步，感激在知音。","却假蘇張舌，高誇周宋鐔。","納流迷浩汗，峻址得嶔崟。","城府开清旭，松筠起碧潯。","披顏爭倩倩，逸足競駸駸。","朗鑒存愚直，皇天實照臨。","公孫仍恃險，侯景未生擒。","书信中原闊，干戈北斗深。","畏人千里井，问俗九州箴。","戰血流依旧，軍声动至今。","葛洪尸定解，許靖力還任。","家事丹砂訣，無成涕作霖。"]', '诗', 'shi', '', NULL, '風疾舟中伏枕書懷三十六韻奉呈湖南親友 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b54ccce5-156f-4067-8408-a1d8a0d4c180', '奉贈蕭二十使君', '奉贈蕭二十使君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["惜在嚴公幕，俱爲蜀使臣。","艱危參大府，前後間清塵。","起草鳴先路，乘槎動要津。","王鳧聊暫出，蕭雉只相馴。","終始任安義，荒蕪孟母鄰。","聯翩匍匐禮，意氣死生親。","張老存家事，嵇康有故人。","食恩慙鹵莽，鏤骨抱酸辛。","巢許山林志，夔龍廊廟珍。","鵬圖乃矯翼，熊軾且移輪。","磊落衣冠地，蒼茫土木身。","塤篪鳴自合，金石瑩逾新。","重憶羅江外，同遊錦水濱。","結歡隨過隙，懷舊益霑巾。","曠絕含香舍，稽留伏枕辰。","停驂雙闕早，迴雁五湖春。","不達長卿病，從來原憲貧。","監河受貸粟，一起轍中鱗。"]', '["惜在嚴公幕，俱爲蜀使臣。","艱危參大府，前後间清塵。","起草鳴先路，乘槎动要津。","王鳧聊暫出，蕭雉只相馴。","終始任安義，荒蕪孟母鄰。","聯翩匍匐禮，意氣死生親。","張老存家事，嵇康有故人。","食恩慙鹵莽，鏤骨抱酸辛。","巢許山林志，夔龙廊廟珍。","鵬圖乃矯翼，熊軾且移輪。","磊落衣冠地，蒼茫土木身。","塤篪鳴自合，金石瑩逾新。","重憶羅江外，同游錦水濱。","結歡隨過隙，懷旧益霑巾。","曠絕含香舍，稽留伏枕辰。","停驂雙闕早，迴雁五湖春。","不達长卿病，從来原憲貧。","監河受貸粟，一起轍中鱗。"]', '诗', 'shi', '', NULL, '奉贈蕭二十使君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee733580-5e11-44be-9e68-4b42a85d8f8e', '奉送二十三舅錄事之攝郴州', '奉送二十三舅錄事之攝郴州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賢良歸盛族，吾舅盡知名。","徐庶高交友，劉牢出外甥。","泥塗豈珠玉，環堵但柴荆。","衰老悲人世，驅馳厭甲兵。","氣春江上別，淚血渭陽情。","舟鷁排風影，林烏反哺聲。","永嘉多北至，句漏且南征。","必見公侯復，終聞盜賊平。","郴州頗涼冷，橘井尚淒清。","從役何蠻貊，居官志在行。"]', '["賢良归盛族，吾舅尽知名。","徐庶高交友，劉牢出外甥。","泥塗豈珠玉，环堵但柴荆。","衰老悲人世，驱驰厭甲兵。","氣春江上別，泪血渭陽情。","舟鷁排风影，林烏反哺声。","永嘉多北至，句漏且南征。","必见公侯复，終闻盜賊平。","郴州頗涼冷，橘井尚淒清。","從役何蠻貊，居官志在行。"]', '诗', 'shi', '', NULL, '奉送二十三舅錄事之攝郴州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b45a58ee-882c-4e39-bebc-3792c8e2e5de', '送魏二十四司直充嶺南掌選崔郎中判官兼寄韋韶州', '送魏二十四司直充嶺南掌選崔郎中判官兼寄韋韶州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["選曹分五嶺，使者歷三湘。","才美膺推薦，君行佐紀綱。","佳聲斯共遠，雅節在周防。","明白山濤鑒，嫌疑陸賈裝。","故人湖外少，春日嶺南長。","憑報韶州牧，新詩昨寄將。"]', '["選曹分五嶺，使者歷三湘。","才美膺推薦，君行佐紀綱。","佳声斯共远，雅節在周防。","明白山濤鑒，嫌疑陸賈裝。","故人湖外少，春日嶺南长。","憑報韶州牧，新诗昨寄將。"]', '诗', 'shi', '', NULL, '送魏二十四司直充嶺南掌選崔郎中判官兼寄韋韶州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1371127c-6ab6-4316-ba07-ef52b37e5b27', '送趙十七明府之縣', '送趙十七明府之縣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["連城爲寶重，茂宰得才新。","山雉迎舟楫，江花報邑人。","論交飜恨晚，臥病却愁春。","惠愛南翁悅，餘波及老身。"]', '["連城爲寶重，茂宰得才新。","山雉迎舟楫，江花報邑人。","論交飜恨晚，臥病却愁春。","惠愛南翁悅，餘波及老身。"]', '诗', 'shi', '', NULL, '送趙十七明府之縣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e8cd22-8ed0-407b-a20a-8c4650f1fa2e', '燕子來舟中作', '燕子来舟中作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["湖南爲客動經春，燕子銜泥兩度新。","舊入故園常識主，如今社日遠看人。","可憐處處巢君室，何異飄飄託此身。","暫語船檣還起去，穿花落水益霑巾。"]', '["湖南爲客动經春，燕子銜泥兩度新。","旧入故园常識主，如今社日远看人。","可怜处处巢君室，何異飄飄託此身。","暫語船檣還起去，穿花落水益霑巾。"]', '诗', 'shi', '', NULL, '燕子來舟中作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd75f98-26ab-4171-91bc-3aa9e979bae2', '同豆盧峰知字韻', '同豆盧峰知字韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["煉金歐冶子，噴玉大宛兒。","符彩高無敵，聰明達所爲。","夢蘭他日應，折桂早年知。","爛漫通經術，光芒刷羽儀。","謝庭瞻不遠，潘省會於斯。","倡和將雛曲，田翁號鹿皮。"]', '["煉金歐冶子，噴玉大宛兒。","符彩高無敵，聰明達所爲。","梦蘭他日應，折桂早年知。","爛漫通經術，光芒刷羽儀。","謝庭瞻不远，潘省會於斯。","倡和將雛曲，田翁號鹿皮。"]', '诗', 'shi', '', NULL, '同豆盧峰知字韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c45810-1845-4140-ac61-bb875c8a6488', '歸雁二首 一', '归雁二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里衡陽雁，今年又北歸。","雙雙瞻客上，一一背人飛。","雲裏相呼疾，沙邊自宿稀。","繫書元浪語，愁寂故山薇。"]', '["万里衡陽雁，今年又北归。","雙雙瞻客上，一一背人飞。","云裏相呼疾，沙邊自宿稀。","繫书元浪語，愁寂故山薇。"]', '诗', 'shi', '', NULL, '歸雁二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba246a1-13b5-432c-a91b-d3b963150a9f', '歸雁二首 二', '归雁二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["欲雪違胡地，先花別楚雲。","却過清渭影，高起洞庭羣。","塞北春陰暮，江南日色曛。","傷弓流落羽，行斷不堪聞。"]', '["欲雪違胡地，先花別楚云。","却過清渭影，高起洞庭羣。","塞北春陰暮，江南日色曛。","傷弓流落羽，行斷不堪闻。"]', '诗', 'shi', '', NULL, '歸雁二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6be3e45-97f6-4b6e-a61a-860fb324b6a1', '小寒食舟中作', '小寒食舟中作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["佳辰強飯食猶寒，隱几蕭條帶鶡冠。","春水船如天上坐，老年花似霧中看。","娟娟戲蝶過閑幔，片片輕鷗下急湍。","雲白山清萬餘里，愁看直北是長安。"]', '["佳辰強飯食猶寒，隐几蕭條带鶡冠。","春水船如天上坐，老年花似霧中看。","娟娟戲蝶過闲幔，片片轻鷗下急湍。","云白山清万餘里，愁看直北是长安。"]', '诗', 'shi', '', NULL, '小寒食舟中作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69f9c09-d812-4d6a-9650-bbbbcad29caa', '清明二首 一', '清明二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝來新火起新煙，湖色春光淨客船。","繡羽銜花他自得，紅顏騎竹我無緣。","胡童結束還難有，楚女腰肢亦可憐。","不見定王城舊處，長懷賈傅井依然。","虛霑焦舉爲寒食，實藉嚴君賣卜錢。","鐘鼎山林各天性，濁醪粗飯任吾年。"]', '["朝来新火起新煙，湖色春光淨客船。","繡羽銜花他自得，紅顏騎竹我無緣。","胡童結束還难有，楚女腰肢亦可怜。","不见定王城旧处，长懷賈傅井依然。","虛霑焦舉爲寒食，實藉嚴君賣卜錢。","鐘鼎山林各天性，濁醪粗飯任吾年。"]', '诗', 'shi', '', NULL, '清明二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a2e26b-5799-453b-bdc1-16b870e092be', '清明二首 二', '清明二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此身飄泊苦西東，右臂偏枯半耳聾。","寂寂繫舟雙下淚，悠悠伏枕左書空。","十年蹴鞠將雛遠，萬里鞦韆習俗同。","旅雁上雲歸紫塞，家人鑽火用青楓。","秦城樓閣煙花裏，漢主山河錦繡中。","風水春來洞庭闊，白蘋愁殺白頭翁。"]', '["此身飄泊苦西东，右臂偏枯半耳聾。","寂寂繫舟雙下泪，悠悠伏枕左书空。","十年蹴鞠將雛远，万里鞦韆習俗同。","旅雁上云归紫塞，家人鑽火用青楓。","秦城楼閣煙花裏，漢主山河錦繡中。","风水春来洞庭闊，白蘋愁殺白头翁。"]', '诗', 'shi', '', NULL, '清明二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3ceb31-3ce5-4708-850f-842ed8edd31d', '發潭州', '發潭州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夜醉長沙酒，曉行湘水春。","岸花飛送客，檣燕語留人。","賈傅才未有，褚公書絕倫。","高名前後事，回首一傷神。"]', '["夜醉长沙酒，晓行湘水春。","岸花飞送客，檣燕語留人。","賈傅才未有，褚公书絕倫。","高名前後事，回首一傷神。"]', '诗', 'shi', '', NULL, '發潭州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba35e31-8786-4ebb-889d-f33293bbaf67', '迴櫂', '迴櫂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宿昔試安命，自私猶畏天。","勞生繫一物，爲客費多年。","衡岳江湖大，蒸池疫癘偏。","散才嬰薄俗，有跡負前賢。","巾拂那關眼，缾罍易滿船。","火雲滋垢膩，凍雨裛沈緜。","強飯蓴添滑，端居茗續煎。","清思漢水上，涼憶峴山巔。","順浪飜堪倚，迴帆又省牽。","吾家碑不昧，王氏井依然。","几杖將衰齒，茅茨寄短椽。","灌園曾取適，遊寺可終焉。","遂性同漁父，成名異魯連。","篙師煩爾送，朱夏及寒泉。"]', '["宿昔試安命，自私猶畏天。","勞生繫一物，爲客費多年。","衡岳江湖大，蒸池疫癘偏。","散才嬰薄俗，有跡負前賢。","巾拂那关眼，缾罍易满船。","火云滋垢膩，凍雨裛沈緜。","強飯蓴添滑，端居茗續煎。","清思漢水上，涼憶峴山巔。","順浪飜堪倚，迴帆又省牽。","吾家碑不昧，王氏井依然。","几杖將衰齒，茅茨寄短椽。","灌园曾取適，游寺可終焉。","遂性同漁父，成名異魯連。","篙師煩爾送，朱夏及寒泉。"]', '诗', 'shi', '', NULL, '迴櫂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('896165e9-c6f3-47f5-ad08-591f4c291630', '贈韋七贊善', '贈韋七贊善', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄉里衣冠不乏賢，杜陵韋曲未央前。","爾家最近魁三象，時論同歸尺五天。","北走關山開雨雪，南遊花柳塞雲煙。","洞庭春色悲公子，鰕菜忘歸范蠡船。"]', '["乡里衣冠不乏賢，杜陵韋曲未央前。","爾家最近魁三象，时論同归尺五天。","北走关山开雨雪，南游花柳塞云煙。","洞庭春色悲公子，鰕菜忘归范蠡船。"]', '诗', 'shi', '', NULL, '贈韋七贊善 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce32eb67-b007-4a04-a668-49445c5b2fd3', '奉酬寇十侍御錫見寄四韻復寄寇', '奉酬寇十侍御錫见寄四韻复寄寇', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["往別郇瑕地，於今四十年。","來簪御府筆，故泊洞庭船。","詩憶傷心處，春深把臂前。","南瞻按百越，黃帽待君偏。"]', '["往別郇瑕地，於今四十年。","来簪御府笔，故泊洞庭船。","诗憶傷心处，春深把臂前。","南瞻按百越，黄帽待君偏。"]', '诗', 'shi', '', NULL, '奉酬寇十侍御錫見寄四韻復寄寇 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a23a71-eaa5-4494-9c16-f3fd44546508', '酬郭十五受判官', '酬郭十五受判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["才微歲老尚虛名，臥病江湖春復生。","藥裹關心詩總廢，花枝照眼句還成。","只同燕石能星隕，自得隋珠覺夜明。","喬口橘洲風浪促，繫帆何惜片時程。"]', '["才微歲老尚虛名，臥病江湖春复生。","藥裹关心诗總廢，花枝照眼句還成。","只同燕石能星隕，自得隋珠覺夜明。","喬口橘洲风浪促，繫帆何惜片时程。"]', '诗', 'shi', '', NULL, '酬郭十五受判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f52da7a-9e85-4077-8b9f-88f1abdaf274', '衡州送李大夫七丈勉赴廣州', '衡州送李大夫七丈勉赴廣州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["斧鉞下青冥，樓船過洞庭。","北風隨爽氣，南斗避文星。","日月籠中鳥，乾坤水上萍。","王孫丈人行，垂老見飄零。"]', '["斧鉞下青冥，楼船過洞庭。","北风隨爽氣，南斗避文星。","日月籠中鸟，乾坤水上萍。","王孫丈人行，垂老见飄零。"]', '诗', 'shi', '', NULL, '衡州送李大夫七丈勉赴廣州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73268d2-ab46-4887-9379-915c053146fc', '哭長孫侍御', '哭长孫侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["道爲謀書重，名因賦頌雄。","禮闈曾擢桂，憲府舊乘驄。","流水生涯盡，浮雲世事空。","唯餘舊臺柏，蕭瑟九原中。"]', '["道爲謀书重，名因賦頌雄。","禮闈曾擢桂，憲府旧乘驄。","流水生涯尽，浮云世事空。","唯餘旧台柏，蕭瑟九原中。"]', '诗', 'shi', '', NULL, '哭長孫侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15180235-db35-499b-8fd5-b8d9fa92f5f2', '虢國夫人', '虢国夫人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["虢國夫人承主恩，平明上馬入宮門。","却嫌脂粉涴顏色，澹埽蛾眉朝至尊。"]', '["虢国夫人承主恩，平明上马入宮门。","却嫌脂粉涴顏色，澹埽蛾眉朝至尊。"]', '诗', 'shi', '', NULL, '虢國夫人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4a274a-df2c-4bab-b123-7d210259b37c', '軍中醉飲寄沈八劉叟', '軍中醉饮寄沈八劉叟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["酒渴愛江清，餘甘漱晚汀。","輭沙欹坐穩，冷石醉眠醒。","野膳隨行帳，華音發從伶。","數杯君不見，醉已遣沈冥。"]', '["酒渴愛江清，餘甘漱晚汀。","輭沙欹坐穩，冷石醉眠醒。","野膳隨行帳，华音發從伶。","數杯君不见，醉已遣沈冥。"]', '诗', 'shi', '', NULL, '軍中醉飲寄沈八劉叟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a8d640-d4a1-4c79-ae07-b67a36e5761c', '杜鵑行', '杜鵑行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["古時杜宇稱望帝，魂作杜鵑何微細。","跳枝竄葉樹木中，搶佯瞥捩雌隨雄。","毛衣慘黑貌顦顇，衆鳥安肯相尊崇。","隳形不敢棲華屋，短翮唯願巢深叢。","穿皮啄朽觜欲禿，苦飢始得食一蟲。","誰言養雛不自哺，此語亦足爲愚蒙。","聲音咽咽如有謂，號啼略與嬰兒同。","口乾垂血轉迫促，似欲上訴於蒼穹。","蜀人聞之皆起立，至今斅學傳遺風。","迺知變化不可窮，豈知昔日居深宮，嬪嬙左右如花紅。"]', '["古时杜宇稱望帝，魂作杜鵑何微細。","跳枝竄葉樹木中，搶佯瞥捩雌隨雄。","毛衣慘黑貌顦顇，衆鸟安肯相尊崇。","隳形不敢棲华屋，短翮唯願巢深叢。","穿皮啄朽觜欲禿，苦飢始得食一蟲。","誰言養雛不自哺，此語亦足爲愚蒙。","声音咽咽如有謂，號啼略與嬰兒同。","口乾垂血轉迫促，似欲上訴於蒼穹。","蜀人闻之皆起立，至今斅学傳遺风。","迺知变化不可窮，豈知昔日居深宮，嬪嬙左右如花紅。"]', '诗', 'shi', '', NULL, '杜鵑行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d096967-8741-47e1-99f9-41e41c03f829', '聞惠二過東溪特一送', '闻惠二過东溪特一送', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["惠子白駒瘦，歸溪唯病身。","皇天無老眼，空谷滯斯人。","崖蜜松花熟，山杯竹葉新。","柴門了無事，黃綺未稱臣。"]', '["惠子白駒瘦，归溪唯病身。","皇天無老眼，空谷滯斯人。","崖蜜松花熟，山杯竹葉新。","柴门了無事，黄綺未稱臣。"]', '诗', 'shi', '', NULL, '聞惠二過東溪特一送 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643603e3-ff0c-43b7-942b-e2348da428ab', '舟泛洞庭', '舟泛洞庭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蛟室圍青草，龍堆擁白沙。","護江盤古木，迎櫂舞神鵶。","破浪南風正，收颿畏日斜。","雲山千萬疊，底處上仙槎。"]', '["蛟室圍青草，龙堆擁白沙。","護江盤古木，迎櫂舞神鵶。","破浪南风正，收颿畏日斜。","云山千万叠，底处上仙槎。"]', '诗', 'shi', '', NULL, '舟泛洞庭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f666ee1-3c05-4695-9cfd-8b4d02d4c418', '李鹽鐵二首', '李鹽鐵二首', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落葉春風起，高城煙霧開。","雜花分戶映，嬌燕入檐回。","一見能傾產，虛懷只愛才。","鹽官雖絆驥，名是漢庭來。"]', '["落葉春风起，高城煙霧开。","杂花分戶映，嬌燕入檐回。","一见能傾產，虛懷只愛才。","鹽官雖絆驥，名是漢庭来。"]', '诗', 'shi', '', NULL, '李鹽鐵二首 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da4aba0f-2770-4a59-9050-7e2688d8f1fa', '長吟', '长吟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江渚飜鷗戲，官橋帶柳陰。","江飛兢渡日，草見蹋春心。","已撥形骸累，真爲爛漫深。","賦詩歌句穩，不免自長吟。"]', '["江渚飜鷗戲，官橋带柳陰。","江飞兢渡日，草见蹋春心。","已撥形骸累，真爲爛漫深。","賦诗歌句穩，不免自长吟。"]', '诗', 'shi', '', NULL, '長吟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ffa5316-14cd-4eb2-b4ea-075621799298', '絕句九首 七', '絕句九首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道巴山裏，春船正好行。","都將百年興，一望九江城。"]', '["闻道巴山裏，春船正好行。","都將百年兴，一望九江城。"]', '诗', 'shi', '', NULL, '絕句九首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9113337c-c93a-497c-ac46-39ad99d6b908', '絕句九首 八', '絕句九首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["水檻溫江口，茅堂石筍西。","移船先主廟，洗藥淙沙溪。"]', '["水檻溫江口，茅堂石筍西。","移船先主廟，洗藥淙沙溪。"]', '诗', 'shi', '', NULL, '絕句九首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c772f5-e6c7-4b3c-9902-1a0af8e8255c', '絕句九首 九', '絕句九首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["設道春來好，狂風大放顛。","吹花隨水去，飜却釣魚船。"]', '["設道春来好，狂风大放顛。","吹花隨水去，飜却釣鱼船。"]', '诗', 'shi', '', NULL, '絕句九首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1fc7f2-defc-46cc-b791-647abb1f381c', '瞿唐懷古', '瞿唐懷古', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西南萬壑注，勍敵兩崖[開]。","地與山根裂，江從月窟來。","削成當白帝，空曲隱陽臺。","疏鑿功雖美，陶鈞力大哉。"]', '["西南万壑注，勍敵兩崖[开]。","地與山根裂，江從月窟来。","削成當白帝，空曲隐陽台。","疏鑿功雖美，陶鈞力大哉。"]', '诗', 'shi', '', NULL, '瞿唐懷古 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeeb99c7-6fe4-4535-af24-9581d92aa264', '送司馬入京', '送司马入京', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣盜至今日，先朝忝從臣。","歎君能戀主，久客羨歸秦。","黃閣長司諫，丹墀有故人。","向來論社稷，爲話涕霑巾。"]', '["羣盜至今日，先朝忝從臣。","歎君能戀主，久客羨归秦。","黄閣长司諫，丹墀有故人。","向来論社稷，爲話涕霑巾。"]', '诗', 'shi', '', NULL, '送司馬入京 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184965e8-dd83-4699-afb1-eac6f8211dab', '惜別行送劉僕射判官', '惜別行送劉僕射判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道南行市駿馬，不限匹數軍中須。","襄陽幕府天下異，主將儉省憂艱虞。","祗收壯健勝鐵甲，豈因格鬬求龍駒。","而今西北自反胡，騏驎蕩盡一匹無。","龍媒真種在帝都，子孫永落西南隅。","向非戎事備征伐，君肯辛苦越江湖。","江湖凡馬多顦顇，衣冠往往乘蹇驢。","梁公富貴於身疎，號令明白人安居。","俸錢時散士子盡，府庫不爲驕豪虛。","以茲報主寸心赤，氣却西戎迴北狄。","羅網羣馬籍馬多，氣在驅馳出金帛。","劉侯奉使光推擇，滔滔才略滄溟窄。","杜陵老翁秋繫船，扶病相識長沙驛。","強梳白髮提胡盧，手把菊花路旁摘。","九州兵革浩茫茫，三歎聚散臨重陽。","當杯對客忍流涕，君不覺老夫神內傷。"]', '["闻道南行市駿马，不限匹數軍中須。","襄陽幕府天下異，主將儉省憂艱虞。","祗收壯健勝鐵甲，豈因格鬬求龙駒。","而今西北自反胡，騏驎蕩尽一匹無。","龙媒真種在帝都，子孫永落西南隅。","向非戎事備征伐，君肯辛苦越江湖。","江湖凡马多顦顇，衣冠往往乘蹇驢。","梁公富貴於身疎，號令明白人安居。","俸錢时散士子尽，府庫不爲驕豪虛。","以茲報主寸心赤，氣却西戎迴北狄。","羅網羣马籍马多，氣在驱驰出金帛。","劉侯奉使光推擇，滔滔才略滄溟窄。","杜陵老翁秋繫船，扶病相識长沙驛。","強梳白髮提胡盧，手把菊花路旁摘。","九州兵革浩茫茫，三歎聚散臨重陽。","當杯对客忍流涕，君不覺老夫神內傷。"]', '诗', 'shi', '', NULL, '惜別行送劉僕射判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5aac1dd-2ab0-4f0e-a47b-279c683b6c52', '呀鶻行', '呀鶻行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["病鶻孤飛俗眼醜，每夜江邊宿衰柳。","清秋落日已側身，過雁歸鵶錯回首。","緊腦雄姿迷所向，疎翮稀毛不可狀。","強神迷復皁雕前，俊才早在蒼鷹上。","風濤颯颯寒山陰，熊羆欲蟄龍蛇深。","念爾此時有一擲，失聲濺血非其心。"]', '["病鶻孤飞俗眼醜，每夜江邊宿衰柳。","清秋落日已側身，過雁归鵶錯回首。","緊腦雄姿迷所向，疎翮稀毛不可狀。","強神迷复皁雕前，俊才早在蒼鷹上。","风濤颯颯寒山陰，熊羆欲蟄龙蛇深。","念爾此时有一擲，失声濺血非其心。"]', '诗', 'shi', '', NULL, '呀鶻行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21009cf8-00ea-4825-a9a4-87bccedba515', '狂歌行贈四兄', '狂歌行贈四兄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["與兄行年校一歲，賢者是兄愚者弟。","兄將富貴等浮雲，弟切功名好權勢。","長安秋雨十日泥，我曹鞴馬聽晨雞。","公卿朱門未開鎖，我曹已到肩相齊。","吾兄睡穩方舒膝，不襪不巾蹋曉日。","男啼女哭莫我知，身上須繒腹中實。","今年思我來嘉州，嘉州酒重花繞樓。","樓頭喫酒樓下臥，長歌短詠還相酬。","四時八節還拘禮，女拜弟妻男拜弟。","幅巾鞶帶不挂身，頭脂足垢何曾洗。","吾兄吾兄巢許倫，一生喜怒長任真。"]', '["與兄行年校一歲，賢者是兄愚者弟。","兄將富貴等浮云，弟切功名好權勢。","长安秋雨十日泥，我曹鞴马听晨雞。","公卿朱门未开鎖，我曹已到肩相齊。","吾兄睡穩方舒膝，不襪不巾蹋晓日。","男啼女哭莫我知，身上須繒腹中實。","今年思我来嘉州，嘉州酒重花繞楼。","楼头喫酒楼下臥，长歌短詠還相酬。","四时八節還拘禮，女拜弟妻男拜弟。","幅巾鞶带不挂身，头脂足垢何曾洗。","吾兄吾兄巢許倫，一生喜怒长任真。"]', '诗', 'shi', '', NULL, '狂歌行贈四兄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39196f1-babc-4cb4-9bad-92f4006f6d36', '逃難', '逃难', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五十頭白翁，南北逃世難。","疎布纏枯骨，奔走苦不暖。","已衰病方入，四海一塗炭。","乾坤萬里內，莫見容身畔。","妻孥復隨我，回首共悲歡。","故國莽丘墟，鄰里各分散。","歸路從此迷，涕盡湘江岸。"]', '["五十头白翁，南北逃世难。","疎布纏枯骨，奔走苦不暖。","已衰病方入，四海一塗炭。","乾坤万里內，莫见容身畔。","妻孥复隨我，回首共悲歡。","故国莽丘墟，鄰里各分散。","归路從此迷，涕尽湘江岸。"]', '诗', 'shi', '', NULL, '逃難 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936e5e7b-7a5d-4e5c-b021-cd3079c05b6a', '寄高適', '寄高適', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楚隔乾坤遠，難招病客魂。","詩名惟我共，世事與誰論。","北闕更新主，南星落故園。","定知相見日，爛漫倒芳尊。"]', '["楚隔乾坤远，难招病客魂。","诗名惟我共，世事與誰論。","北闕更新主，南星落故园。","定知相见日，爛漫倒芳尊。"]', '诗', 'shi', '', NULL, '寄高適 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2de4bc-ee96-4ec0-bed4-16541c2dd2c0', '送靈州李判官', '送靈州李判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["犬戎腥四海，回首一茫茫。","血戰乾坤赤，氛迷日月黃。","將軍專策略，幕府盛材良。","近賀中興主，神兵動朔方。"]', '["犬戎腥四海，回首一茫茫。","血戰乾坤赤，氛迷日月黄。","將軍專策略，幕府盛材良。","近賀中兴主，神兵动朔方。"]', '诗', 'shi', '', NULL, '送靈州李判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3a2178-4382-4532-9f74-3c8fc5a8e629', '與嚴二郎奉禮別', '與嚴二郎奉禮別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["別君誰暖眼，將老病纏身。","出涕同斜日，臨風看去塵。","商歌還入夜，巴俗自爲鄰。","尚媿微軀在，遙聞盛禮新。","山東羣盜散，闕下受降頻。","諸將歸應盡，題書報旅人。"]', '["別君誰暖眼，將老病纏身。","出涕同斜日，臨风看去塵。","商歌還入夜，巴俗自爲鄰。","尚媿微軀在，遙闻盛禮新。","山东羣盜散，闕下受降頻。","諸將归應尽，題书報旅人。"]', '诗', 'shi', '', NULL, '與嚴二郎奉禮別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a318610a-56a2-4c5c-a4f3-337085962bd4', '巴西驛亭觀江漲呈竇使君二首 一', '巴西驛亭观江漲呈竇使君二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["轉驚波作怒，即恐岸隨流。","賴有杯中物，還同海上鷗。","關心小剡縣，傍眼見揚州。","爲接情人飲，朝來減半愁。"]', '["轉驚波作怒，即恐岸隨流。","賴有杯中物，還同海上鷗。","关心小剡縣，傍眼见揚州。","爲接情人饮，朝来減半愁。"]', '诗', 'shi', '', NULL, '巴西驛亭觀江漲呈竇使君二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d955a6e-82ab-4336-848e-80d4d0c52227', '巴西驛亭觀江漲呈竇使君二首 二', '巴西驛亭观江漲呈竇使君二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["向晚波微綠，連空岸脚青。","日兼春有暮，愁與醉無醒。","漂泊猶杯酒，躊躇此驛亭。","相看萬里外，同是一浮萍。"]', '["向晚波微綠，連空岸脚青。","日兼春有暮，愁與醉無醒。","漂泊猶杯酒，躊躇此驛亭。","相看万里外，同是一浮萍。"]', '诗', 'shi', '', NULL, '巴西驛亭觀江漲呈竇使君二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6fc326-de20-4ee9-a355-a79c523d55d1', '遣憂', '遣憂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亂離知又甚，消息苦難真。","受諫無今日，臨危憶古人。","紛紛乘白馬，攘攘著黃巾。","隋氏留宮室，焚燒何太頻。"]', '["亂離知又甚，消息苦难真。","受諫無今日，臨危憶古人。","紛紛乘白马，攘攘著黄巾。","隋氏留宮室，焚燒何太頻。"]', '诗', 'shi', '', NULL, '遣憂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388bec3c-e7e4-44f2-99f2-f8dfe5a2daba', '早花', '早花', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西京安穩未，不見一人來。","臘日巴江曲，山花已自開。","盈盈當雪杏，豔豔待春梅。","直苦風塵暗，誰憂容鬢催。"]', '["西京安穩未，不见一人来。","臘日巴江曲，山花已自开。","盈盈當雪杏，豔豔待春梅。","直苦风塵暗，誰憂容鬢催。"]', '诗', 'shi', '', NULL, '早花 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b969e7b-3472-43b2-a137-dbe434043411', '巴山', '巴山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巴山遇中使，云自峽城來。","盜賊還奔突，乘輿恐未回。","天寒邵伯樹，地闊望仙臺。"]', '["巴山遇中使，云自峽城来。","盜賊還奔突，乘輿恐未回。","天寒邵伯樹，地闊望仙台。"]', '诗', 'shi', '', NULL, '巴山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68b787e3-af74-4a3b-961b-7b01295dc800', '收京', '收京', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["復道收京邑，兼聞殺犬戎。","衣冠却扈從，車架已還宮。","克復成如此，安危在數公。","莫令回首地，慟哭起悲風。"]', '["复道收京邑，兼闻殺犬戎。","衣冠却扈從，车架已還宮。","克复成如此，安危在數公。","莫令回首地，慟哭起悲风。"]', '诗', 'shi', '', NULL, '收京 杜甫 shi');
